        0: "solo_responde",
        1: "sugiere_acciones",
        2: "tools_seguras",
        3: "tools_con_monitoreo",
        4: "requiere_aprobacion",
        5: "cuarentena_solo_lectura",
    }

    def evaluate(self, current_level: int, decision: GuardDecision) -> int:
        risk = decision.risk_score
