    return datetime.now(timezone.utc).isoformat()


@dataclass
class CognitiveEvent:
    event_type: str
    agent_id: str
    user_id: str = "anonymous"
    content: Any = None
    source: str = "unknown"
    target: str = "unknown"
    session_id: str = "default"
    metadata: Dict[str, Any] = field(default_factory=dict)
