from pathlib import Path
from typing import Any, Dict, List
from cyberlace.utils.yaml_loader import safe_load


class PolicyEngine:
    def __init__(self, policy_path: str | Path | None = None):
        self.policy_path = Path(policy_path) if policy_path else Path(__file__).parents[1] / "policies" / "default_policies.yaml"
        self.policies = self._load()

    def _load(self) -> Dict[str, Any]:
        if not self.policy_path.exists():
            return {"policies": {}}
        with self.policy_path.open("r", encoding="utf-8") as f:
            return safe_load(f) or {"policies": {}}

    def evaluate(self, facts: Dict[str, Any]) -> List[Dict[str, Any]]:
        matches = []
        for name, policy in self.policies.get("policies", {}).items():
            when = policy.get("when", {})
            if self._match_when(when, facts):
                matches.append({
                    "name": name,
                    "description": policy.get("description", ""),
                    "then": policy.get("then", {}),
                })
        return matches

    def _match_when(self, when: Dict[str, Any], facts: Dict[str, Any]) -> bool:
        for key, expected in when.items():
            if key == "risk_gte":
                if float(facts.get("risk_score", 0)) < float(expected):
                    return False
                continue

            actual = facts.get(key)
            if isinstance(expected, list):
                if isinstance(actual, list):
                    if not any(x in expected for x in actual):
                        return False
                elif actual not in expected:
                    return False
            else:
                if actual != expected:
                    return False
        return True

from typing import Dict, Any


class RiskEngine:
    def __init__(self, weights: Dict[str, float] | None = None):
        self.weights = weights or {
            "prompt": 0.20,
            "memory": 0.20,
            "tool": 0.20,
            "context": 0.15,
            "behavior": 0.10,
            "autonomy": 0.10,
            "output": 0.05,
        }

    def severity(self, score: float) -> str:
        if score >= 76:
            return "CRITICAL"
        if score >= 51:
            return "HIGH"
        if score >= 21:
            return "MEDIUM"
        return "LOW"

    def combine(self, scores: Dict[str, float]) -> float:
        total_weight = 0.0
        total = 0.0
        for key, value in scores.items():
            w = float(self.weights.get(key, 0.0))
            total += float(value) * w
            total_weight += w
        if total_weight <= 0:
            return max(scores.values()) if scores else 0.0
        return round(total / total_weight, 2)

from typing import Dict, Any, List
from cyberlace.core.models import GuardDecision


class SemanticFirewall:
    def decide(self, decisions: List[GuardDecision], mode: str = "monitor") -> GuardDecision:
        if not decisions:
            return GuardDecision(
                allowed=True,
                action="ALLOW",
                risk_score=0,
                severity="LOW",
                reason="Sin señales de riesgo",
                category="semantic_firewall",
            )

        max_risk = max(d.risk_score for d in decisions)
        evidence = []
        categories = []
        for d in decisions:
            evidence.extend(d.evidence)
            categories.append(d.category)

        if mode == "off":
            return GuardDecision(True, "ALLOW", 0, "LOW", "CyberLACE apagado", "semantic_firewall")

        if mode == "monitor":
            return GuardDecision(
                allowed=True,
                action="MONITOR",
                risk_score=max_risk,
                severity=self._severity(max_risk),
                reason="Modo monitor: se registra riesgo sin bloquear",
                category="semantic_firewall",
                evidence=evidence,
            )

        if max_risk >= 90:
            action, allowed = "QUARANTINE", False
        elif max_risk >= 80:
            action, allowed = "BLOCK", False
        elif max_risk >= 60:
            action, allowed = "HUMAN_REVIEW", False
        elif max_risk >= 35:
            action, allowed = "MONITOR", True
        else:
            action, allowed = "ALLOW", True

        return GuardDecision(
            allowed=allowed,
            action=action,
            risk_score=max_risk,
            severity=self._severity(max_risk),
            reason=f"Decisión semántica basada en riesgo {max_risk}",
            category="semantic_firewall",
            evidence=evidence,
            confidence=max(d.confidence for d in decisions),
        )

    def _severity(self, risk: float) -> str:
        if risk >= 76:
            return "CRITICAL"
        if risk >= 51:
            return "HIGH"
        if risk >= 21:
            return "MEDIUM"
        return "LOW"

