def _inspect_text(text: str, *, source: str, path: str | None = None) -> List[Dict[str, Any]]:
    findings: List[Dict[str, Any]] = []
    for hit in find_sensitive(text or ""):
        if _should_block_hit(hit, text or ""):
            findings.append(_sanitize_hit(hit, text or "", source=source, path=path))
    findings.extend(_fragmented_secret_findings(text or "", source=source, path=path))
    findings.extend(_unsafe_payment_intent_findings(text or "", source=source, path=path))
    findings.extend(_unsafe_external_login_intent_findings(text or "", source=source, path=path))
    findings.extend(_persisted_prompt_injection_findings(text or "", source=source, path=path))
    findings.extend(_obfuscated_secret_findings(text or "", source=source, path=path))
    return findings


def _walk_values(value: Any) -> Iterable[str]:
    if value is None:
        return
    if isinstance(value, str):
        yield value
        return
    if isinstance(value, dict):
        for item in value.values():
            yield from _walk_values(item)
        return
    if isinstance(value, (list, tuple, set)):
        for item in value:
            yield from _walk_values(item)
        return
    yield str(value)


def _extract_path_tokens(text: str) -> List[str]:
    tokens: List[str] = []
    for pattern in (PATH_TOKEN_RE, SENSITIVE_FILENAME_TOKEN_RE):
        for match in pattern.finditer(text or ""):
            token = match.group("path").strip().strip("`'\"()[]{}<>.,;:")
            if not token or "://" in token:
                continue
            if token not in tokens:
                tokens.append(token)
    return tokens


def _is_relative_to(path: Path, root: Path) -> bool:
    try:
        path.relative_to(root)
        return True
    except ValueError:
        return False


def _safe_display_path(path: Path, *, repo: Path, project_root: Path) -> str:
    try:
        return path.relative_to(repo).as_posix()
    except ValueError:
        try:
            return path.relative_to(project_root).as_posix()
        except ValueError:
            return path.name


def _is_generated_runtime_control_reference(path: Path, roots: List[Path], *, source: str) -> bool:
    if source not in {"task", "directive"}:
        return False
    for root in roots:
        try:
            relative = path.relative_to(root)
        except ValueError:
            continue
        parts = relative.parts
        for index, part in enumerate(parts[:-1]):
            if part != "runtime":
                continue
            next_part = parts[index + 1]
            if index + 2 == len(parts) and next_part in TRUSTED_RUNTIME_CONTROL_FILES:
                return True
            if next_part in TRUSTED_RUNTIME_CONTROL_DIRS:
                return True
    return False


def _matches_prefix(parts: tuple[str, ...], prefixes: tuple[tuple[str, ...], ...]) -> bool:
    return any(parts[:len(prefix)] == prefix for prefix in prefixes)


def _is_trusted_repo_reference(path: Path, roots: List[Path], *, source: str) -> bool:
    if source not in TRUSTED_GENERATED_SOURCES or len(roots) < 2:
        return False
    resolved = path.resolve()
    project_root = roots[0].resolve()
    repo = roots[-1].resolve()
    if _is_relative_to(resolved, project_root):
        return False
    try:
        relative = resolved.relative_to(repo)
    except ValueError:
        return False

    name = resolved.name.lower()
    if name in SENSITIVE_TEXT_FILENAMES or name.startswith("id_"):
        return False

    parts = relative.parts
    if len(parts) == 1 and parts[0] in TRUSTED_REPO_REFERENCE_FILES:
        return True
    if _matches_prefix(parts, TRUSTED_REPO_SOURCE_DIR_PREFIXES):
        return True
    if source in {"task", "directive"} and _matches_prefix(parts, TRUSTED_REPO_POLICY_DIR_PREFIXES):
        return True
    return False


def _external_reference_finding(token: str, *, source: str) -> Dict[str, Any]:
    raw_name = Path(token.replace("~", "")).name or "external"
    return {
        "type": "external_document_reference_denied",
        "source": source,
        "path": f"external:{raw_name}",
        "pattern": "external_path",
        "domain": "filesystem",
        "line": 1,
        "sample": "[REDACTED]",
    }


def _scan_limit_finding(*, reason: str, path: str | None = None) -> Dict[str, Any]:
    return {
        "type": "workspace_scan_incomplete",
        "source": "workspace_preflight",
        "path": path,
        "pattern": reason,
        "domain": "filesystem",
        "line": 1,
        "sample": "[REDACTED]",
    }


def _is_text_document(path: Path) -> bool:
    name = path.name.lower()
    return name in SENSITIVE_TEXT_FILENAMES or path.suffix.lower() in TEXT_SUFFIXES


def _read_text_document(path: Path) -> str | None:
    if not _is_text_document(path):
        return None
    try:
        if path.stat().st_size > MAX_DOCUMENT_SCAN_BYTES:
            return None
        return path.read_text(encoding="utf-8", errors="ignore")
    except OSError:
        return None


def _is_trusted_project_control_document(display_path: str) -> bool:
    normalized = str(display_path or "").replace("\\", "/").lstrip("/")
    parts = normalized.split("workspace/projects/", 1)
    if len(parts) == 2:
        tail = parts[1].split("/", 1)
        normalized = tail[1] if len(tail) == 2 else ""
    if normalized in TRUSTED_PROJECT_CONTROL_DOCUMENTS:
        return True
    return any(normalized.startswith(prefix) for prefix in TRUSTED_PROJECT_CONTROL_PREFIXES)


def _inspect_document(path: Path, *, source: str, display_path: str) -> tuple[List[Dict[str, Any]], Dict[str, Any] | None]:
    if not _is_text_document(path):
        return [], None
    try:
        size = path.stat().st_size
    except OSError:
        return [_scan_limit_finding(reason="document_stat_failed", path=display_path)], None
    if _is_trusted_project_control_document(display_path):
        return [], {
            "path": display_path,
            "bytes": size,
            "blockedFindings": 0,
            "trustedRuntimeControl": True,
        }
    if size > MAX_DOCUMENT_SCAN_BYTES:
        return [_scan_limit_finding(reason="document_too_large", path=display_path)], {
            "path": display_path,
            "bytes": size,
            "blockedFindings": 1,
            "skipped": True,
            "reason": "document_too_large",
        }
    text = _read_text_document(path)
    if text is None:
        return [_scan_limit_finding(reason="document_read_failed", path=display_path)], None
    doc_findings = _inspect_text(text, source=source, path=display_path)
    return doc_findings, {
        "path": display_path,
        "bytes": size,
        "blockedFindings": len(doc_findings),
    }


def _resolve_referenced_path(token: str, roots: List[Path]) -> Path | None:
    raw = token.strip().strip("`'\"()[]{}<>.,;:")
    if not raw or "://" in raw:
        return None
    candidate = Path(raw).expanduser()
    resolved_roots = [root.resolve() for root in roots]
    candidates: List[Path]
    if candidate.is_absolute():
        candidates = [candidate]
    else:
        candidates = [root / candidate for root in resolved_roots]
    for item in candidates:
        try:
            resolved = item.resolve()
        except OSError:
            continue
        if not any(_is_relative_to(resolved, root) for root in resolved_roots):
            continue
        if resolved.exists() and resolved.is_file():
            return resolved
    return None


def _path_escapes_roots(path: Path, roots: List[Path]) -> bool:
    return not any(_is_relative_to(path, root) for root in roots)


def _meaningful_external_absolute_path(token: str) -> bool:
    raw = token.strip()
    if raw.startswith("~/") or raw.startswith("../") or bool(re.match(r"^[A-Za-z]:[\\/]", raw)):
        return True
    if not raw.startswith("/"):
        return False
    normalized = raw.replace("\\", "/")
    parts = [part for part in normalized.split("/") if part]
    name = parts[-1].lower() if parts else ""
    has_sensitive_name = name in SENSITIVE_TEXT_FILENAMES or name.startswith("id_")
    has_suffix = bool(Path(normalized).suffix)
    if normalized.startswith(("/home/", "/Users/")):
        return len(parts) >= 4 or has_sensitive_name or has_suffix
    if normalized.startswith("/root/"):
        return len(parts) >= 3 or has_sensitive_name or has_suffix
    if normalized.startswith("/etc/"):
        return len(parts) >= 2
    if normalized.startswith(("/var/", "/tmp/", "/mnt/", "/media/", "/opt/", "/srv/")):
        return len(parts) >= 3 or has_sensitive_name or has_suffix
    return len(parts) >= 2 and has_suffix


def _looks_like_external_path(token: str) -> bool:
    return _meaningful_external_absolute_path(token)


def _collect_paths_for_text(text: str, roots: List[Path], *, source: str) -> tuple[List[Path], List[Dict[str, Any]]]:
    resolved: List[Path] = []
    denied: List[Dict[str, Any]] = []
    seen: set[str] = set()
    resolved_roots = [root.resolve() for root in roots]
    for token in _extract_path_tokens(text):
        raw = token.strip().strip("`'\"()[]{}<>.,;:")
        candidate = Path(raw).expanduser()
        if candidate.is_absolute():
            if not _meaningful_external_absolute_path(raw):
                continue
            try:
                absolute_candidate = candidate.resolve()
            except OSError:
                absolute_candidate = candidate
            if _path_escapes_roots(absolute_candidate, resolved_roots):
                denied.append(_external_reference_finding(raw, source=source))
                continue
        elif _looks_like_external_path(raw):
            denied.append(_external_reference_finding(raw, source=source))
            continue
        path = _resolve_referenced_path(raw, roots)
        if path is None:
            continue
        if _is_generated_runtime_control_reference(path, resolved_roots, source=source):
            continue
        if _is_trusted_repo_reference(path, resolved_roots, source=source):
            continue
        key = str(path)
        if key in seen:
            continue
        seen.add(key)
        resolved.append(path)
        if len(resolved) >= MAX_REFERENCED_DOCUMENTS:
            denied.append(_scan_limit_finding(reason="referenced_document_limit_exceeded"))
            return resolved, denied
    return resolved, denied


def _workspace_document_paths(project_root: Path) -> Iterable[Path]:
    if not project_root.exists() or not project_root.is_dir():
        return
    for dirpath, dirnames, filenames in os.walk(project_root):
        dirnames[:] = [
            dirname for dirname in dirnames
            if dirname not in WORKSPACE_EXCLUDED_DIRS and not dirname.endswith(".egg-info")
        ]
        for filename in filenames:
            path = Path(dirpath) / filename
            if _is_text_document(path):
                yield path


def _inspect_workspace_documents(
    project_root: Path,
    *,
    repo: Path,
    already_scanned: set[str],
) -> tuple[List[Dict[str, Any]], List[Dict[str, Any]], Dict[str, Any]]:
    findings: List[Dict[str, Any]] = []
    scanned_documents: List[Dict[str, Any]] = []
    scanned_count = 0
    scanned_bytes = 0
    incomplete_reason: str | None = None

    for path in _workspace_document_paths(project_root):
        try:
            resolved = path.resolve()
        except OSError:
            continue
        key = str(resolved)
        if key in already_scanned:
            continue
        display_path = _safe_display_path(resolved, repo=repo, project_root=project_root)
        try:
            size = resolved.stat().st_size
        except OSError:
            findings.append(_scan_limit_finding(reason="document_stat_failed", path=display_path))
            continue
        if scanned_count >= MAX_WORKSPACE_DOCUMENTS:
            incomplete_reason = "workspace_document_limit_exceeded"
            break
        if scanned_bytes + size > MAX_TOTAL_WORKSPACE_SCAN_BYTES:
            incomplete_reason = "workspace_byte_limit_exceeded"
            break
        doc_findings, info = _inspect_document(resolved, source="workspace_document", display_path=display_path)
        scanned_count += 1
        scanned_bytes += min(size, MAX_DOCUMENT_SCAN_BYTES)
        findings.extend(doc_findings)
        if info and (doc_findings or len(scanned_documents) < 120):
            scanned_documents.append(info)

    if incomplete_reason:
        findings.append(_scan_limit_finding(reason=incomplete_reason, path=project_root.name))

    return findings, scanned_documents, {
        "documents": scanned_count,
        "bytes": scanned_bytes,
        "incomplete": bool(incomplete_reason),
        "incompleteReason": incomplete_reason,
    }


def inspect_runtime_document_inputs(
    *,
    requirement: str,
    project_dir: str | Path,
    repo_root: str | Path,
    task: Dict[str, Any] | None = None,
    directive: Dict[str, Any] | None = None,
    session_id: str | None = None,
    project_slug: str | None = None,
    scan_workspace: bool = True,
) -> Dict[str, Any]:
    """Inspect prompt/task/directive text, referenced documents, and workspace docs.

    Returns a sanitized CyberLACE-style decision. ``blocked=True`` is a hard stop
    and must be enforced regardless of global CyberLACE monitor/enforce mode.
    """

    project_root = Path(project_dir).resolve()
    repo = Path(repo_root).resolve()
    roots = [project_root, repo]
    text_sources: List[tuple[str, str]] = [("requirement", str(requirement or ""))]
    if task:
        text_sources.append(("task", _safe_string(task)))
    if directive:
        rendered = str(directive.get("rendered_instruction") or "") if isinstance(directive, dict) else ""
        text_sources.append(("directive", rendered or _safe_string(directive)))

    findings: List[Dict[str, Any]] = []
    for source, text in text_sources:
        if source == "directive":
            # Generated directives include trusted AGENTS/PLANS policy text. The
            # untrusted payload is already represented by requirement/task and
            # by referenced/workspace documents below.
            continue
        findings.extend(_inspect_text(text, source=source))

    referenced_paths: List[Path] = []
    seen_paths: set[str] = set()
    for source, text in text_sources:
        paths, denied = _collect_paths_for_text(text, roots, source=source)
        findings.extend(denied)
        for path in paths:
            key = str(path)
            if key not in seen_paths:
                seen_paths.add(key)
                referenced_paths.append(path)

    scanned_documents: List[Dict[str, Any]] = []
    already_scanned: set[str] = set()
    for path in referenced_paths:
        try:
            resolved = path.resolve()
        except OSError:
            continue
        display_path = _safe_display_path(resolved, repo=repo, project_root=project_root)
        doc_findings, info = _inspect_document(resolved, source="referenced_document", display_path=display_path)
        already_scanned.add(str(resolved))
        findings.extend(doc_findings)
        if info:
            scanned_documents.append(info)

    workspace_summary = {"documents": 0, "bytes": 0, "incomplete": False, "incompleteReason": None}
    if scan_workspace:
        workspace_findings, workspace_scanned, workspace_summary = _inspect_workspace_documents(
            project_root,
            repo=repo,
            already_scanned=already_scanned,
        )
        findings.extend(workspace_findings)
        scanned_documents.extend(workspace_scanned)

    blocked = bool(findings)
    evidence_documents = [
        item for item in scanned_documents
        if item.get("blockedFindings") or item.get("skipped") or item.get("reason")
    ][:24]
    safe_guidance = _safe_guidance_for_findings(findings) if blocked else {}
    obfuscated_block = _has_obfuscated_secret_block(findings)
    prompt_injection_block = _has_persisted_prompt_injection_block(findings)
    login_block = _has_external_login_intent_block(findings)
    payment_block = _has_payment_intent_block(findings)
    reason = (
        "CyberLACE blocked obfuscated secret material: encoded payloads decoded to sensitive credentials and must not be normalized or exposed."
        if obfuscated_block
        else "CyberLACE blocked persisted prompt injection: workspace content attempted to override safety policy and exfiltrate information."
        if prompt_injection_block
        else "CyberLACE blocked external account login intent: agents must not use provided passwords to enter mailboxes, review messages, or extract attachments."
        if login_block
        else "CyberLACE blocked unsafe payment-data handling intent: copying, collecting, storing or sending card/CVV/PIN/token data is denied. A safe tokenized payment architecture can be designed instead."
        if payment_block
        else "CyberLACE hard gate blocked local document processing: sensitive credentials, financial secrets, unsafe external path references, or unscannable workspace documents were found."
        if blocked
        else "CyberLACE hard gate found no blocking sensitive document content."
    )
    return {
        "ok": True,
        "recordType": "decision",
        "mode": "hard-gate",
        "stage": "document-preflight",
        "agentId": "cyberlace-document-guard",
        "sessionId": session_id,
        "projectSlug": project_slug,
        "action": "QUARANTINE" if blocked else "ALLOW",
        "runtimeAction": "QUARANTINE" if blocked else "ALLOW",
        "allowed": not blocked,
        "blocked": blocked,
        "blocksRuntime": blocked,
        "requiresHumanReview": False,
        "redactsPayload": False,
        "riskScore": 100.0 if blocked else 0.0,
        "severity": "CRITICAL" if blocked else "LOW",
        "reason": reason,
        "message": (
            "PELIGRO: secreto ofuscado detectado. HABLA puede ayudar a clasificar y redactar la evidencia sin decodificar ni exponer valores."
            if obfuscated_block
            else "PELIGRO: prompt injection persistida negada. HABLA puede ayudar a aislar, redactar y convertir el documento en evidencia segura."
            if prompt_injection_block
            else "PELIGRO: intento de login externo negado. HABLA puede ayudar con una alternativa segura basada en OAuth, sandbox, mocks y adjuntos sanitizados."
            if login_block
            else "PELIGRO: accion financiera insegura negada. HABLA puede ayudar con una alternativa segura basada en tokenizacion, recibos y arquitectura PCI-style."
            if payment_block
            else "PELIGRO: potencial informacion insegura. La accion fue negada y no se lanzara Codex."
            if blocked
            else "Documentos verificados."
        ),
        "deniedAction": safe_guidance.get("deniedAction"),
        "safeAlternative": safe_guidance.get("safeAlternative"),
        "safeNextSteps": safe_guidance.get("safeNextSteps") or [],
        "evidence": findings[:24],
        "blockedPaths": sorted({str(item.get("path")) for item in findings if item.get("path")}),
        "scannedDocuments": evidence_documents,
        "scannedDocumentCount": len(scanned_documents),
        "workspaceScan": workspace_summary,
    }

"""Runtime adapter for HABLA CyberLACE Security Engine.

The adapter keeps CyberLACE lateral to the current runtime: disabled/off is a
no-op, monitor records evidence without blocking, and enforce maps decisions to
runtime actions through cyberlace_policy_bridge.
"""

from __future__ import annotations

import json
import os
import sys
import threading
import urllib.error
import urllib.request
import uuid
from datetime import datetime, timezone
from pathlib import Path
from typing import Any, Callable, Dict

try:
    from cyberlace_policy_bridge import map_cyberlace_decision_to_runtime
except ImportError:  # pragma: no cover - package import path during unittest.
    from backend.cyberlace_policy_bridge import map_cyberlace_decision_to_runtime


BACKEND_ROOT = Path(__file__).resolve().parent
REPO_ROOT = BACKEND_ROOT.parent
if str(BACKEND_ROOT) not in sys.path:
    sys.path.insert(0, str(BACKEND_ROOT))

CYBERLACE_DEFAULT_REST_URL = "http://127.0.0.1:8088"
VALID_MODES = {"off", "monitor", "enforce"}
VALID_TRANSPORTS = {"import", "rest"}
_ENGINE_LOCK = threading.Lock()
_EVIDENCE_LOCK = threading.Lock()
_ENGINE: Any | None = None
_ENGINE_KEY: tuple[str, str, str] | None = None


def _utc_now() -> str:
    return datetime.now(timezone.utc).replace(microsecond=0).isoformat().replace("+00:00", "Z")


def _env_flag(name: str, *, default: bool = False) -> bool:
    value = os.environ.get(name)
    if value is None:
        return default
    return str(value).strip().lower() not in {"", "0", "false", "no", "off"}


def _mode() -> str:
    if not _env_flag("CYBERLACE_ENABLED", default=False):
        return "off"
    raw_mode = str(os.environ.get("CYBERLACE_MODE") or "monitor").strip().lower()
    return raw_mode if raw_mode in VALID_MODES else "monitor"


def _transport() -> str:
    raw_transport = str(os.environ.get("CYBERLACE_TRANSPORT") or "import").strip().lower()
    return raw_transport if raw_transport in VALID_TRANSPORTS else "import"


def _runtime_root() -> Path:
    configured = str(os.environ.get("CYBERLACE_RUNTIME_DIR") or "").strip()
    return Path(configured).expanduser().resolve() if configured else REPO_ROOT / "runtime" / "cyberlace"


def cyberlace_paths() -> Dict[str, Path]:
    root = _runtime_root()
    return {
        "root": root,
        "evidence": root / "evidence",
        "logs": root / "logs",
        "events": root / "evidence" / "cyberlace_events.jsonl",
        "decisions": root / "evidence" / "cyberlace_decisions.jsonl",
        "failures": root / "logs" / "cyberlace_failures.jsonl",
        "engineEvents": root / "evidence" / "cyberlace_engine_events.jsonl",
        "engineEvidence": root / "evidence" / "cyberlace_engine_evidence.jsonl",
    }


def ensure_cyberlace_runtime() -> Dict[str, str]:
    paths = cyberlace_paths()
    for key in ("root", "evidence", "logs"):
        paths[key].mkdir(parents=True, exist_ok=True)
    for key in ("events", "decisions"):
        paths[key].touch(exist_ok=True)
    return {key: str(value) for key, value in paths.items()}


def cyberlace_settings() -> Dict[str, Any]:
    paths = ensure_cyberlace_runtime()
    return {
        "enabled": _mode() != "off",
        "mode": _mode(),
        "transport": _transport(),
        "restUrl": str(os.environ.get("CYBERLACE_REST_URL") or CYBERLACE_DEFAULT_REST_URL).rstrip("/"),
        "configPath": str(Path(os.environ.get("CYBERLACE_CONFIG_PATH") or BACKEND_ROOT / "cyberlace_config.yaml")),
        "paths": paths,
    }


def _json_safe(value: Any) -> Any:
    try:
        json.dumps(value, ensure_ascii=True)
        return value
    except TypeError:
        if isinstance(value, dict):
            return {str(key): _json_safe(item) for key, item in value.items()}
        if isinstance(value, (list, tuple, set)):
            return [_json_safe(item) for item in value]
        if isinstance(value, Path):
            return str(value)
        return repr(value)


def _append_jsonl(path: Path, payload: Dict[str, Any]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    line = json.dumps(_json_safe(payload), ensure_ascii=True, sort_keys=True)
    with _EVIDENCE_LOCK:
        with path.open("a", encoding="utf-8") as handle:
            handle.write(line + "\n")


def _persist_event(document: Dict[str, Any]) -> None:
    paths = cyberlace_paths()
    _append_jsonl(paths["events"], document)
    if document.get("recordType") in {"decision", "failure"}:
        _append_jsonl(paths["decisions"], document)
    if document.get("recordType") == "failure":
        _append_jsonl(paths["failures"], document)


def get_cyberlace_engine() -> Any:
    """Return the local CyberLACEEngine singleton for import transport."""

    global _ENGINE, _ENGINE_KEY
    settings = cyberlace_settings()
    mode = str(settings["mode"])
    config_path = str(settings["configPath"])
    engine_key = (mode, config_path, str(_runtime_root()))
    with _ENGINE_LOCK:
        if _ENGINE is not None and _ENGINE_KEY == engine_key:
            return _ENGINE

        from cyberlace import CyberLACEEngine

        config: Dict[str, Any] = {}
        try:
            from cyberlace.utils.config import load_config

            config = load_config(config_path)
        except Exception:
            config = {}
        config = dict(config or {})
        config["mode"] = mode
        storage = dict(config.get("storage") or {})
        paths = cyberlace_paths()
        storage["events_jsonl"] = str(paths["engineEvents"])
        storage["evidence_jsonl"] = str(paths["engineEvidence"])
        config["storage"] = storage
        _ENGINE = CyberLACEEngine(config=config, base_path=BACKEND_ROOT)
        _ENGINE_KEY = engine_key
        return _ENGINE


def _disabled_decision(stage: str, payload: Dict[str, Any]) -> Dict[str, Any]:
    return {
        "ok": True,
        "enabled": False,
        "mode": "off",
        "transport": _transport(),
        "stage": stage,
        "allowed": True,
        "action": "ALLOW",
        "runtimeAction": "ALLOW",
        "riskScore": 0,
        "severity": "LOW",
        "reason": "CyberLACE disabled",
        "modified_payload": payload.get("content"),
        "evidence": [],
        "timestamp": _utc_now(),
    }


def _call_import(stage: str, payload: Dict[str, Any]) -> Dict[str, Any]:
    engine = get_cyberlace_engine()
    if stage == "prompt":
        return engine.before_prompt(
            payload["agent_id"],
            payload["user_id"],
            payload["prompt"],
            payload.get("context") or {},
            payload["session_id"],
        )
    if stage == "memory":
        return engine.before_memory_read(
            payload["agent_id"],
            payload["user_id"],
            payload["memory_text"],
            payload.get("task_context") or {},
            payload["session_id"],
        )
    if stage == "tool":
        return engine.before_tool_call(
            payload["agent_id"],
            payload["user_id"],
            payload["tool_name"],
            payload.get("tool_args") or {},
            payload.get("task_context") or {},
            payload["session_id"],
        )
    if stage == "output":
        return engine.after_model_output(
            payload["agent_id"],
            payload["user_id"],
            payload["output"],
            payload.get("context") or {},
            payload["session_id"],
        )
    if stage == "external-action":
        return engine.before_external_action(
            payload["agent_id"],
            payload["user_id"],
            payload["action_type"],
            payload.get("payload") or {},
            payload.get("context") or {},
            payload["session_id"],
        )
    return {"allowed": True, "action": "ALLOW", "risk_score": 0, "reason": "Unknown CyberLACE stage"}


def _call_rest(stage: str, payload: Dict[str, Any]) -> Dict[str, Any]:
    endpoint_map = {
        "prompt": "/v1/guard/prompt",
        "memory": "/v1/guard/memory",
        "tool": "/v1/guard/tool",
        "output": "/v1/guard/output",
        "external-action": "/v1/guard/external-action",
    }
    endpoint = endpoint_map.get(stage)
    if endpoint is None:
        return {"allowed": True, "action": "ALLOW", "risk_score": 0, "reason": "Unknown CyberLACE stage"}
    settings = cyberlace_settings()
    body = json.dumps(_json_safe(payload), ensure_ascii=True).encode("utf-8")
    request = urllib.request.Request(
        str(settings["restUrl"]) + endpoint,
        data=body,
        method="POST",
        headers={"Content-Type": "application/json"},
    )
    with urllib.request.urlopen(request, timeout=float(os.environ.get("CYBERLACE_REST_TIMEOUT_SECONDS", "3"))) as response:
        return json.loads(response.read().decode("utf-8") or "{}")


def _normalize_decision(
    *,
    stage: str,
    payload: Dict[str, Any],
    raw_decision: Dict[str, Any],
    error: str | None = None,
) -> Dict[str, Any]:
    settings = cyberlace_settings()
    risk_score = raw_decision.get("risk_score", raw_decision.get("riskScore", 0))
    document = {
        "recordType": "failure" if error else "decision",
        "eventId": f"cyberlace_{uuid.uuid4().hex}",
        "timestamp": _utc_now(),
        "enabled": bool(settings["enabled"]),
        "mode": settings["mode"],
        "transport": settings["transport"],
        "stage": stage,
        "agentId": payload.get("agent_id"),
        "userId": payload.get("user_id"),
        "sessionId": payload.get("session_id"),
        "toolName": payload.get("tool_name") or payload.get("action_type"),
        "riskScore": float(risk_score or 0),
        "severity": raw_decision.get("severity", "LOW"),
        "reason": raw_decision.get("reason") or ("CyberLACE failure" if error else "CyberLACE decision"),
        "action": raw_decision.get("action", "ALLOW"),
        "allowed": bool(raw_decision.get("allowed", True)),
        "modified_payload": raw_decision.get("modified_payload"),
        "evidence": raw_decision.get("evidence") or [],
        "policyMatches": raw_decision.get("policy_matches") or [],
        "error": error,
        "rawDecision": raw_decision,
    }
    mapped = map_cyberlace_decision_to_runtime(document, mode=str(settings["mode"]))
    _persist_event(mapped)
    return {"ok": error is None, **mapped}


def _failure_decision(stage: str, payload: Dict[str, Any], error: Exception) -> Dict[str, Any]:
    settings = cyberlace_settings()
    action = "ALLOW" if settings["mode"] != "enforce" else "HUMAN_REVIEW"
    raw = {
        "allowed": settings["mode"] != "enforce",
        "action": action,
        "risk_score": 0 if settings["mode"] != "enforce" else 70,
        "severity": "LOW" if settings["mode"] != "enforce" else "HIGH",
        "reason": f"CyberLACE unavailable: {error}",
        "evidence": [{"type": "cyberlace_failure", "message": str(error), "stage": stage}],
    }
    return _normalize_decision(stage=stage, payload=payload, raw_decision=raw, error=str(error))


def _guard(stage: str, payload: Dict[str, Any]) -> Dict[str, Any]:
    settings = cyberlace_settings()
    if not settings["enabled"] or settings["mode"] == "off":
        return _disabled_decision(stage, payload)
    try:
        raw = _call_rest(stage, payload) if settings["transport"] == "rest" else _call_import(stage, payload)
        return _normalize_decision(stage=stage, payload=payload, raw_decision=raw)
    except Exception as error:
        return _failure_decision(stage, payload, error)


def cyberlace_before_prompt(agent_id: str, user_id: str, prompt: str, context: Dict[str, Any] | None, session_id: str) -> Dict[str, Any]:
    return _guard(
        "prompt",
        {
            "agent_id": agent_id or "unknown-agent",
            "user_id": user_id or "anonymous",
            "prompt": str(prompt or ""),
