from project_graph import extract_html_references, extract_js_imports, normalize_posix_path, resolve_import_specifier, to_posix

IGNORED_PARTS = {"node_modules", "dist", "__pycache__", ".venv", ".vista"}
WORKSPACE_PREFIXES = {("workspace", "projects"), ("analysis", "projects")}
PROJECT_CONTENT_FOLDERS = {"src", "backend", "frontend", "shared", "tests", "docs", "algorithms", "assets"}
CONCEPTUAL_DOC_SUFFIXES = {".md"}
CONCEPTUAL_ROOT_FILES = {"readme.md"}


def utc_now() -> str:
    return datetime.now(timezone.utc).isoformat()


def workspace_path_parts(relative_path: str) -> tuple[str, str, List[str]] | None:
    path = PurePosixPath(normalize_posix_path(relative_path))
    parts = list(path.parts)
    if len(parts) < 3 or tuple(parts[:2]) not in WORKSPACE_PREFIXES:
        return None
    return parts[0], parts[2], parts[3:]


def workspace_scene_segments(relative_path: str) -> List[str]:
    resolved = workspace_path_parts(relative_path)
    if resolved is None:
        return []

    _, _, remainder = resolved
    segments: List[str] = []
    for index, part in enumerate(remainder):
        if part in PROJECT_CONTENT_FOLDERS:
            break
        if index == len(remainder) - 1:
            break
        segments.append(part)
    return segments


def workspace_scene_key_for_path(relative_path: str) -> str | None:
    resolved = workspace_path_parts(relative_path)
    if resolved is None:
        return None

    _, project_slug, _ = resolved
    segments = workspace_scene_segments(relative_path)
    if not segments:
        return project_slug
    return "/".join([project_slug, *segments])


def workspace_scene_label(scene_key: str | None) -> str:
    if not scene_key:
        return "Mapa completo"
    return " / ".join(segment.replace("-", " ").title() for segment in scene_key.split("/"))


def workspace_scene_root_for_path(relative_path: str) -> str | None:
    resolved = workspace_path_parts(relative_path)
    if resolved is None:
        return None

    prefix_kind, project_slug, _ = resolved
    segments = workspace_scene_segments(relative_path)
    root_parts = [prefix_kind, "projects", project_slug, *segments]
    return normalize_posix_path("/".join(root_parts))


def infer_expected_layer(relative_path: str) -> str | None:
    normalized = normalize_posix_path(relative_path)
    suffix = PurePosixPath(normalized).suffix.lower()

    if normalized.endswith("/backend/data/tasks.json") or "/backend/data/" in normalized:
        return "data"
    if "/docs/" in normalized or suffix == ".md":
        return "docs"
    if suffix == ".css":
        return "style"
    if "/shared/" in normalized:
        return "shared"
    if "/frontend/" in normalized:
        return "frontend"
    if "/backend/" in normalized:
        return "backend"
    return None


def extract_fetch_targets(content: str) -> List[str]:
    return [match for match in re.findall(r'fetch\(\s*["\']([^"\']+)["\']', content or "") if match]


def resolve_project_root_reference(current_path: str, specifier: str, known_paths: set[str]) -> str | None:
    normalized = str(specifier or "").strip()
    if not normalized.startswith("/"):
        return None

    scene_root = workspace_scene_root_for_path(current_path)
    if not scene_root:
        return None

    if normalized.startswith(("/shared/", "/frontend/", "/assets/", "/backend/")):
        candidate = normalize_posix_path(f"{scene_root}/{normalized.lstrip('/')}")
        if candidate in known_paths:
            return candidate
    return None


def edge_exists(nodes_by_path: Dict[str, Dict[str, Any]], edge_pairs: set[tuple[str, str]], source_path: str, target_path: str) -> bool:
    source_node = nodes_by_path.get(source_path)
    target_node = nodes_by_path.get(target_path)
    if not source_node or not target_node:
        return False
    return (str(source_node.get("id")), str(target_node.get("id"))) in edge_pairs


def nearest_step_id(steps: List[Dict[str, Any]], line: int | None) -> str | None:
    if not steps or not line:
        return None

    candidates = [
        step for step in steps
        if isinstance(step.get("line"), int) and int(step.get("line") or 0) > 0 and str(step.get("id") or "") not in {"start", "end"}
    ]
    if not candidates:
        return None

    nearest = min(candidates, key=lambda step: abs(int(step.get("line") or 0) - int(line)))
    return str(nearest.get("id") or "") or None


def top_level_python_functions(module: ast.Module) -> List[ast.FunctionDef | ast.AsyncFunctionDef]:
    return [node for node in module.body if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef))]


def python_call_names(module: ast.AST) -> set[str]:
    names: set[str] = set()
    for child in ast.walk(module):
        if isinstance(child, ast.Call):
            if isinstance(child.func, ast.Name):
                names.add(child.func.id)
            elif isinstance(child.func, ast.Attribute):
                names.add(child.func.attr)
    return names


def should_skip_python_orphan(node: ast.FunctionDef | ast.AsyncFunctionDef) -> bool:
    if node.name.startswith("_") or node.name in {"main", "run", "start", "bootstrap", "create_app"}:
        return True
    for decorator in node.decorator_list:
        decorator_text = ast.unparse(decorator) if hasattr(ast, "unparse") else ""
        if any(token in decorator_text for token in ("route", "socketio.on", "app.", "bp.", "property")):
            return True
    return False


def extract_js_local_functions(content: str) -> List[Dict[str, Any]]:
    functions: List[Dict[str, Any]] = []
    patterns = (
        r"^(?:export\s+)?(?:async\s+)?function\s+([A-Za-z_$][\w$]*)\s*\(",
        r"^(?:export\s+)?const\s+([A-Za-z_$][\w$]*)\s*=\s*(?:async\s*)?(?:\([^)]*\)|[A-Za-z_$][\w$]*)\s*=>",
        r"^(?:export\s+)?let\s+([A-Za-z_$][\w$]*)\s*=\s*(?:async\s*)?(?:\([^)]*\)|[A-Za-z_$][\w$]*)\s*=>",
    )
    for line_no, raw_line in enumerate(content.splitlines(), start=1):
        stripped = raw_line.strip()
        if not stripped or stripped.startswith(("//", "*", "/*")):
            continue
        for pattern in patterns:
            match = re.match(pattern, stripped)
            if match:
                functions.append(
                    {
                        "name": match.group(1),
                        "line": line_no,
                        "exported": stripped.startswith("export "),
                    }
                )
                break
    return functions


def validate_algorithm_wiring(
    steps: List[Dict[str, Any]],
    edges: List[Dict[str, Any]],
    add_finding,
    *,
    relative_path: str,
    scene_key: str,
) -> None:
    if not steps:
        return

    step_ids = {str(step.get("id") or "") for step in steps if step.get("id")}
    outgoing: Dict[str, List[Dict[str, Any]]] = {step_id: [] for step_id in step_ids}
    incoming: Dict[str, List[Dict[str, Any]]] = {step_id: [] for step_id in step_ids}

    for edge in edges:
        source_id = str(edge.get("from") or "")
        target_id = str(edge.get("to") or "")
        if source_id not in step_ids or target_id not in step_ids:
            add_finding(
                "error",
                "algorithm_broken_edge",
                "El diagrama interno contiene una flecha hacia un bloque inexistente.",
                relative_path=relative_path,
                scene_key=scene_key,
                hint="Corrige el origen o destino de la flecha interna para mantener el cableado del flujo.",
                evidence={"edge": edge},
                step_id=source_id or None,
            )
            continue
        outgoing[source_id].append(edge)
        incoming[target_id].append(edge)

    reachable = set()
    stack = ["start"] if "start" in step_ids else []
    while stack:
        current = stack.pop()
        if current in reachable:
            continue
        reachable.add(current)
        for edge in outgoing.get(current, []):
            target_id = str(edge.get("to") or "")
            if target_id and target_id not in reachable:
                stack.append(target_id)

    for step in steps:
        step_id = str(step.get("id") or "")
        step_type = str(step.get("type") or "")
        line = int(step.get("line") or 0) or None
        if step_id not in reachable and step_id not in {"start"}:
            add_finding(
                "error",
                "algorithm_unreachable_step",
                "Hay un bloque interno que nunca recibe flujo desde el inicio del algoritmo.",
                relative_path=relative_path,
                scene_key=scene_key,
                hint="Conecta este bloque al flujo principal o eliminalo si quedo aislado.",
                line=line,
                step_id=step_id,
            )
        if step_type == "decision" and len(outgoing.get(step_id, [])) < 2:
            add_finding(
                "warning",
                "algorithm_missing_branch",
                "La decision no tiene ambas ramas conectadas y el flujo puede quedar ambiguo.",
                relative_path=relative_path,
                scene_key=scene_key,
                hint="Agrega al menos una salida afirmativa y otra negativa desde este bloque de decision.",
                line=line,
                step_id=step_id,
            )
        if step_type not in {"end", "decision"} and step_id not in {"start"} and not outgoing.get(step_id):
            add_finding(
                "warning",
                "algorithm_dead_end",
                "El bloque interno termina sin salida y puede haber un corte en el harness del algoritmo.",
                relative_path=relative_path,
                scene_key=scene_key,
                hint="Conecta este bloque con el siguiente paso logico o con el fin del flujo.",
                line=line,
                step_id=step_id,
            )


def lint_graph(
    graph: Dict[str, Any],
    project_root: Path,
    scene_filter: str | None = None,
    *,
    include_workspace_doc_scan: bool = True,
) -> Dict[str, Any]:
    nodes = graph.get("nodes") or []
    edges = graph.get("edges") or []
    nodes_by_path = {normalize_posix_path(str(node.get("path") or "")): node for node in nodes if node.get("path")}
    known_paths = set(nodes_by_path)
    edge_pairs = {(str(edge.get("from") or ""), str(edge.get("to") or "")) for edge in edges if edge.get("from") and edge.get("to")}
    findings: List[Dict[str, Any]] = []

    def in_scope(relative_path: str | None, scene_key: str | None = None) -> bool:
        if not scene_filter:
            return True
        if scene_key is None and relative_path:
            scene_key = workspace_scene_key_for_path(relative_path)
        return scene_key == scene_filter

    def add_finding(
        severity: str,
        code: str,
        message: str,
        *,
        relative_path: str | None = None,
        scene_key: str | None = None,
        hint: str | None = None,
        evidence: Dict[str, Any] | None = None,
        line: int | None = None,
        step_id: str | None = None,
    ) -> None:
        normalized_path = normalize_posix_path(relative_path) if relative_path else None
        if not in_scope(normalized_path, scene_key):
            return
        node = nodes_by_path.get(normalized_path or "")
        algorithm = node.get("algorithm") if isinstance(node, dict) and isinstance(node.get("algorithm"), dict) else {}
        steps = algorithm.get("steps") if isinstance(algorithm.get("steps"), list) else []
        derived_step_id = step_id or nearest_step_id(steps, line)
        finding = {
            "severity": severity,
            "code": code,
            "message": message,
            "path": normalized_path,
            "scene": scene_key or (workspace_scene_key_for_path(normalized_path) if normalized_path else None),
            "hint": hint or "",
            "evidence": evidence or {},
            "line": line,
            "stepId": derived_step_id,
            "nodeId": str(node.get("id") or "") if isinstance(node, dict) else "",
        }
        findings.append(finding)

    for node in nodes:
        relative_path = normalize_posix_path(str(node.get("path") or ""))
        suffix = PurePosixPath(relative_path).suffix.lower()
        scene_key = str(node.get("workspaceScene") or workspace_scene_key_for_path(relative_path) or "")
        expected_scene = workspace_scene_key_for_path(relative_path)
        if expected_scene and scene_key and expected_scene != scene_key:
            add_finding(
                "warning",
                "scene_mismatch",
                "El nodo pertenece a otra escena segun su path y puede contaminar el mapa conceptual.",
                relative_path=relative_path,
                scene_key=scene_key,
                hint="Recalcula workspaceScene usando la ruta real del archivo antes de persistir el nodo.",
                evidence={"expectedScene": expected_scene, "actualScene": scene_key},
            )

        origin = node.get("sceneOrigin") if isinstance(node.get("sceneOrigin"), dict) else None
        position = node.get("position") if isinstance(node.get("position"), dict) else None
        if origin and position:
            origin_x = origin.get("x")
            origin_y = origin.get("y")
            position_x = position.get("x")
            position_y = position.get("y")
            if isinstance(origin_x, (int, float)) and isinstance(origin_y, (int, float)) and isinstance(position_x, (int, float)) and isinstance(position_y, (int, float)):
                if position_x < origin_x or position_y < origin_y:
                    add_finding(
                        "error",
                        "scene_local_coordinates",
                        "El nodo conserva coordenadas locales y puede montarse encima de otra escena.",
                        relative_path=relative_path,
                        scene_key=scene_key,
                        hint="Traduce la posicion local sumando sceneOrigin antes de guardar el nodo sincronizado.",
                        evidence={"sceneOrigin": origin, "position": position},
                    )

        expected_layer = infer_expected_layer(relative_path)
        actual_layer = str(node.get("layer") or "")
        if expected_layer == "data" and actual_layer != "data":
            add_finding(
                "warning",
                "layer_storage_mismatch",
                "El archivo de persistencia esta mezclado con la capa backend en vez de una capa de datos.",
                relative_path=relative_path,
                scene_key=scene_key,
                hint="Clasifica backend/data como layer data para separar logica ejecutable de estado persistido.",
                evidence={"expectedLayer": "data", "actualLayer": actual_layer},
            )
        if expected_layer == "docs" and actual_layer != "docs":
            add_finding(
                "warning",
                "layer_docs_mismatch",
                "La documentacion del proyecto no esta etiquetada como docs dentro del mapa.",
                relative_path=relative_path,
                scene_key=scene_key,
                hint="Usa la capa docs para archivos .md y contenido dentro de /docs/.",
                evidence={"expectedLayer": "docs", "actualLayer": actual_layer},
            )

        algorithm = node.get("algorithm") if isinstance(node.get("algorithm"), dict) else {}
        steps = algorithm.get("steps") if isinstance(algorithm.get("steps"), list) else []
        edges_in_algorithm = algorithm.get("edges") if isinstance(algorithm.get("edges"), list) else []
        code = str(node.get("code") or "")
        validate_algorithm_wiring(
            steps,
            edges_in_algorithm,
            add_finding,
            relative_path=relative_path,
            scene_key=scene_key,
        )
        if expected_layer == "data" and code.strip() in {"[]", "{}", ""}:
            if any(relative_path in str(step.get("code") or "") for step in steps):
                add_finding(
                    "info",
                    "passive_data_pseudo_flow",
                    "El almacenamiento vacio se esta dibujando como algoritmo de proceso en vez de estado pasivo.",
                    relative_path=relative_path,
                    scene_key=scene_key,
                    hint="Renderiza nodos de datos vacios como snapshot o estado, no como flujo ejecutable.",
                )

        if suffix == ".py":
            try:
                module = ast.parse(code)
            except SyntaxError as error:
                add_finding(
                    "error",
                    "python_syntax_error",
                    "El archivo Python tiene un error de sintaxis o indentacion y no puede cablearse completo.",
                    relative_path=relative_path,
                    scene_key=scene_key,
                    hint="Corrige la sintaxis para que el analizador pueda reconstruir el flujo completo.",
                    evidence={"detail": error.msg},
                    line=error.lineno,
                )
            else:
                called_names = python_call_names(module)
                for function in top_level_python_functions(module):
                    if should_skip_python_orphan(function):
                        continue
                    if function.name not in called_names:
                        add_finding(
                            "warning",
                            "python_orphan_function",
                            "Hay una funcion definida que no parece ser llamada por ningun flujo del modulo.",
                            relative_path=relative_path,
                            scene_key=scene_key,
                            hint="Conectala desde el flujo principal, exportala de forma explicita o elimina el codigo muerto.",
                            evidence={"function": function.name},
                            line=function.lineno,
                        )
                for child in ast.walk(module):
                    if isinstance(child, ast.ImportFrom) and child.level > 0:
                        import_path = relative_path
                        base = PurePosixPath(import_path).parent
                        parent_parts = list(base.parts)
                        if child.level > 1:
                            parent_parts = parent_parts[: max(0, len(parent_parts) - (child.level - 1))]
                        module_parts = list(parent_parts)
                        if child.module:
                            module_parts.extend(child.module.split("."))
                        resolved_base = "/".join(module_parts)
                        candidate_paths = [f"{resolved_base}.py", f"{resolved_base}/__init__.py"]
                        if not any(candidate in known_paths for candidate in candidate_paths):
                            add_finding(
                                "error",
                                "python_relative_import_missing",
                                "Hay una importacion relativa de Python que no resuelve a ningun archivo real del proyecto.",
                                relative_path=relative_path,
                                scene_key=scene_key,
                                hint="Revisa el paquete objetivo o corrige la ruta relativa del import.",
                                evidence={"module": child.module or "", "level": child.level},
                                line=child.lineno,
                            )

        if suffix in {".js", ".jsx", ".ts", ".tsx"}:
            open_braces = code.count("{")
            close_braces = code.count("}")
            if open_braces != close_braces:
                add_finding(
                    "warning",
                    "js_brace_mismatch",
                    "El archivo JS/TS tiene llaves desbalanceadas y la lectura del flujo puede quedar rota.",
                    relative_path=relative_path,
                    scene_key=scene_key,
                    hint="Revisa bloques if/else, loops o funciones que no cierran correctamente.",
                    evidence={"openBraces": open_braces, "closeBraces": close_braces},
                )
            for function in extract_js_local_functions(code):
                if function["exported"] or str(function["name"]).startswith(("use", "App")):
                    continue
                occurrences = len(re.findall(rf"\b{re.escape(str(function['name']))}\b", code))
                if occurrences <= 1:
                    add_finding(
                        "warning",
                        "js_orphan_function",
                        "Hay una funcion local declarada que no parece participar en el cableado del modulo.",
                        relative_path=relative_path,
                        scene_key=scene_key,
                        hint="Invocala desde el flujo real, pasala como callback visible o elimina el codigo muerto.",
                        evidence={"function": function["name"]},
                        line=int(function["line"]),
                    )

    workspace_root = project_root / "workspace" / "projects"
    if include_workspace_doc_scan and workspace_root.exists():
        for file_path in workspace_root.rglob("*"):
            if not file_path.is_file():
                continue
            if any(part in IGNORED_PARTS for part in file_path.parts):
                continue
            suffix = file_path.suffix.lower()
            file_name = file_path.name.lower()
            if suffix not in CONCEPTUAL_DOC_SUFFIXES and file_name not in CONCEPTUAL_ROOT_FILES:
                continue
            relative_path = to_posix(file_path.relative_to(project_root))
            scene_key = workspace_scene_key_for_path(relative_path)
            if relative_path not in nodes_by_path:
                add_finding(
                    "warning",
                    "missing_conceptual_node",
                    "El archivo existe en disco pero no aparece en el mapa conceptual.",
                    relative_path=relative_path,
                    scene_key=scene_key,
                    hint="Incluye markdown en el escaner o preserva nodos de documentacion al mezclar el estado guardado con el rescan.",
                )

    for relative_path, node in nodes_by_path.items():
        scene_key = str(node.get("workspaceScene") or workspace_scene_key_for_path(relative_path) or "")
        suffix = PurePosixPath(relative_path).suffix.lower()
        content = str(node.get("code") or "")

        if suffix == ".html":
            for specifier in extract_html_references(content):
                resolved = resolve_import_specifier(relative_path, specifier, known_paths) or resolve_project_root_reference(relative_path, specifier, known_paths)
                if (specifier.startswith(".") or specifier.startswith("/")) and not resolved:
                    add_finding(
                        "error",
                        "unresolved_html_reference",
                        "La vista HTML referencia un recurso local que no existe o no puede resolverse.",
                        relative_path=relative_path,
                        scene_key=scene_key,
                        hint="Corrige la ruta del script, stylesheet o recurso enlazado.",
                        evidence={"specifier": specifier},
                    )
                if resolved and not edge_exists(nodes_by_path, edge_pairs, relative_path, resolved):
                    add_finding(
                        "warning",
                        "missing_html_dependency_edge",
                        "La vista HTML referencia un recurso real que no esta conectado en el mapa.",
                        relative_path=relative_path,
                        scene_key=scene_key,
                        hint="Crea una flecha entre el HTML y el recurso referenciado para que la carga sea trazable.",
                        evidence={"targetPath": resolved, "specifier": specifier},
                    )

        if suffix in {".js", ".jsx", ".ts", ".tsx"}:
            for specifier in extract_js_imports(content):
                resolved = resolve_import_specifier(relative_path, specifier, known_paths) or resolve_project_root_reference(relative_path, specifier, known_paths)
                if (specifier.startswith(".") or specifier.startswith("/")) and not resolved:
                    add_finding(
                        "error",
                        "unresolved_module_import",
                        "El modulo importa un archivo local que no existe o no puede resolverse.",
                        relative_path=relative_path,
                        scene_key=scene_key,
                        hint="Corrige el import o crea el archivo faltante para cerrar el cableado.",
                        evidence={"specifier": specifier},
                    )
                if resolved and not edge_exists(nodes_by_path, edge_pairs, relative_path, resolved):
                    add_finding(
                        "warning",
                        "missing_module_edge",
                        "El modulo importa o referencia un archivo real que no esta conectado en el mapa.",
                        relative_path=relative_path,
                        scene_key=scene_key,
                        hint="Agrega una flecha usa/importa para reflejar la dependencia real del modulo.",
                        evidence={"targetPath": resolved, "specifier": specifier},
                    )

            fetch_targets = extract_fetch_targets(content)
            backend_paths = [
                path
                for path, target_node in nodes_by_path.items()
                if str(target_node.get("workspaceScene") or "") == scene_key and str(target_node.get("layer") or "") == "backend"
            ]
            if any(target.startswith("/") and not target.startswith(("/shared/", "/assets/", "/frontend/")) for target in fetch_targets):
                if backend_paths and not any(edge_exists(nodes_by_path, edge_pairs, relative_path, backend_path) for backend_path in backend_paths):
                    add_finding(
                        "warning",
                        "missing_http_backend_edge",
                        "El frontend usa rutas HTTP pero no tiene una flecha hacia el backend de su escena.",
                        relative_path=relative_path,
                        scene_key=scene_key,
                        hint="Conecta el cliente con el servicio backend que responde esas rutas.",
                    )

            for target in fetch_targets:
                resolved = resolve_project_root_reference(relative_path, target, known_paths)
                if resolved and not edge_exists(nodes_by_path, edge_pairs, relative_path, resolved):
                    add_finding(
                        "warning",
                        "missing_fetch_resource_edge",
                        "El cliente hace fetch a un recurso interno pero el mapa no muestra esa dependencia.",
                        relative_path=relative_path,
                        scene_key=scene_key,
                        hint="Agrega una flecha desde el cliente hacia el recurso compartido o estatico que consulta.",
                        evidence={"targetPath": resolved, "fetchTarget": target},
                    )

        if suffix == ".py" and "/backend/" in relative_path:
            if "task_schema.json" in content:
                scene_root = workspace_scene_root_for_path(relative_path)
                if scene_root:
                    target_path = normalize_posix_path(f"{scene_root}/shared/task_schema.json")
                    if target_path in known_paths and not edge_exists(nodes_by_path, edge_pairs, relative_path, target_path):
                        add_finding(
                            "warning",
                            "missing_backend_schema_edge",
                            "El backend usa el schema compartido pero esa dependencia no aparece conectada.",
                            relative_path=relative_path,
                            scene_key=scene_key,
                            hint="Conecta el backend con el schema compartido para reflejar la validacion real.",
                            evidence={"targetPath": target_path},
                        )
            if "tasks.json" in content:
                scene_root = workspace_scene_root_for_path(relative_path)
                if scene_root:
                    target_path = normalize_posix_path(f"{scene_root}/backend/data/tasks.json")
                    if target_path in known_paths and not edge_exists(nodes_by_path, edge_pairs, relative_path, target_path):
                        add_finding(
                            "warning",
                            "missing_backend_storage_edge",
                            "El backend persiste tareas en disco pero el mapa no muestra la dependencia de storage.",
                            relative_path=relative_path,
                            scene_key=scene_key,
                            hint="Conecta el servicio backend con su archivo o capa de persistencia.",
                            evidence={"targetPath": target_path},
                        )

    severity_order = {"error": 0, "warning": 1, "info": 2}
    findings.sort(key=lambda item: (severity_order.get(str(item.get("severity")), 9), str(item.get("path") or ""), str(item.get("code") or "")))

    summary = {"error": 0, "warning": 0, "info": 0, "total": len(findings)}
    for finding in findings:
        severity = str(finding.get("severity") or "info")
        if severity not in summary:
            summary[severity] = 0
        summary[severity] += 1

    return {
        "generatedAt": utc_now(),
        "scope": {
            "scene": scene_filter or "",
            "label": workspace_scene_label(scene_filter),
        },
        "summary": summary,
        "findings": findings,
    }

from __future__ import annotations

import ast
import json
import os
import re
from pathlib import Path, PurePosixPath
from typing import Any, Dict, Iterable, List, Sequence

IGNORED_PARTS = {".git", ".pytest_cache", ".ruff_cache", ".runtime", "build", "coverage", "node_modules", "dist", "__pycache__", ".venv"}
IGNORED_FILES = {"package-lock.json", ".agent-project.json", "editor_state.json", "reverse_engineering_state.json"}
MAX_NODE_CODE_BYTES = 250_000
IGNORED_WORKSPACE_PROJECT_PARTS = {"runtime", ".vista"}
SUPPORTED_SUFFIXES = {".py", ".jsx", ".js", ".ts", ".tsx", ".css", ".html", ".json", ".txt", ".md", ".cpp", ".cc", ".cxx", ".h", ".hpp"}
JS_SUFFIXES = {".js", ".jsx", ".ts", ".tsx"}
STYLE_SUFFIXES = {".css"}
CONFIG_FILES = {"package.json", "requirements.txt"}
FLOW_TYPES = {"start", "end", "process", "decision", "io"}
DEFAULT_LAYER_COLORS = {
    "frontend": "#a855f7",
    "backend": "#f97316",
    "data": "#fb7185",
    "microservice": "#14b8a6",
    "shared": "#38bdf8",
    "docs": "#eab308",
    "style": "#d946ef",
    "config": "#f59e0b",
    "script": "#ec4899",
}
CUSTOM_LAYER_COLORS = ["#60a5fa", "#22c55e", "#f43f5e", "#f59e0b", "#14b8a6", "#a855f7", "#fb7185"]


def graph_code_payload(content: str) -> tuple[str, bool]:
    encoded = content.encode("utf-8")
    if len(encoded) <= MAX_NODE_CODE_BYTES:
        return content, False
    preview = encoded[:MAX_NODE_CODE_BYTES].decode("utf-8", errors="ignore")
    return f"{preview}\n\n[... graph code preview truncated: {len(encoded)} bytes total ...]", True


def build_project_graph(project_root: Path) -> Dict[str, Any]:
    files = discover_source_files(project_root)
    known_paths = {to_posix(path.relative_to(project_root)) for path in files}
    nodes = []
    imports_by_path: Dict[str, List[str]] = {}

    for file_path in files:
        relative_path = to_posix(file_path.relative_to(project_root))
        try:
            content = file_path.read_text(encoding="utf-8")
            file_size = file_path.stat().st_size
            source_path = str(file_path.resolve())
        except (FileNotFoundError, OSError):
            continue
        code_payload, code_truncated = graph_code_payload(content)
        statements = extract_real_statements(relative_path, content)
        algorithm = build_real_algorithm(relative_path, content, statements)
        imports = extract_internal_references(relative_path, content, known_paths)

        imports_by_path[relative_path] = imports
        nodes.append(
            {
                "id": node_id_for_path(relative_path),
                "name": file_path.name,
                "path": relative_path,
                "sourcePath": source_path,
                "layer": infer_layer(relative_path),
                "layerLabel": layer_label_for_path(relative_path),
                "status": infer_status(relative_path),
                "size": format_size(file_size),
                "lines": count_lines(content),
                "description": describe_file(relative_path, statements),
                "imports": imports,
                "dependents": [],
                "color": default_color_for_layer(infer_layer(relative_path)),
                "code": code_payload,
                "codeTruncated": code_truncated,
                "codeLanguage": detect_code_language(relative_path),
                "algorithm": algorithm,
            }
        )

    node_id_by_path = {node["path"]: node["id"] for node in nodes}
    dependents_by_path = {node["path"]: [] for node in nodes}

    for source_path, import_paths in imports_by_path.items():
        for target_path in import_paths:
            dependents_by_path.setdefault(target_path, []).append(source_path)

    for node in nodes:
        node["dependents"] = dependents_by_path.get(node["path"], [])

    edges = []
    seen_edges = set()
    for source_path, import_paths in imports_by_path.items():
        source_node = next((node for node in nodes if node["path"] == source_path), None)
        if not source_node:
            continue

        for target_path in import_paths:
            source_id = node_id_by_path[source_path]
            target_id = node_id_by_path[target_path]
            edge_key = (source_id, target_id)
            if edge_key in seen_edges or source_id == target_id:
                continue
            seen_edges.add(edge_key)

            target_node = next((node for node in nodes if node["path"] == target_path), None)
            edges.append(
                {
                    "id": f"edge-{source_id}-{target_id}",
                    "from": source_id,
                    "to": target_id,
                    "type": infer_edge_type(source_node, target_node),
                    "label": infer_edge_label(source_node, target_node),
                    "dashed": False,
                }
            )

    return {
        "metadata": {
            "projectName": project_root.name,
            "sessionId": "repo-live-scan",
            "source": "real_project_scan",
            "note": "Mapa generado desde los archivos reales del repositorio. Cada algoritmo usa lineas reales del codigo.",
        },
        "nodes": nodes,
        "edges": edges,
    }


def discover_source_files(project_root: Path) -> List[Path]:
    files: List[Path] = []
    for root_name in ("backend", "frontend", "microservice-js", "workspace/projects"):
        root = project_root / root_name
        if not root.exists():
            continue

        try:
            iterator = root.rglob("*")
            for file_path in iterator:
                try:
                    if not file_path.is_file():
                        continue
                except (FileNotFoundError, OSError):
                    continue

                if any(part in IGNORED_PARTS for part in file_path.parts):
                    continue

                if is_workspace_runtime_internal_file(project_root, file_path):
                    continue

                if file_path.name in IGNORED_FILES or file_path.suffix not in SUPPORTED_SUFFIXES:
                    continue

                files.append(file_path)
        except (FileNotFoundError, OSError):
            continue

    return sorted(files, key=lambda path: to_posix(path.relative_to(project_root)))


def is_workspace_runtime_internal_file(project_root: Path, file_path: Path) -> bool:
    try:
        parts = file_path.relative_to(project_root).parts
    except ValueError:
        return False
    if len(parts) < 4 or parts[0] != "workspace" or parts[1] != "projects":
        return False
    project_relative_parts = parts[3:]
    return bool(project_relative_parts and project_relative_parts[0] in IGNORED_WORKSPACE_PROJECT_PARTS)


def extract_internal_references(current_path: str, content: str, known_paths: set[str]) -> List[str]:
    references = []

    if current_path == "backend/app.py" and "backend/requirements.txt" in known_paths:
        references.append("backend/requirements.txt")

    if current_path.endswith(tuple(JS_SUFFIXES)):
        for specifier in extract_js_imports(content):
            resolved = resolve_import_specifier(current_path, specifier, known_paths)
            if resolved:
                references.append(resolved)

        if "frontend/package.json" in known_paths and uses_frontend_dependencies(content):
            references.append("frontend/package.json")

        if current_path.startswith("microservice-js/") and "microservice-js/package.json" in known_paths:
            references.append("microservice-js/package.json")

        if "backend/app.py" in known_paths and references_backend_runtime(content):
            references.append("backend/app.py")

    if current_path.endswith(".html"):
        for specifier in extract_html_references(content):
            resolved = resolve_import_specifier(current_path, specifier, known_paths)
            if resolved:
                references.append(resolved)

    if current_path.endswith(".py"):
        references.extend(extract_python_import_references(current_path, content, known_paths))

    if current_path.endswith(".css"):
        for specifier in re.findall(r'@import\s+["\']([^"\']+)["\']', content):
            resolved = resolve_import_specifier(current_path, specifier, known_paths)
            if resolved:
                references.append(resolved)

    unique = []
    seen = set()
    for reference in references:
        if reference in seen or reference == current_path:
            continue
        seen.add(reference)
        unique.append(reference)
    return unique


def extract_js_imports(content: str) -> List[str]:
    matches = re.findall(r'import\s+(?:[^;]*?\s+from\s+)?["\']([^"\']+)["\']', content)
    return [match for match in matches if match]


def extract_html_references(content: str) -> List[str]:
    matches = re.findall(r'(?:src|href)=["\']([^"\']+)["\']', content)
    return [match for match in matches if match]


def extract_python_import_references(current_path: str, content: str, known_paths: set[str]) -> List[str]:
    try:
        module = ast.parse(content)
    except SyntaxError:
        return []

    references: List[str] = []
    for node in ast.walk(module):
        if isinstance(node, ast.Import):
            for alias in node.names:
                resolved = resolve_python_module_reference(current_path, alias.name, known_paths, level=0)
                if resolved:
                    references.append(resolved)
        elif isinstance(node, ast.ImportFrom):
            module_name = node.module or ""
            if module_name:
                resolved = resolve_python_module_reference(current_path, module_name, known_paths, level=node.level)
                if resolved:
                    references.append(resolved)
            elif node.level > 0:
                for alias in node.names:
                    resolved = resolve_python_module_reference(current_path, alias.name, known_paths, level=node.level)
                    if resolved:
                        references.append(resolved)

    return references


def uses_frontend_dependencies(content: str) -> bool:
    return any(package in content for package in ('from "react"', 'from "react-dom"', 'from "three"', 'from "socket.io-client"'))


def references_backend_runtime(content: str) -> bool:
    return (
        "SOCKET_URL" in content
        or "socket.io-client" in content
        or "localhost:5000" in content
        or "/api/architecture" in content
    )


def resolve_import_specifier(current_path: str, specifier: str, known_paths: set[str]) -> str | None:
    normalized = specifier.strip()
    if not normalized:
        return None

    current_parent = PurePosixPath(current_path).parent
    if normalized.startswith("/"):
        if current_path.startswith("frontend/"):
            candidate = to_posix(PurePosixPath("frontend") / normalized.lstrip("/"))
            if candidate in known_paths:
                return candidate
        return None

    if normalized.startswith("."):
        joined = normalize_posix_path(str(current_parent / normalized))
        for candidate in expand_candidate_paths(joined):
            if candidate in known_paths:
                return candidate
        return None

    return None


def expand_candidate_paths(path: str) -> List[str]:
    suffix = PurePosixPath(path).suffix
    candidates = [path]

    if not suffix:
        for extension in (".js", ".jsx", ".ts", ".tsx", ".css", ".json", ".html"):
            candidates.append(f"{path}{extension}")
        for index_name in ("index.js", "index.jsx", "index.ts", "index.tsx"):
            candidates.append(f"{path}/{index_name}")

    return candidates


def resolve_python_module_reference(current_path: str, module_name: str, known_paths: set[str], level: int = 0) -> str | None:
    normalized_module = str(module_name or "").strip()
    current_parent = PurePosixPath(current_path).parent
    candidates: List[str] = []

    if level > 0:
        relative_parent = current_parent
        for _ in range(max(level - 1, 0)):
            relative_parent = relative_parent.parent
        joined_parts = list(relative_parent.parts)
        if normalized_module:
            joined_parts.extend(normalized_module.split("."))
        if joined_parts:
            joined_path = normalize_posix_path("/".join(joined_parts))
            candidates.extend(expand_python_module_candidates(joined_path))

    if normalized_module:
        direct_parts = normalized_module.split(".")
        direct_path = normalize_posix_path("/".join(direct_parts))
        candidates.extend(expand_python_module_candidates(direct_path))

        for ancestor in [current_parent, *current_parent.parents]:
            if str(ancestor) in {".", ""}:
                continue
            joined_path = normalize_posix_path(str(ancestor / PurePosixPath(*direct_parts)))
            candidates.extend(expand_python_module_candidates(joined_path))

    seen = set()
    for candidate in candidates:
        if candidate in seen:
            continue
        seen.add(candidate)
        if candidate in known_paths:
            return candidate
    return None


def expand_python_module_candidates(path: str) -> List[str]:
    normalized = normalize_posix_path(path)
    return [
        f"{normalized}.py",
        f"{normalized}/__init__.py",
    ]


def extract_real_statements(relative_path: str, content: str) -> List[Dict[str, Any]]:
    suffix = PurePosixPath(relative_path).suffix

    if suffix == ".py":
        return extract_python_statements(content)
    if suffix in JS_SUFFIXES:
        return extract_js_statements(content)
    if suffix in STYLE_SUFFIXES:
        return extract_css_statements(content)
    if suffix == ".html":
        return extract_html_statements(content)
    if suffix == ".json":
        return extract_json_statements(content)
    if suffix == ".txt":
        return extract_text_statements(content)
    if suffix == ".md":
        return extract_text_statements(content)
    if suffix in {".cpp", ".cc", ".cxx", ".h", ".hpp"}:
        return fallback_text_statements(content)

    return []


def extract_python_statements(content: str) -> List[Dict[str, Any]]:
    try:
        module = ast.parse(content)
    except SyntaxError:
        return fallback_text_statements(content)

    statements: List[Dict[str, Any]] = []
    for node in module.body:
        statements.extend(flatten_python_node(node, content))

    return select_key_statements(statements, max_items=8)


def flatten_python_node(node: ast.AST, content: str) -> List[Dict[str, Any]]:
    if isinstance(node, (ast.Import, ast.ImportFrom)):
        return [python_statement(node, content, "io", priority=3)]

    if isinstance(node, ast.Try):
        statements = []
        for child in node.body[:1]:
            statements.extend(flatten_python_node(child, content))
        for handler in node.handlers[:1]:
            for child in handler.body[:1]:
                statements.extend(flatten_python_node(child, content))
        return statements

    if isinstance(node, (ast.Assign, ast.AnnAssign, ast.AugAssign)):
        statement = python_statement(node, content, "process", priority=4)
        if statement["text"].count("{") > 3 or len(statement["text"]) > 100:
            return []
        return [statement]

    if isinstance(node, ast.FunctionDef):
        decorators = [source_segment(decorator, content) for decorator in node.decorator_list]
        signature = f"def {node.name}(...):"
        if decorators:
            signature = f"{decorators[0]} {signature}"
        statements = [
            {
                "line": node.lineno,
                "text": signature,
                "type": "process",
                "priority": 12 if decorators else 8,
            }
        ]
        first_child = first_python_child(node.body)
        if first_child is not None:
            child_statement = python_statement(first_child, content, infer_python_step_type(first_child), priority=6)
            if len(child_statement["text"]) <= 90:
                statements.append(child_statement)
        return statements

    if isinstance(node, ast.If):
        statements = [python_statement(node, content, "decision", priority=11, force_text=f"if {source_segment(node.test, content)}:")]
        first_body = first_python_child(node.body)
        if first_body is not None:
            statements.append(python_statement(first_body, content, infer_python_step_type(first_body), priority=7))
        first_else = first_python_child(node.orelse)
        if first_else is not None:
            statements.append(python_statement(first_else, content, infer_python_step_type(first_else), priority=7))
        return statements

    if isinstance(node, ast.Expr):
        return [python_statement(node, content, infer_python_step_type(node), priority=6)]

    return [python_statement(node, content, infer_python_step_type(node), priority=5)]


def first_python_child(nodes: Sequence[ast.stmt]) -> ast.stmt | None:
    for node in nodes:
        if isinstance(node, ast.Expr) and isinstance(getattr(node, "value", None), ast.Constant) and isinstance(node.value.value, str):
            continue
        return node
    return None


def infer_python_step_type(node: ast.AST) -> str:
    text = source_segment(node, "")
    if isinstance(node, ast.If):
        return "decision"
    if isinstance(node, (ast.Return, ast.Yield)):
        return "io"
    if isinstance(node, ast.Expr):
        call = getattr(node, "value", None)
        if isinstance(call, ast.Call):
            callee = source_segment(call.func, "")
            if any(token in callee for token in ("emit", "jsonify", "run", "request")):
                return "io"
    if any(token in text for token in ("emit(", "jsonify(", "socketio.run", "request", "return ")):
        return "io"
    return "process"


def python_statement(node: ast.AST, content: str, step_type: str, priority: int, force_text: str | None = None) -> Dict[str, Any]:
    text = force_text or source_segment(node, content)
    return {
        "line": getattr(node, "lineno", 1),
        "text": compact_code(text),
        "type": step_type if step_type in FLOW_TYPES else "process",
        "priority": priority,
    }


def source_segment(node: ast.AST, content: str) -> str:
    if content:
        segment = ast.get_source_segment(content, node)
        if segment:
            return segment
    if isinstance(node, ast.Attribute):
        return f"{source_segment(node.value, content)}.{node.attr}"
    if isinstance(node, ast.Name):
        return node.id
    if isinstance(node, ast.Constant):
        return repr(node.value)
    return node.__class__.__name__


def extract_js_statements(content: str) -> List[Dict[str, Any]]:
    scope, line_offset = extract_default_export_scope(content)
    statements: List[Dict[str, Any]] = []

    for index, raw_line in enumerate(scope.splitlines(), start=1):
        line_no = line_offset + index
        compact = compact_code(raw_line)
        if not compact or compact in {"{", "}", ");", ")", "]", "];"}:
            continue
        if compact.startswith("//") or compact.startswith("*"):
            continue

        step_type = infer_js_step_type(compact)
        priority = score_js_line(compact)
        if priority <= 0:
            continue

        statements.append(
            {
                "line": line_no,
                "text": compact,
                "type": step_type,
                "priority": priority,
            }
        )

    return select_key_statements(statements, max_items=8)


def extract_default_export_scope(content: str) -> tuple[str, int]:
    match = re.search(r"export\s+default\s+function\b[^{]*\{", content)
    if not match:
        return content, 0

    start_index = content.find("{", match.start())
    end_index = find_matching_brace(content, start_index)
    if end_index <= start_index:
        return content, 0

    body = content[start_index + 1 : end_index]
    line_offset = content[: start_index + 1].count("\n")
    return body, line_offset


def find_matching_brace(content: str, start_index: int) -> int:
    depth = 0
    in_string = False
    quote = ""
    escaped = False

    for index in range(start_index, len(content)):
        char = content[index]
        if in_string:
            if escaped:
                escaped = False
                continue
            if char == "\\":
                escaped = True
                continue
            if char == quote:
                in_string = False
            continue

        if char in {'"', "'", "`"}:
            in_string = True
            quote = char
            continue

        if char == "{":
            depth += 1
        elif char == "}":
            depth -= 1
            if depth == 0:
                return index

    return len(content) - 1


def infer_js_step_type(line: str) -> str:
    if re.match(r"^(if|else if|switch|for|while)\b", line):
        return "decision"
    if any(token in line for token in ("socket.", "io(", "emit(", "render(", "appendChild(", "emit(")):
        return "io"
    if line.startswith("return"):
        return "io"
    return "process"


def score_js_line(line: str) -> int:
    if line.startswith("const [") or "useState(" in line:
        return 9
    if "useEffect" in line or "useMemo" in line:
        return 12
    if "socket.on" in line or "socket.emit" in line or "io(" in line:
        return 13
    if line.startswith("if ") or line.startswith("if(") or line.startswith("if ("):
        return 11
    if line.startswith("for ") or line.startswith("for(") or ".map(" in line:
        return 8
    if any(token in line for token in ("new THREE.", "renderer.", "scene.", "controls.", "requestAnimationFrame")):
        return 10
    if line.startswith("return"):
        return 11
    if line.startswith("const ") or line.startswith("let ") or line.startswith("function "):
        return 6
    if line.startswith("<") or line.startswith("</"):
        return 0
    return 4


def extract_css_statements(content: str) -> List[Dict[str, Any]]:
    statements = []
    for line_no, raw_line in enumerate(content.splitlines(), start=1):
        stripped = raw_line.strip()
        if not stripped or stripped.startswith("/*") or stripped.startswith("*"):
            continue
        if stripped.endswith("{") or stripped.startswith("@media"):
            statements.append({"line": line_no, "text": compact_code(stripped), "type": "process", "priority": 8})
        elif stripped.startswith("--"):
            statements.append({"line": line_no, "text": compact_code(stripped), "type": "process", "priority": 5})
    return select_key_statements(statements, max_items=8)


def extract_html_statements(content: str) -> List[Dict[str, Any]]:
    statements = []
    for line_no, raw_line in enumerate(content.splitlines(), start=1):
        stripped = raw_line.strip()
        if not stripped or stripped.startswith("<!doctype"):
            continue
        if stripped.startswith("<"):
            priority = 10 if "script" in stripped or 'id="root"' in stripped else 6
            step_type = "io" if "script" in stripped else "process"
            statements.append({"line": line_no, "text": compact_code(stripped), "type": step_type, "priority": priority})
    return select_key_statements(statements, max_items=8)


def extract_json_statements(content: str) -> List[Dict[str, Any]]:
    try:
        payload = json.loads(content)
    except json.JSONDecodeError:
        return fallback_text_statements(content)

    statements = []
    if isinstance(payload, dict):
        if not payload:
            statements.append(
                {
                    "line": 1,
                    "text": "{}",
                    "type": "process",
                    "priority": 8,
                }
            )
        for index, (key, value) in enumerate(payload.items(), start=1):
            summary = summarize_json_value(value)
            statements.append(
                {
                    "line": index,
                    "text": compact_code(f'"{key}": {summary}'),
                    "type": "process",
                    "priority": 10 if key in {"scripts", "dependencies", "name"} else 6,
                }
            )
    elif isinstance(payload, list):
        if not payload:
            statements.append(
                {
                    "line": 1,
                    "text": "[0 items]",
                    "type": "process",
                    "priority": 8,
                }
            )
        for index, value in enumerate(payload[:8], start=1):
            statements.append(
                {
                    "line": index,
                    "text": compact_code(f"[{index - 1}] {summarize_json_value(value)}"),
                    "type": "process",
                    "priority": 8,
                }
            )
    else:
        statements.append(
            {
                "line": 1,
                "text": compact_code(summarize_json_value(payload)),
                "type": "process",
                "priority": 8,
            }
        )
    return select_key_statements(statements, max_items=8)


def summarize_json_value(value: Any) -> str:
    if isinstance(value, dict):
        return "{" + ", ".join(list(value.keys())[:4]) + ("..." if len(value) > 4 else "") + "}"
    if isinstance(value, list):
        return f"[{len(value)} items]"
    return json.dumps(value, ensure_ascii=True)


def extract_text_statements(content: str) -> List[Dict[str, Any]]:
    statements = []
    for line_no, raw_line in enumerate(content.splitlines(), start=1):
        stripped = raw_line.strip()
        if not stripped:
            continue
        statements.append({"line": line_no, "text": stripped, "type": "io", "priority": 8})
    return select_key_statements(statements, max_items=8)


def fallback_text_statements(content: str) -> List[Dict[str, Any]]:
    statements = []
    for line_no, raw_line in enumerate(content.splitlines(), start=1):
        compact = compact_code(raw_line)
        if not compact:
            continue
        statements.append({"line": line_no, "text": compact, "type": "process", "priority": 4})
    return select_key_statements(statements, max_items=8)


def select_key_statements(statements: List[Dict[str, Any]], max_items: int) -> List[Dict[str, Any]]:
    cleaned = []
    seen = set()
    for statement in statements:
        text = statement["text"]
        if not text or text in seen:
            continue
        seen.add(text)
        cleaned.append(statement)

    if len(cleaned) <= max_items:
        return cleaned

    ranked = sorted(cleaned, key=lambda item: (-item["priority"], item["line"]))
    selected_lines = sorted(item["line"] for item in ranked[:max_items])
    return [item for item in cleaned if item["line"] in selected_lines]


class FlowGraphBuilder:
    def __init__(self, language: str, title: str) -> None:
        self.language = language
        self.title = title
        self.steps: List[Dict[str, Any]] = [{"id": "start", "type": "start", "label": "Inicio", "x": 300, "y": 46, "line": 0}]
        self.edges: List[Dict[str, Any]] = []
        self.step_count = 0

    def add_step(self, step_type: str, label: str, line: int, x: float, y: float, code: str | None = None) -> str:
        self.step_count += 1
        step_id = f"step-{self.step_count}"
        self.steps.append(
            {
                "id": step_id,
                "type": step_type if step_type in FLOW_TYPES else "process",
                "label": wrap_code_label(label),
                "x": round(x, 2),
                "y": round(y, 2),
                "line": int(line or 0),
                "code": compact_code(code or label),
                "codeLanguage": self.language,
                "color": None,
            }
        )
        return step_id

    def add_edge(self, source_id: str, target_id: str, label: str = "") -> None:
        if not source_id or not target_id or source_id == target_id:
            return

        edge = {"from": source_id, "to": target_id}
        if label:
            edge["label"] = label
        self.edges.append(edge)

    def connect(self, pending_links: List[Dict[str, Any]], target_id: str) -> None:
        for link in pending_links:
            self.add_edge(str(link.get("id") or ""), target_id, str(link.get("label") or ""))

    def finalize(self, pending_links: List[Dict[str, Any]], end_y: float) -> Dict[str, Any]:
        self.steps.append({"id": "end", "type": "end", "label": "Fin", "x": 300, "y": round(end_y, 2), "line": 0})
        self.connect(pending_links or [{"id": "start", "label": ""}], "end")
        return {
            "title": self.title,
            "source": "real_source",
            "steps": self.steps,
            "edges": self.edges,
        }


def build_real_algorithm(relative_path: str, content: str, statements: List[Dict[str, Any]]) -> Dict[str, Any]:
    suffix = PurePosixPath(relative_path).suffix.lower()

    if suffix == ".py":
        algorithm = build_python_algorithm(relative_path, content)
        if algorithm:
            return algorithm
    if suffix in JS_SUFFIXES:
        algorithm = build_js_algorithm(relative_path, content)
        if algorithm:
            return algorithm
    return build_algorithm(relative_path, statements)


def build_python_algorithm(relative_path: str, content: str) -> Dict[str, Any] | None:
    try:
        module = ast.parse(content)
    except SyntaxError:
        return None

    entry = select_python_entry(module)
    entry_body = entry.get("body") if isinstance(entry, dict) else None
    if not isinstance(entry_body, list):
        return None

    builder = FlowGraphBuilder("python", f"Algoritmo real de {PurePosixPath(relative_path).name}")
    pending_links = [{"id": "start", "label": ""}]
    current_y = 156.0

    entry_label = str(entry.get("label") or "").strip()
    entry_line = int(entry.get("line") or 0)
    if entry_label:
        entry_step_id = builder.add_step("process", entry_label, entry_line, 300, current_y, entry_label)
        builder.connect(pending_links, entry_step_id)
        pending_links = [{"id": entry_step_id, "label": ""}]
        current_y += 120

    pending_links, current_y = walk_python_sequence(
        builder,
        entry_body,
        content,
        pending_links,
        300,
        current_y,
        340,
    )
    return builder.finalize(pending_links, max(current_y, 280))


def select_python_entry(module: ast.Module) -> Dict[str, Any]:
    functions = [node for node in module.body if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef))]
    entry_guard = next((node for node in module.body if is_python_main_guard(node)), None)
    if isinstance(entry_guard, ast.If):
        called_name = first_called_name(entry_guard.body)
        target = next((node for node in functions if node.name == called_name), None)
        if target is not None:
            return {
                "label": format_python_function_signature(target),
                "line": target.lineno,
                "body": list(target.body),
            }
        return {
            "label": "if __name__ == '__main__':",
            "line": entry_guard.lineno,
            "body": list(entry_guard.body),
        }

    preferred_names = {"main", "run", "bootstrap", "start", "init_app", "create_app", "handle_request", "serve", "build_app"}
    ranked_functions = sorted(
        functions,
        key=lambda node: (
            0 if node.name in preferred_names else 1,
            0 if node.decorator_list else 1,
            node.lineno,
        ),
    )
    if ranked_functions:
        target = ranked_functions[0]
        return {
            "label": format_python_function_signature(target),
            "line": target.lineno,
            "body": list(target.body),
        }

    body = [node for node in module.body if not isinstance(node, (ast.Import, ast.ImportFrom))]
    return {
        "label": "",
        "line": 1,
        "body": body or list(module.body),
    }


def is_python_main_guard(node: ast.AST) -> bool:
    if not isinstance(node, ast.If):
        return False
    test = node.test
    if not isinstance(test, ast.Compare) or len(test.ops) != 1 or len(test.comparators) != 1:
        return False
    return (
        isinstance(test.left, ast.Name)
        and test.left.id == "__name__"
        and isinstance(test.ops[0], ast.Eq)
        and isinstance(test.comparators[0], ast.Constant)
        and test.comparators[0].value == "__main__"
    )


def first_called_name(nodes: Sequence[ast.stmt]) -> str | None:
    for node in nodes:
        for child in ast.walk(node):
            if isinstance(child, ast.Call):
                return called_name_from_ast(child.func)
    return None


def called_name_from_ast(node: ast.AST) -> str | None:
    if isinstance(node, ast.Name):
        return node.id
    if isinstance(node, ast.Attribute):
        return node.attr
    return None


def format_python_function_signature(node: ast.FunctionDef | ast.AsyncFunctionDef) -> str:
    prefix = "async def" if isinstance(node, ast.AsyncFunctionDef) else "def"
    return f"{prefix} {node.name}(...)"


def walk_python_sequence(
    builder: FlowGraphBuilder,
    statements: Sequence[ast.stmt],
    content: str,
    pending_links: List[Dict[str, Any]],
    center_x: float,
    current_y: float,
    lane_width: float,
) -> tuple[List[Dict[str, Any]], float]:
    active_links = pending_links
    next_y = current_y

    for node in statements:
        if isinstance(node, ast.Expr) and isinstance(getattr(node, "value", None), ast.Constant) and isinstance(node.value.value, str):
            continue

        if isinstance(node, ast.If):
            label = compact_code(f"if {source_segment(node.test, content)}:")
            decision_id = builder.add_step("decision", label, node.lineno, center_x, next_y, label)
            builder.connect(active_links, decision_id)

            branch_y = next_y + 152
            branch_width = max(170, lane_width * 0.68)
            true_links, true_y = walk_python_sequence(
                builder,
                node.body,
                content,
                [{"id": decision_id, "label": "Si"}],
                center_x - branch_width / 2,
                branch_y,
                branch_width,
            )
            if node.orelse:
                false_links, false_y = walk_python_sequence(
                    builder,
                    node.orelse,
                    content,
                    [{"id": decision_id, "label": "No"}],
                    center_x + branch_width / 2,
                    branch_y,
                    branch_width,
                )
            else:
                false_links = [{"id": decision_id, "label": "No"}]
                false_y = branch_y

            active_links = true_links + false_links
            next_y = max(true_y, false_y) + 132
            continue

        if isinstance(node, (ast.For, ast.AsyncFor, ast.While)):
            if isinstance(node, ast.While):
                label = compact_code(f"while {source_segment(node.test, content)}:")
            else:
                label = compact_code(f"for {source_segment(node.target, content)} in {source_segment(node.iter, content)}:")

            loop_id = builder.add_step("decision", label, node.lineno, center_x, next_y, label)
            builder.connect(active_links, loop_id)
            body_y = next_y + 152
            body_links, body_end_y = walk_python_sequence(
                builder,
                node.body,
                content,
                [{"id": loop_id, "label": "Itera"}],
                center_x - max(120, lane_width * 0.18),
                body_y,
                max(170, lane_width * 0.72),
            )
            for link in body_links:
                builder.add_edge(str(link.get("id") or ""), loop_id, str(link.get("label") or "Repite"))

            active_links = [{"id": loop_id, "label": "Sale"}]
            next_y = body_end_y + 132
            continue

        if isinstance(node, ast.Try):
            try_label = "try"
            try_id = builder.add_step("process", try_label, node.lineno, center_x, next_y, try_label)
            builder.connect(active_links, try_id)
            branch_y = next_y + 146
            body_links, body_y = walk_python_sequence(
                builder,
                node.body,
                content,
                [{"id": try_id, "label": "Ok"}],
                center_x - max(100, lane_width * 0.18),
                branch_y,
                lane_width,
            )
            except_links: List[Dict[str, Any]] = []
            except_y = branch_y
            for handler_index, handler in enumerate(node.handlers, start=1):
                handler_label = compact_code(f"except {source_segment(handler.type, content) if handler.type else 'Exception'}:")
                catch_id = builder.add_step("process", handler_label, handler.lineno, center_x + max(120, lane_width * 0.22), branch_y + (handler_index - 1) * 118, handler_label)
                builder.add_edge(try_id, catch_id, "Error")
                handler_links, handler_end_y = walk_python_sequence(
                    builder,
                    handler.body,
                    content,
                    [{"id": catch_id, "label": "Maneja"}],
                    center_x + max(180, lane_width * 0.32),
                    branch_y + handler_index * 118,
                    lane_width,
                )
                except_links.extend(handler_links)
                except_y = max(except_y, handler_end_y)

            active_links = body_links + except_links
            if node.finalbody:
                active_links, final_y = walk_python_sequence(
                    builder,
                    node.finalbody,
                    content,
                    active_links,
                    center_x,
                    max(body_y, except_y) + 124,
                    lane_width,
                )
                next_y = final_y + 114
            else:
                next_y = max(body_y, except_y) + 124
            continue

        step_type = infer_python_step_type(node)
        text = format_python_flow_label(node, content)
        step_id = builder.add_step(step_type, text, getattr(node, "lineno", 1), center_x, next_y, source_segment(node, content))
        builder.connect(active_links, step_id)
        active_links = [{"id": step_id, "label": ""}]
        next_y += 118 if step_type == "decision" else 106

    return active_links, next_y


def format_python_flow_label(node: ast.AST, content: str) -> str:
    if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
        return format_python_function_signature(node)
    if isinstance(node, ast.Return):
        return compact_code(f"return {source_segment(node.value, content) if node.value else ''}".strip())
    if isinstance(node, ast.Assign):
        return compact_code(source_segment(node, content))
    if isinstance(node, ast.AnnAssign):
        return compact_code(source_segment(node, content))
    if isinstance(node, ast.AugAssign):
        return compact_code(source_segment(node, content))
    return compact_code(source_segment(node, content))


def build_js_algorithm(relative_path: str, content: str) -> Dict[str, Any] | None:
    scope, line_offset, label = select_js_entry_scope(content)
    if not scope.strip():
        return None

    flow_lines = extract_js_flow_lines(scope, line_offset)
    if not flow_lines:
        return None

    builder = FlowGraphBuilder(detect_code_language(relative_path), f"Algoritmo real de {PurePosixPath(relative_path).name}")
    pending_links = [{"id": "start", "label": ""}]
    current_y = 156.0

    if label:
        entry_step_id = builder.add_step("process", label, max(line_offset, 1), 300, current_y, label)
        builder.connect(pending_links, entry_step_id)
        pending_links = [{"id": entry_step_id, "label": ""}]
        current_y += 120

    pending_links, current_y, _ = walk_js_block(
        builder,
        flow_lines,
        0,
        0,
        pending_links,
        300,
        current_y,
        340,
    )
    return builder.finalize(pending_links, max(current_y, 280))


def select_js_entry_scope(content: str) -> tuple[str, int, str]:
    export_match = re.search(r"export\s+default\s+function\s+([A-Za-z0-9_]*)?[^{]*\{", content)
    if export_match:
        function_name = export_match.group(1) or "default"
        start_index = content.find("{", export_match.start())
        end_index = find_matching_brace(content, start_index)
        body = content[start_index + 1 : end_index]
        line_offset = content[: start_index + 1].count("\n")
        return body, line_offset, f"export default function {function_name}(...)"

    preferred_name_priority = {
        "main": 0,
        "run": 0,
        "bootstrap": 0,
        "start": 0,
        "init": 0,
        "initialize": 0,
        "initializeApp": 0,
        "mount": 1,
        "setup": 1,
        "App": 2,
        "render": 4,
    }
    named_matches = []
    for pattern in (
        r"((?:async\s+)?function\s+([A-Za-z_$][\w$]*)\b[^{]*\{)",
        r"((?:const|let|var)\s+([A-Za-z_$][\w$]*)\s*=\s*(?:async\s*)?(?:\([^)]*\)|[A-Za-z0-9_]+)\s*=>\s*\{)",
    ):
        for match in re.finditer(pattern, content):
            name = match.group(2) or "entry"
            start_index = content.find("{", match.start())
            end_index = find_matching_brace(content, start_index)
            invocation_count = len(re.findall(rf"\b(?:void\s+)?{re.escape(name)}\s*\(", content))
            named_matches.append(
                {
                    "name": name,
                    "start": start_index,
                    "end": end_index,
                    "score": (
                        preferred_name_priority.get(name, 3),
                        0 if re.search(r"(init|start|bootstrap|mount|setup)", name, re.IGNORECASE) else 1,
                        0 if re.search(r"(load|handle|save|bind|render)", name, re.IGNORECASE) else 1,
                        0 if invocation_count > 1 else 1,
                        match.start(),
                    ),
                }
            )

    if named_matches:
        target = sorted(named_matches, key=lambda item: item["score"])[0]
        body = content[target["start"] + 1 : target["end"]]
        line_offset = content[: target["start"] + 1].count("\n")
        return body, line_offset, f"{target['name']}(...)"

    scope, line_offset = extract_default_export_scope(content)
    return scope, line_offset, ""


def extract_js_flow_lines(scope: str, line_offset: int) -> List[Dict[str, Any]]:
    depths = js_depths_by_line(scope)
    flow_lines: List[Dict[str, Any]] = []

    for index, raw_line in enumerate(scope.splitlines(), start=1):
        stripped = compact_code(raw_line)
        if not stripped or stripped in {"{", "}", ");", ")", "]", "];"}:
            continue
        if stripped.startswith(("//", "*", "/*")) or stripped.startswith("<") or stripped.startswith("</"):
            continue

        kind = classify_js_flow_line(stripped)
        if kind is None:
            continue

        flow_lines.append(
            {
                "line": line_offset + index,
                "text": stripped,
                "type": infer_js_step_type(stripped),
                "kind": kind,
                "depth": depths[index - 1] if index - 1 < len(depths) else 0,
                "opensBlock": "{" in raw_line,
            }
        )

    return flow_lines


def js_depths_by_line(content: str) -> List[int]:
    depths: List[int] = []
    depth = 0
    in_string = False
    quote = ""
    escaped = False
    in_block_comment = False

    for raw_line in content.splitlines():
        depths.append(max(depth, 0))
        index = 0
        while index < len(raw_line):
            char = raw_line[index]
            next_char = raw_line[index + 1] if index + 1 < len(raw_line) else ""

            if in_block_comment:
                if char == "*" and next_char == "/":
                    in_block_comment = False
                    index += 2
                    continue
                index += 1
                continue

            if in_string:
                if escaped:
                    escaped = False
                elif char == "\\":
                    escaped = True
                elif char == quote:
                    in_string = False
                index += 1
                continue

            if char == "/" and next_char == "/":
                break
            if char == "/" and next_char == "*":
                in_block_comment = True
                index += 2
                continue
            if char in {'"', "'", "`"}:
                in_string = True
                quote = char
                index += 1
                continue
            if char == "{":
                depth += 1
            elif char == "}":
                depth = max(0, depth - 1)
            index += 1

    return depths


def classify_js_flow_line(line: str) -> str | None:
    if re.match(r"^if\s*\(", line):
        return "if"
    if re.match(r"^else\s+if\s*\(", line):
        return "else_if"
    if re.match(r"^else\b", line):
        return "else"
    if re.match(r"^(for|while)\s*\(", line):
        return "loop"
    if re.match(r"^return\b", line):
        return "return"
    if re.match(r"^(const|let|var)\s+[A-Za-z_$][\w$]*\s*=\s*(?:async\s*)?(?:\([^)]*\)|[A-Za-z_$][\w$]*)\s*=>", line):
        return "function"
    if re.match(r"^(?:async\s+)?function\s+[A-Za-z_$][\w$]*\s*\(", line):
        return "function"
    if any(token in line for token in ("fetch(", "socket.", "emit(", "addEventListener(", "appendChild(", "render(", "setState(", "dispatch(")):
        return "io"
    if line.startswith(("const ", "let ", "var ", "await ", "document.", "window.")):
        return "process"
    return None


def walk_js_block(
    builder: FlowGraphBuilder,
    flow_lines: Sequence[Dict[str, Any]],
    start_index: int,
    depth: int,
    pending_links: List[Dict[str, Any]],
    center_x: float,
    current_y: float,
    lane_width: float,
) -> tuple[List[Dict[str, Any]], float, int]:
    active_links = pending_links
    next_y = current_y
    index = start_index

    while index < len(flow_lines):
        line = flow_lines[index]
        line_depth = int(line.get("depth") or 0)
        kind = str(line.get("kind") or "")

        if line_depth < depth:
            break
        if line_depth > depth:
            index += 1
            continue
        if kind in {"else", "else_if"} and index != start_index:
            break

        if kind in {"if", "else_if"}:
            decision_id = builder.add_step("decision", str(line.get("text") or ""), int(line.get("line") or 0), center_x, next_y, str(line.get("text") or ""))
            builder.connect(active_links, decision_id)

            branch_y = next_y + 152
            branch_width = max(170, lane_width * 0.68)
            true_links, true_y, next_index = walk_js_block(
                builder,
                flow_lines,
                index + 1,
                depth + 1,
                [{"id": decision_id, "label": "Si"}],
                center_x - branch_width / 2,
                branch_y,
                branch_width,
            ) if line.get("opensBlock") else ([{"id": decision_id, "label": "Si"}], branch_y, index + 1)

            false_links: List[Dict[str, Any]] = [{"id": decision_id, "label": "No"}]
            false_y = branch_y
            index = next_index
            if index < len(flow_lines):
                next_line = flow_lines[index]
                next_kind = str(next_line.get("kind") or "")
                next_depth = int(next_line.get("depth") or 0)
                if next_depth == depth and next_kind in {"else", "else_if"}:
                    false_center_x = center_x + branch_width / 2
                    if next_kind == "else_if":
                        false_links, false_y, index = walk_js_block(
                            builder,
                            flow_lines,
                            index,
                            depth,
                            [{"id": decision_id, "label": "No"}],
                            false_center_x,
                            branch_y,
                            branch_width,
                        )
                    else:
                        false_links, false_y, index = walk_js_block(
                            builder,
                            flow_lines,
                            index + 1,
                            depth + 1,
                            [{"id": decision_id, "label": "No"}],
                            false_center_x,
                            branch_y,
                            branch_width,
                        ) if next_line.get("opensBlock") else ([{"id": decision_id, "label": "No"}], branch_y, index + 1)

            active_links = true_links + false_links
            next_y = max(true_y, false_y) + 132
            continue

        if kind == "loop":
            loop_id = builder.add_step("decision", str(line.get("text") or ""), int(line.get("line") or 0), center_x, next_y, str(line.get("text") or ""))
            builder.connect(active_links, loop_id)
            body_y = next_y + 152
            body_links, body_end_y, index = walk_js_block(
                builder,
                flow_lines,
                index + 1,
                depth + 1,
                [{"id": loop_id, "label": "Itera"}],
                center_x - max(120, lane_width * 0.18),
                body_y,
                max(170, lane_width * 0.72),
            ) if line.get("opensBlock") else ([{"id": loop_id, "label": "Itera"}], body_y, index + 1)
            for link in body_links:
                builder.add_edge(str(link.get("id") or ""), loop_id, str(link.get("label") or "Repite"))
            active_links = [{"id": loop_id, "label": "Sale"}]
            next_y = body_end_y + 132
            continue

        step_id = builder.add_step(
            str(line.get("type") or "process"),
            str(line.get("text") or ""),
            int(line.get("line") or 0),
            center_x,
            next_y,
            str(line.get("text") or ""),
        )
        builder.connect(active_links, step_id)
        active_links = [{"id": step_id, "label": ""}]
        next_y += 118 if line.get("type") == "decision" else 106
        index += 1

    return active_links, next_y, index


def build_algorithm(relative_path: str, statements: List[Dict[str, Any]]) -> Dict[str, Any]:
    if not statements:
        statements = [{"line": 1, "text": relative_path, "type": "process", "priority": 1}]

    language = detect_code_language(relative_path)
    steps = [{"id": "start", "type": "start", "label": "Inicio", "x": 300, "y": 46}]
    edges = []
    y = 156
    previous_id = "start"

    for index, statement in enumerate(statements, start=1):
        step_id = f"step-{index}"
        steps.append(
            {
                "id": step_id,
                "type": statement["type"] if statement["type"] in FLOW_TYPES else "process",
                "label": wrap_code_label(f"L{statement['line']} {statement['text']}"),
                "x": 300,
                "y": y,
                "line": int(statement["line"]),
                "code": statement["text"],
                "codeLanguage": language,
                "color": None,
            }
        )
        edges.append({"from": previous_id, "to": step_id})
        previous_id = step_id
        y += 118 if statement["type"] == "decision" else 106

    steps.append({"id": "end", "type": "end", "label": "Fin", "x": 300, "y": y, "line": 0})
    edges.append({"from": previous_id, "to": "end"})

    return {
        "title": f"Algoritmo real de {PurePosixPath(relative_path).name}",
        "source": "real_source",
        "steps": steps,
        "edges": edges,
    }


def wrap_code_label(text: str, max_chars: int = 24, max_lines: int = 4) -> str:
    words = text.split()
    if not words:
        return ""

    lines: List[str] = []
    current = ""

    for word in words:
        candidate = f"{current} {word}".strip()
        if not current or len(candidate) <= max_chars:
            current = candidate
            continue
        lines.append(current)
        current = word
        if len(lines) == max_lines - 1:
            break

    if current and len(lines) < max_lines:
        lines.append(current)

    consumed = len(" ".join(lines).split())
    if consumed < len(words) and lines:
        lines[-1] = f"{lines[-1]}..."

    return "\n".join(lines[:max_lines])


def compact_code(text: str) -> str:
    return re.sub(r"\s+", " ", text or "").strip()


def format_size(byte_count: int) -> str:
    if byte_count < 1024:
        return f"{byte_count} B"
    return f"{byte_count / 1024:.1f} KB"


def count_lines(content: str) -> int:
    return len(content.splitlines())


def infer_layer(relative_path: str) -> str:
    file_name = PurePosixPath(relative_path).name
    suffix = PurePosixPath(relative_path).suffix
    workspace_project = workspace_project_slug(relative_path)

    if file_name in CONFIG_FILES:
        return "config"
    if suffix in STYLE_SUFFIXES:
        return "style"
    if suffix == ".md" or "/docs/" in relative_path:
        return "docs"
    if relative_path.startswith("backend/data/") or "/backend/data/" in relative_path:
        return "data"
    if workspace_project:
        return workspace_project
    if relative_path.startswith("microservice-js/"):
        return "microservice"
    if relative_path.startswith("backend/"):
        return "backend"
    if relative_path.startswith("frontend/"):
        return "frontend"
    return "script"


def infer_status(relative_path: str) -> str:
    file_name = PurePosixPath(relative_path).name
    if file_name in {"app.py", "App.jsx", "ArchitectureCanvas.jsx", "AlgorithmFlow.jsx"}:
        return "modified"
    if file_name in CONFIG_FILES:
        return "generated"
    return "generated"


def detect_code_language(relative_path: str) -> str:
    suffix = PurePosixPath(relative_path).suffix.lower()
    return {
        ".py": "python",
        ".js": "javascript",
        ".jsx": "jsx",
        ".ts": "typescript",
        ".tsx": "tsx",
        ".css": "css",
        ".html": "html",
        ".json": "json",
        ".txt": "text",
        ".md": "markdown",
        ".cpp": "cpp",
        ".cc": "cpp",
        ".cxx": "cpp",
        ".h": "cpp",
        ".hpp": "cpp",
    }.get(suffix, "text")


def layer_label_for_path(relative_path: str) -> str:
    workspace_project = workspace_project_slug(relative_path)
    if workspace_project:
        return workspace_project.replace("-", " ").title()

    layer = infer_layer(relative_path)
    return {
        "frontend": "Frontend",
        "backend": "Backend",
        "data": "Data",
        "microservice": "Microservice",
        "shared": "Shared",
        "docs": "Docs",
        "style": "Style",
        "config": "Config",
        "script": "Script",
    }.get(layer, layer.replace("-", " ").title())


def default_color_for_layer(layer: str) -> str:
    if layer in DEFAULT_LAYER_COLORS:
        return DEFAULT_LAYER_COLORS[layer]
    palette_index = sum(ord(char) for char in layer) % len(CUSTOM_LAYER_COLORS)
    return CUSTOM_LAYER_COLORS[palette_index]


def describe_file(relative_path: str, statements: List[Dict[str, Any]]) -> str:
    suffix = PurePosixPath(relative_path).suffix
    step_count = len(statements)
    if suffix == ".py":
        return f"Archivo Python con {step_count} pasos extraidos del codigo real del servidor."
    if suffix in JS_SUFFIXES:
        return f"Modulo JavaScript/React con {step_count} pasos tomados del componente o flujo real."
    if suffix == ".css":
        return f"Hoja de estilos con {step_count} reglas o bloques reales relevantes."
    if suffix == ".html":
        return f"Documento HTML con {step_count} elementos clave del flujo de carga."
    if suffix == ".json":
        return f"Configuracion JSON con {step_count} claves reales del proyecto."
    if suffix == ".md":
        return f"Documento Markdown con {step_count} fragmentos reales usados para explicar la arquitectura."
    return f"Archivo real del proyecto con {step_count} fragmentos relevantes."


def infer_edge_type(source_node: Dict[str, Any], target_node: Dict[str, Any] | None) -> str:
    if not target_node:
        return "uses"
    if source_node["layer"] in {"frontend", "microservice"} and target_node["layer"] == "backend":
        return "socket"
    if source_node["layer"] == "backend" and target_node["layer"] == "microservice":
        return "socket"
    if source_node["layer"] not in DEFAULT_LAYER_COLORS and target_node["layer"] == "backend":
        return "socket"
    if source_node["layer"] == "backend" and target_node["layer"] not in DEFAULT_LAYER_COLORS:
        return "socket"
    if source_node["layer"] == "config" or target_node["layer"] == "config":
        return "import"
    if source_node["layer"] == "style" or target_node["layer"] == "style":
        return "reference"
    return "uses"


def infer_edge_label(source_node: Dict[str, Any], target_node: Dict[str, Any] | None) -> str:
    if not target_node:
        return "usa"
    if source_node["layer"] == "frontend" and target_node["layer"] == "backend":
        return "consume backend"
    if source_node["layer"] == "microservice" and target_node["layer"] == "backend":
        return "sincroniza ecosistema"
    if source_node["layer"] == "backend" and target_node["layer"] == "microservice":
        return "publica pulso"
    if source_node["layer"] not in DEFAULT_LAYER_COLORS and target_node["layer"] == "backend":
        return "conecta servicio"
    if source_node["layer"] == "backend" and target_node["layer"] not in DEFAULT_LAYER_COLORS:
        return "orquesta proyecto"
    if source_node["layer"] == "config":
        return "define runtime"
    if target_node["layer"] == "config":
        return "requiere config"
    if target_node["layer"] == "style":
        return "aplica estilo"
    return "importa"


def workspace_project_slug(relative_path: str) -> str | None:
    path = PurePosixPath(relative_path)
    parts = path.parts
    if len(parts) >= 3 and parts[0] == "workspace" and parts[1] == "projects":
        return re.sub(r"[^a-z0-9]+", "-", parts[2].lower()).strip("-") or parts[2].lower()
    return None


def node_id_for_path(relative_path: str) -> str:
    return normalize_posix_path(relative_path).replace("/", "__").replace(".", "_")


def normalize_posix_path(value: str) -> str:
    return to_posix(PurePosixPath(os.path.normpath(value)))


def to_posix(path: os.PathLike[str] | PurePosixPath | str) -> str:
    return str(path).replace("\\", "/")

from __future__ import annotations

import ast
import hashlib
import re
from datetime import datetime, timezone
from pathlib import Path, PurePosixPath
from typing import Any, Dict, Iterable, List

from project_graph import (
    IGNORED_FILES,
    IGNORED_PARTS,
    JS_SUFFIXES,
    SUPPORTED_SUFFIXES,
    STYLE_SUFFIXES,
    build_real_algorithm,
    count_lines,
    describe_file,
    detect_code_language,
    extract_html_references,
    extract_js_imports,
    extract_real_statements,
    extract_python_import_references,
    format_size,
    infer_edge_label,
    infer_edge_type,
    layer_label_for_path,
    node_id_for_path,
    normalize_posix_path,
    to_posix,
)

ANALYSIS_PATH_PREFIX = "analysis/projects"
ANALYSIS_CONTENT_FOLDERS = {"src", "backend", "frontend", "shared", "tests", "docs", "algorithms", "assets", "data"}
MAX_FILE_ANALYSIS = 80
MAX_DIRECTORY_ANALYSIS = 240


def utc_now() -> str:
    return datetime.now(timezone.utc).isoformat()


def slugify(value: str) -> str:
    return re.sub(r"[^a-z0-9]+", "-", str(value or "").strip().lower()).strip("-") or "analysis"


def build_analysis_entry(target_path: str) -> Dict[str, Any]:
    resolved_target = Path(target_path).expanduser().resolve()
    if not resolved_target.exists():
        raise FileNotFoundError(f"No existe la ruta: {resolved_target}")

    mode = "directory" if resolved_target.is_dir() else "file"
    digest = hashlib.sha1(str(resolved_target).encode("utf-8")).hexdigest()[:8]
    base_name = resolved_target.name if resolved_target.is_dir() else resolved_target.stem
    analysis_id = f"reverse-{slugify(base_name)}-{digest}"
    files = discover_analysis_files(resolved_target, mode)
    graph = build_analysis_graph(resolved_target, files, analysis_id, mode)
    primary_node_id = find_primary_node_id(graph, resolved_target)

    return {
        "id": analysis_id,
        "label": resolved_target.name or str(resolved_target),
        "targetPath": str(resolved_target),
        "mode": mode,
        "createdAt": utc_now(),
        "primaryNodeId": primary_node_id,
        "summary": {
            "nodes": len(graph.get("nodes") or []),
            "edges": len(graph.get("edges") or []),
        },
        "graph": graph,
    }


def discover_analysis_files(target_path: Path, mode: str) -> List[Path]:
    if mode == "directory":
        return discover_directory_files(target_path)
    return discover_file_scope(target_path)


def discover_directory_files(target_dir: Path) -> List[Path]:
    files: List[Path] = []
    for file_path in target_dir.rglob("*"):
        if len(files) >= MAX_DIRECTORY_ANALYSIS:
            break
        if not file_path.is_file():
            continue
        if any(part in IGNORED_PARTS for part in file_path.parts):
            continue
        if file_path.name in IGNORED_FILES or file_path.suffix.lower() not in SUPPORTED_SUFFIXES:
            continue
        files.append(file_path.resolve())
    return sorted(files, key=lambda item: str(item))


def discover_file_scope(target_file: Path) -> List[Path]:
    root_dir = infer_file_scope_root(target_file)
    discovered: List[Path] = []
    seen = set()
    queue = [target_file.resolve()]

    while queue and len(discovered) < MAX_FILE_ANALYSIS:
        current_path = queue.pop(0)
        if current_path in seen:
            continue
        seen.add(current_path)

        if not current_path.is_file():
            continue
        if current_path.suffix.lower() not in SUPPORTED_SUFFIXES or current_path.name in IGNORED_FILES:
            continue
        if any(part in IGNORED_PARTS for part in current_path.parts):
            continue

        discovered.append(current_path)
        for dependency in resolve_local_dependencies(current_path, root_dir):
            if dependency not in seen:
                queue.append(dependency)

    return sorted(discovered, key=lambda item: str(item))


def infer_file_scope_root(target_file: Path) -> Path:
    target_file = target_file.resolve()
    current_dir = target_file.parent

    while (current_dir / "__init__.py").exists() and current_dir.parent != current_dir:
        current_dir = current_dir.parent

    for marker in ("pyproject.toml", "setup.py", "requirements.txt", ".git", "README.md"):
        if (current_dir / marker).exists():
            return current_dir

    return current_dir


def resolve_local_dependencies(current_file: Path, root_dir: Path) -> List[Path]:
    try:
        content = current_file.read_text(encoding="utf-8")
    except OSError:
        return []

    suffix = current_file.suffix.lower()
    dependencies: List[Path] = []

    if suffix in JS_SUFFIXES:
        for specifier in extract_js_imports(content):
            resolved = resolve_local_specifier_actual(current_file, root_dir, specifier)
            if resolved:
                dependencies.append(resolved)
    if suffix == ".html":
        for specifier in extract_html_references(content):
            resolved = resolve_local_specifier_actual(current_file, root_dir, specifier)
            if resolved:
                dependencies.append(resolved)
    if suffix in STYLE_SUFFIXES:
        for specifier in re.findall(r'@import\s+["\']([^"\']+)["\']', content):
            resolved = resolve_local_specifier_actual(current_file, root_dir, specifier)
            if resolved:
                dependencies.append(resolved)
    if suffix == ".py":
        dependencies.extend(resolve_local_python_dependencies(current_file, root_dir, content))

    unique = []
    seen = set()
    for dependency in dependencies:
        resolved_dependency = dependency.resolve()
        if resolved_dependency in seen:
            continue
        seen.add(resolved_dependency)
        unique.append(resolved_dependency)
    return unique


def resolve_local_specifier_actual(current_file: Path, root_dir: Path, specifier: str) -> Path | None:
    normalized = str(specifier or "").strip()
    if not normalized or not normalized.startswith((".", "/")):
        return None

    candidates: List[Path] = []
    if normalized.startswith("/"):
        joined = root_dir / normalized.lstrip("/")
        candidates.extend(expand_actual_candidates(joined))
    else:
        joined = (current_file.parent / normalized).resolve()
        candidates.extend(expand_actual_candidates(joined))

    for candidate in candidates:
        if candidate.is_file() and is_within_root(candidate, root_dir):
            return candidate.resolve()
    return None


def resolve_local_python_dependencies(current_file: Path, root_dir: Path, content: str) -> List[Path]:
    try:
        module = ast.parse(content)
    except SyntaxError:
        return []

    references: List[Path] = []
    for node in ast.walk(module):
        if isinstance(node, ast.Import):
            for alias in node.names:
                resolved = resolve_python_module_actual(current_file, root_dir, alias.name, level=0)
                if resolved:
                    references.append(resolved)
        elif isinstance(node, ast.ImportFrom):
            module_name = node.module or ""
            if module_name:
                resolved = resolve_python_module_actual(current_file, root_dir, module_name, level=node.level)
                if resolved:
                    references.append(resolved)
            elif node.level > 0:
                for alias in node.names:
                    resolved = resolve_python_module_actual(current_file, root_dir, alias.name, level=node.level)
                    if resolved:
                        references.append(resolved)
    return references


def resolve_python_module_actual(current_file: Path, root_dir: Path, module_name: str, level: int = 0) -> Path | None:
    normalized_module = str(module_name or "").strip()
    candidates: List[Path] = []

    if level > 0:
        relative_parent = current_file.parent.resolve()
        for _ in range(max(level - 1, 0)):
            relative_parent = relative_parent.parent
        parts = normalized_module.split(".") if normalized_module else []
        base = relative_parent.joinpath(*parts) if parts else relative_parent
        candidates.extend(expand_python_actual_candidates(base))

    if normalized_module:
        parts = normalized_module.split(".")
        candidates.extend(expand_python_actual_candidates(root_dir.joinpath(*parts)))
        for ancestor in directories_within_root(current_file.parent.resolve(), root_dir):
            candidates.extend(expand_python_actual_candidates(ancestor.joinpath(*parts)))

    for candidate in candidates:
        if candidate.is_file() and is_within_root(candidate, root_dir):
            return candidate.resolve()
    return None


def directories_within_root(start_dir: Path, root_dir: Path) -> Iterable[Path]:
    current = start_dir.resolve()
    root = root_dir.resolve()
    while True:
        if is_within_root(current, root):
            yield current
        if current == root or current == current.parent:
            break
        current = current.parent


def expand_actual_candidates(base_path: Path) -> List[Path]:
    if base_path.suffix:
        return [base_path]

    candidates = [base_path]
    for extension in (".js", ".jsx", ".ts", ".tsx", ".css", ".json", ".html", ".py", ".md", ".txt", ".cpp", ".cc", ".cxx", ".h", ".hpp"):
        candidates.append(Path(f"{base_path}{extension}"))
    for index_name in ("index.js", "index.jsx", "index.ts", "index.tsx"):
        candidates.append(base_path / index_name)
    return candidates


def expand_python_actual_candidates(base_path: Path) -> List[Path]:
    return [
        Path(f"{base_path}.py"),
        base_path / "__init__.py",
    ]


def is_within_root(candidate: Path, root_dir: Path) -> bool:
    try:
        candidate.resolve().relative_to(root_dir.resolve())
        return True
    except ValueError:
        return False


def build_analysis_graph(target_path: Path, files: List[Path], analysis_id: str, mode: str) -> Dict[str, Any]:
    if not files:
        raise ValueError("No se encontraron archivos analizables para esta ruta.")

    root_dir = target_path.resolve() if target_path.is_dir() else infer_file_scope_root(target_path)
    virtual_by_actual = {
        file_path.resolve(): virtual_analysis_path(analysis_id, relative_analysis_path(file_path.resolve(), root_dir, mode))
        for file_path in files
    }
    actual_by_virtual = {virtual_path: actual_path for actual_path, virtual_path in virtual_by_actual.items()}

    imports_by_virtual: Dict[str, List[str]] = {}
    nodes: List[Dict[str, Any]] = []

    for actual_path, virtual_path in virtual_by_actual.items():
        content = actual_path.read_text(encoding="utf-8")
        relative_source = relative_analysis_path(actual_path, root_dir, mode)
        relative_source_normalized = normalize_posix_path(relative_source)
        statements = extract_real_statements(virtual_path, content)
        algorithm = build_real_algorithm(virtual_path, content, statements)
        imports = build_analysis_imports(actual_path, root_dir, virtual_by_actual, content)
        imports_by_virtual[virtual_path] = imports

        layer = infer_analysis_layer(relative_source_normalized)
        layer_label = layer_label_for_analysis(layer)
        nodes.append(
            {
                "id": node_id_for_path(virtual_path),
                "name": actual_path.name,
                "path": virtual_path,
                "sourcePath": str(actual_path),
                "layer": layer,
                "layerLabel": layer_label,
                "status": "generated",
                "size": format_size(actual_path.stat().st_size),
                "lines": count_lines(content),
                "description": describe_file(relative_source_normalized, statements),
                "imports": imports,
                "dependents": [],
                "color": default_color_for_analysis(layer),
                "code": content,
                "codeLanguage": detect_code_language(virtual_path),
                "algorithm": algorithm,
                "readOnly": True,
                "analysisId": analysis_id,
                "analysisLabel": target_path.name or str(target_path),
                "workspaceProject": analysis_id,
                "workspaceScene": analysis_id,
                "workspaceSceneLabel": f"Analisis · {target_path.name or analysis_id}",
            }
        )

    dependents_by_virtual = {node["path"]: [] for node in nodes}
    for source_virtual, import_virtuals in imports_by_virtual.items():
        for target_virtual in import_virtuals:
            dependents_by_virtual.setdefault(target_virtual, []).append(source_virtual)

    node_by_virtual = {node["path"]: node for node in nodes}
    for node in nodes:
        node["dependents"] = dependents_by_virtual.get(node["path"], [])

    edges = []
    seen_edges = set()
    for source_virtual, import_virtuals in imports_by_virtual.items():
        source_node = node_by_virtual.get(source_virtual)
        if not source_node:
            continue
        for target_virtual in import_virtuals:
            target_node = node_by_virtual.get(target_virtual)
            if not target_node:
                continue
            edge_key = (source_node["id"], target_node["id"])
            if edge_key in seen_edges or source_node["id"] == target_node["id"]:
                continue
            seen_edges.add(edge_key)
            edges.append(
                {
                    "id": f"edge-{source_node['id']}-{target_node['id']}",
                    "from": source_node["id"],
                    "to": target_node["id"],
                    "type": infer_edge_type(source_node, target_node),
                    "label": infer_edge_label(source_node, target_node),
                    "dashed": False,
                }
            )

    return {
        "metadata": {
            "projectName": f"Analisis · {target_path.name or analysis_id}",
            "sessionId": analysis_id,
            "source": "reverse_engineering",
            "mode": mode,
            "targetPath": str(target_path.resolve()),
            "generatedCount": len(nodes),
            "connectionCount": len(edges),
            "isolatedCount": len([node for node in nodes if not node["imports"] and not node["dependents"]]),
            "updatedAt": utc_now(),
            "note": "Escena generada por ingenieria inversa desde una ruta local cargada por el programador.",
        },
        "nodes": nodes,
        "edges": edges,
    }


def build_analysis_imports(
    actual_path: Path,
    root_dir: Path,
    virtual_by_actual: Dict[Path, str],
    content: str,
) -> List[str]:
    discovered_virtuals: List[str] = []
    suffix = actual_path.suffix.lower()

    if suffix in JS_SUFFIXES:
        for specifier in extract_js_imports(content):
            resolved = resolve_local_specifier_actual(actual_path, root_dir, specifier)
            if resolved and resolved in virtual_by_actual:
                discovered_virtuals.append(virtual_by_actual[resolved])
    if suffix == ".html":
        for specifier in extract_html_references(content):
            resolved = resolve_local_specifier_actual(actual_path, root_dir, specifier)
            if resolved and resolved in virtual_by_actual:
                discovered_virtuals.append(virtual_by_actual[resolved])
    if suffix in STYLE_SUFFIXES:
        for specifier in re.findall(r'@import\s+["\']([^"\']+)["\']', content):
            resolved = resolve_local_specifier_actual(actual_path, root_dir, specifier)
            if resolved and resolved in virtual_by_actual:
                discovered_virtuals.append(virtual_by_actual[resolved])
    if suffix == ".py":
        for resolved in resolve_local_python_dependencies(actual_path, root_dir, content):
            if resolved in virtual_by_actual:
                discovered_virtuals.append(virtual_by_actual[resolved])

    unique = []
    seen = set()
    for path in discovered_virtuals:
        if path in seen:
            continue
        seen.add(path)
        unique.append(path)
    return unique


def relative_analysis_path(actual_path: Path, root_dir: Path, mode: str) -> str:
    try:
        return to_posix(actual_path.resolve().relative_to(root_dir.resolve()))
    except ValueError:
        return to_posix(actual_path.name)


def virtual_analysis_path(analysis_id: str, relative_path: str) -> str:
    return normalize_posix_path(f"{ANALYSIS_PATH_PREFIX}/{slugify(analysis_id)}/{relative_path}")


def infer_analysis_layer(relative_path: str) -> str:
    normalized = normalize_posix_path(relative_path)
    suffix = PurePosixPath(normalized).suffix.lower()
    parts = PurePosixPath(normalized).parts

    if suffix == ".md" or "docs" in parts:
        return "docs"
    if suffix in STYLE_SUFFIXES:
        return "style"
    if "backend" in parts:
        if "data" in parts:
            return "data"
        return "backend"
    if "frontend" in parts:
        return "frontend"
    if "shared" in parts:
        return "shared"
    if "microservice" in normalized or "service" in parts:
        return "microservice"
    if PurePosixPath(normalized).name in {"package.json", "requirements.txt", "pyproject.toml", "tsconfig.json"}:
        return "config"
    return "script"


def layer_label_for_analysis(layer: str) -> str:
    return {
        "frontend": "Frontend",
        "backend": "Backend",
        "data": "Data",
        "microservice": "Microservice",
        "shared": "Shared",
        "docs": "Docs",
        "style": "Style",
        "config": "Config",
        "script": "Script",
    }.get(layer, layer.replace("-", " ").title())


def default_color_for_analysis(layer: str) -> str:
    from project_graph import default_color_for_layer

    return default_color_for_layer(layer)


def find_primary_node_id(graph: Dict[str, Any], target_path: Path) -> str:
    resolved_target = str(target_path.resolve())
    nodes = graph.get("nodes") if isinstance(graph, dict) else []
    if not isinstance(nodes, list):
        return ""

    for node in nodes:
        if str(node.get("sourcePath") or "") == resolved_target:
            return str(node.get("id") or "")

    return str(nodes[0].get("id") or "") if nodes else ""

from __future__ import annotations

from typing import Any, Callable, Dict, List

from flask import jsonify


def register_sandbox_routes(
    app: Any,
    *,
    resolve_editor_project: Callable[[str], tuple[str, Any] | None],
    refresh_sandbox_state: Callable[[str, Any], Dict[str, Any]],
    start_project_sandbox: Callable[[str, Any], Dict[str, Any]],
    terminate_sandbox_process: Callable[..., Dict[str, Any]],
    sandbox_log_tail: Callable[[Any, int], List[str]],
    socketio: Any,
) -> None:
    @app.get("/api/projects/<project_id>/sandbox")
    def get_project_sandbox(project_id: str):
        resolved = resolve_editor_project(project_id)
        if resolved is None:
            return jsonify({"ok": False, "error": "project_not_found"}), 404
        project_slug, project_dir = resolved
        state = refresh_sandbox_state(project_slug, project_dir)
        return jsonify({"ok": True, "projectId": project_slug, "sandbox": state, "logs": sandbox_log_tail(project_dir, 40)})

    @app.post("/api/projects/<project_id>/sandbox/start")
    def start_project_sandbox_endpoint(project_id: str):
        resolved = resolve_editor_project(project_id)
        if resolved is None:
            return jsonify({"ok": False, "error": "project_not_found"}), 404
        project_slug, project_dir = resolved
        try:
            state = start_project_sandbox(project_slug, project_dir)
        except RuntimeError as error:
            return jsonify({"ok": False, "error": str(error)}), 400
        except OSError as error:
            return jsonify({"ok": False, "error": "sandbox_start_failed", "message": str(error)}), 500

        socketio.emit(
            "agent:visual",
            {
                "op": "sandbox_started",
                "projectSlug": project_slug,
                "phase": "runtime-sandbox",
                "status": state.get("status"),
                "message": f"Sandbox runtime activo en {state.get('url')}",
                "url": state.get("url"),
                "pid": state.get("pid"),
                "port": state.get("port"),
            },
        )
        return jsonify({"ok": True, "projectId": project_slug, "sandbox": state, "logs": sandbox_log_tail(project_dir, 40)})

    @app.post("/api/projects/<project_id>/sandbox/stop")
    def stop_project_sandbox_endpoint(project_id: str):
        resolved = resolve_editor_project(project_id)
        if resolved is None:
            return jsonify({"ok": False, "error": "project_not_found"}), 404
        project_slug, project_dir = resolved
        state = terminate_sandbox_process(project_slug, project_dir, reason="human_stop")
        socketio.emit(
            "agent:visual",
            {
                "op": "sandbox_stopped",
                "projectSlug": project_slug,
                "phase": "runtime-sandbox",
                "status": state.get("status"),
                "message": "Sandbox runtime detenido.",
                "pid": state.get("pid"),
                "port": state.get("port"),
            },
        )
        return jsonify({"ok": True, "projectId": project_slug, "sandbox": state, "logs": sandbox_log_tail(project_dir, 40)})

from __future__ import annotations

import json
import os
import signal
import socket
import subprocess
import sys
import threading
import time
import urllib.error
import urllib.request
from pathlib import Path
from typing import Any, Callable, Dict, List

JsonLoader = Callable[[Path, Dict[str, Any]], Dict[str, Any]]
NowProvider = Callable[[], str]
PortAllocator = Callable[[str], int]


class SandboxService:
    def __init__(
        self,
        *,
        host: str,
        port_start: int,
        port_end: int,
        ready_timeout_seconds: float,
        ready_poll_seconds: float,
        state_name: str,
        log_name: str,
        load_json_file: JsonLoader,
        now_provider: NowProvider,
    ) -> None:
        self.host = host
        self.port_start = port_start
        self.port_end = port_end
        self.ready_timeout_seconds = ready_timeout_seconds
        self.ready_poll_seconds = ready_poll_seconds
        self.state_name = state_name
        self.log_name = log_name
        self.load_json_file = load_json_file
        self.now_provider = now_provider
        self.processes: Dict[str, subprocess.Popen[Any]] = {}
        self.lock = threading.Lock()

    def state_path(self, project_dir: Path) -> Path:
        return project_dir / "runtime" / self.state_name

    def log_path(self, project_dir: Path) -> Path:
        return project_dir / "runtime" / "logs" / self.log_name

    def read_state(self, project_dir: Path) -> Dict[str, Any]:
        state = self.load_json_file(self.state_path(project_dir), {})
        return state if isinstance(state, dict) else {}

    def write_state(self, project_dir: Path, state: Dict[str, Any]) -> None:
        path = self.state_path(project_dir)
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(json.dumps(state, ensure_ascii=True, indent=2) + "\n", encoding="utf-8")

    @staticmethod
    def pid_is_running(pid: Any) -> bool:
        try:
            normalized_pid = int(pid)
        except (TypeError, ValueError):
            return False
        if normalized_pid <= 0:
            return False
        try:
            os.kill(normalized_pid, 0)
            return True
        except ProcessLookupError:
            return False
        except PermissionError:
            return True
        except OSError:
            return False

    @staticmethod
    def port_is_available(port: int, host: str) -> bool:
        with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as probe:
            probe.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
            try:
                probe.bind((host, port))
            except OSError:
                return False
        return True

    def allocate_port(self, project_slug: str) -> int:
        span = max(1, self.port_end - self.port_start + 1)
        offset = sum(ord(char) for char in project_slug) % span
        for index in range(span):
            port = self.port_start + ((offset + index) % span)
            if self.port_is_available(port, self.host):
                return port
        raise RuntimeError("sandbox_port_unavailable")

    def detect_plan(self, project_dir: Path, port: int) -> Dict[str, Any] | None:
        for package_path in (project_dir / "package.json", project_dir / "frontend" / "package.json"):
            if not package_path.exists():
                continue
            package = self.load_json_file(package_path, {})
            scripts = package.get("scripts") if isinstance(package, dict) else {}
            scripts = scripts if isinstance(scripts, dict) else {}
            package_dir = package_path.parent
            if "dev" in scripts:
                script = str(scripts.get("dev") or "")
                command = ["npm", "run", "dev"]
                if "vite" in script:
                    command.extend(["--", "--host", self.host, "--port", str(port)])
                return {
                    "technology": "node",
                    "command": command,
                    "cwd": str(package_dir),
                    "entrypoint": f"{package_path.relative_to(project_dir).as_posix()}:scripts.dev",
                    "dependencyStatus": "uses_existing_project_dependencies",
                }
            if "start" in scripts:
                return {
                    "technology": "node",
                    "command": ["npm", "run", "start"],
                    "cwd": str(package_dir),
                    "entrypoint": f"{package_path.relative_to(project_dir).as_posix()}:scripts.start",
                    "dependencyStatus": "uses_existing_project_dependencies",
                }

        for relative in ("app.py", "server.py", "main.py", "backend/app.py", "backend/server.py", "src/app.py", "src/main.py"):
            candidate = project_dir / relative
            if not candidate.exists() or not candidate.is_file():
                continue
            try:
                content = candidate.read_text(encoding="utf-8", errors="ignore")
            except OSError:
                content = ""
            if "Flask" in content or "SocketIO" in content or "FastAPI" in content or "uvicorn" in content:
                return {
                    "technology": "python",
                    "command": [sys.executable or "python3", str(candidate)],
                    "cwd": str(candidate.parent),
                    "entrypoint": relative,
                    "dependencyStatus": "uses_current_python_environment",
                }

        static_root = None
        for relative in ("frontend/index.html", "index.html", "public/index.html", "src/index.html"):
            candidate = project_dir / relative
            if candidate.exists() and candidate.is_file():
                static_root = candidate.parent
                break
        if static_root is not None:
            return {
                "technology": "static",
                "command": [sys.executable or "python3", "-m", "http.server", str(port), "--bind", self.host],
                "cwd": str(static_root),
                "entrypoint": str(static_root.relative_to(project_dir)),
                "dependencyStatus": "standard_library",
            }
        return None

    def env(self, port: int) -> Dict[str, str]:
        env = os.environ.copy()
        env.update(
            {
                "HOST": self.host,
                "PORT": str(port),
                "FLASK_RUN_HOST": self.host,
                "FLASK_RUN_PORT": str(port),
                "PYTHONUNBUFFERED": "1",
            }
        )
        return env

    def preview_url(self, port: int) -> str:
        return f"http://{self.host}:{port}/"

    def wait_for_http_ready(
        self,
        url: str,
        process: subprocess.Popen[Any],
        *,
        timeout_seconds: float | None = None,
    ) -> Dict[str, Any]:
        deadline = time.time() + max(0.1, self.ready_timeout_seconds if timeout_seconds is None else timeout_seconds)
        last_error = ""
        while time.time() < deadline:
            returncode = process.poll()
            if returncode is not None:
                return {
                    "ready": False,
                    "reason": "process_exited_before_http_ready",
                    "returncode": returncode,
                    "lastError": last_error,
                }
            try:
                request_obj = urllib.request.Request(url, method="GET")
                with urllib.request.urlopen(request_obj, timeout=0.8) as response:
                    status_code = int(getattr(response, "status", 200) or 200)
                    return {
                        "ready": 200 <= status_code < 500,
                        "reason": "http_ready",
                        "statusCode": status_code,
                        "lastError": "",
                    }
            except urllib.error.HTTPError as error:
                status_code = int(getattr(error, "code", 0) or 0)
                if 200 <= status_code < 500:
                    return {
                        "ready": True,
                        "reason": "http_ready",
                        "statusCode": status_code,
                        "lastError": "",
                    }
                last_error = str(error)
            except (urllib.error.URLError, TimeoutError, OSError) as error:
                last_error = str(error)
            time.sleep(max(0.05, self.ready_poll_seconds))

        return {
            "ready": False,
            "reason": "http_ready_timeout",
            "returncode": process.poll(),
            "lastError": last_error,
        }

    @staticmethod
    def terminate_process_group(process: subprocess.Popen[Any], *, timeout_seconds: float = 2.0) -> None:
        try:
            os.killpg(int(process.pid), signal.SIGTERM)
        except (OSError, ProcessLookupError):
            try:
                os.kill(int(process.pid), signal.SIGTERM)
            except (OSError, ProcessLookupError):
                pass

        deadline = time.time() + timeout_seconds
        while time.time() < deadline and process.poll() is None:
            time.sleep(0.1)

        if process.poll() is None:
            try:
                os.killpg(int(process.pid), signal.SIGKILL)
            except (OSError, ProcessLookupError):
                try:
                    os.kill(int(process.pid), signal.SIGKILL)
                except (OSError, ProcessLookupError):
                    pass
            try:
                process.wait(timeout=1.0)
            except subprocess.TimeoutExpired:
                pass

    def refresh_state(self, project_slug: str, project_dir: Path) -> Dict[str, Any]:
        state = self.read_state(project_dir)
        pid = state.get("pid")
        running = self.pid_is_running(pid)
        if state and state.get("status") == "running" and not running:
            state["status"] = "stopped"
            state["ready"] = False
            state["stoppedAt"] = self.now_provider()
            state["updatedAt"] = state["stoppedAt"]
            self.write_state(project_dir, state)
        if not state:
            state = {
                "schema_version": 1,
                "projectId": project_slug,
                "status": "idle",
                "ready": False,
                "host": self.host,
                "port": None,
                "url": None,
                "embedUrl": None,
                "previewKind": None,
                "pid": None,
                "command": [],
                "technology": None,
                "logPath": str(self.log_path(project_dir)),
            }
        state["running"] = bool(state.get("status") == "running" and running)
        if state["running"]:
            state.setdefault("ready", True)
            state.setdefault("embedUrl", state.get("url"))
            state.setdefault("previewKind", "browser")
        else:
            state["ready"] = False
        return state

    def terminate_process(self, project_slug: str, project_dir: Path, reason: str = "human_stop") -> Dict[str, Any]:
        with self.lock:
            state = self.refresh_state(project_slug, project_dir)
            pid = state.get("pid")
            process = self.processes.pop(project_slug, None)
            if not self.pid_is_running(pid):
                state.update({"status": "stopped", "running": False, "ready": False, "stopReason": reason, "updatedAt": self.now_provider()})
                self.write_state(project_dir, state)
                return state

            try:
                os.killpg(int(pid), signal.SIGTERM)
            except (OSError, ProcessLookupError):
                try:
                    os.kill(int(pid), signal.SIGTERM)
                except (OSError, ProcessLookupError):
                    pass

            deadline = time.time() + 2.0
            while time.time() < deadline and self.pid_is_running(pid):
                time.sleep(0.1)
            if process is not None:
                try:
                    process.wait(timeout=0.2)
                except subprocess.TimeoutExpired:
                    pass

            if self.pid_is_running(pid):
                try:
                    os.killpg(int(pid), signal.SIGKILL)
                except (OSError, ProcessLookupError):
                    try:
                        os.kill(int(pid), signal.SIGKILL)
                    except (OSError, ProcessLookupError):
                        pass
                if process is not None:
                    try:
                        process.wait(timeout=1.0)
                    except subprocess.TimeoutExpired:
                        pass

            stopped_at = self.now_provider()
            state.update(
                {
                    "status": "stopped",
                    "running": False,
                    "ready": False,
                    "stopReason": reason,
                    "stoppedAt": stopped_at,
                    "updatedAt": stopped_at,
                }
            )
            self.write_state(project_dir, state)
            return state

    def start(
        self,
        project_slug: str,
        project_dir: Path,
        *,
        allocate_port: PortAllocator | None = None,
    ) -> Dict[str, Any]:
        with self.lock:
            existing = self.refresh_state(project_slug, project_dir)
            if existing.get("running"):
                return existing

            port = allocate_port(project_slug) if allocate_port is not None else self.allocate_port(project_slug)
            plan = self.detect_plan(project_dir, port)
            if plan is None:
                raise RuntimeError("sandbox_entrypoint_not_found")

            log_path = self.log_path(project_dir)
            log_path.parent.mkdir(parents=True, exist_ok=True)
            log_handle = log_path.open("a", encoding="utf-8")
            log_handle.write(f"\n[{self.now_provider()}] Starting sandbox: {' '.join(plan['command'])}\n")
            log_handle.flush()
            process = subprocess.Popen(
                plan["command"],
                cwd=plan["cwd"],
                env=self.env(port),
                stdout=log_handle,
                stderr=subprocess.STDOUT,
                text=True,
                start_new_session=True,
            )
            log_handle.close()
            self.processes[project_slug] = process
            preview_url = self.preview_url(port)
            healthcheck = self.wait_for_http_ready(preview_url, process)
            if not healthcheck.get("ready"):
                self.processes.pop(project_slug, None)
                self.terminate_process_group(process)
                failed_state = {
                    "schema_version": 1,
                    "projectId": project_slug,
                    "status": "failed",
                    "running": False,
                    "ready": False,
                    "host": self.host,
                    "port": port,
                    "url": preview_url,
                    "embedUrl": None,
                    "previewKind": "browser",
                    "pid": process.pid,
                    "command": plan["command"],
                    "cwd": plan["cwd"],
                    "technology": plan["technology"],
                    "entrypoint": plan["entrypoint"],
                    "dependencyStatus": plan["dependencyStatus"],
                    "logPath": str(log_path),
                    "startedAt": self.now_provider(),
                    "stoppedAt": self.now_provider(),
                    "updatedAt": self.now_provider(),
                    "healthcheck": healthcheck,
                    "network": {"bind": self.host, "internetExposed": False, "previewUrl": preview_url},
                }
                self.write_state(project_dir, failed_state)
                raise RuntimeError(f"sandbox_not_ready:{healthcheck.get('reason') or 'unknown'}")
            state = {
                "schema_version": 1,
                "projectId": project_slug,
                "status": "running",
                "running": True,
                "ready": True,
                "host": self.host,
                "port": port,
                "url": preview_url,
                "embedUrl": preview_url,
                "previewKind": "browser",
                "pid": process.pid,
                "command": plan["command"],
                "cwd": plan["cwd"],
                "technology": plan["technology"],
                "entrypoint": plan["entrypoint"],
                "dependencyStatus": plan["dependencyStatus"],
                "logPath": str(log_path),
                "startedAt": self.now_provider(),
                "updatedAt": self.now_provider(),
                "healthcheck": healthcheck,
                "network": {"bind": self.host, "internetExposed": False, "previewUrl": preview_url},
            }
            self.write_state(project_dir, state)
            return state

    def log_tail(self, project_dir: Path, limit: int = 80) -> List[str]:
        path = self.log_path(project_dir)
        if not path.exists():
            return []
        try:
            return path.read_text(encoding="utf-8", errors="replace").splitlines()[-limit:]
        except OSError:
            return []

