.gemini-section-divider {
  position: relative;
  z-index: 20;
  display: flex;
  align-items: center;
  min-height: 54px;
  margin: 24px 0 22px;
  pointer-events: auto;
}

.gemini-section-divider.is-open {
  z-index: 80;
}

.gemini-section-divider::before,
.gemini-section-divider::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  pointer-events: none;
}

.gemini-section-divider::before {
  top: 50%;
  height: 3px;
  transform: translateY(-50%);
  background: var(--gemini-divider);
  background-size: 220% 100%;
  opacity: var(--divider-glow-opacity);
  box-shadow:
    0 0 12px rgba(236, 72, 153, 0.42),
    0 0 24px rgba(59, 130, 246, 0.34);
  animation: gemini-divider-drift 8s linear infinite;
}

.gemini-section-divider::after {
  top: calc(50% - 9px);
  height: 18px;
  background: var(--gemini-divider);
  background-size: 220% 100%;
  filter: blur(18px);
  opacity: calc(var(--divider-glow-opacity) * 0.42);
  animation: gemini-divider-drift 8s linear infinite reverse;
}

