@keyframes gemini-divider-drift {
  from {
    background-position: 0% 50%;
  }

  to {
    background-position: 220% 50%;
  }
}

@keyframes habla-letter-shift {
  from {
    background-position: 0% 50%;
  }

  to {
    background-position: 260% 50%;
  }
}

@keyframes repair-spinner {
  to {
    transform: rotate(360deg);
  }
}


@keyframes code-agent-change-pulse {
  from {
    opacity: 0.62;
    transform: translateX(-4px);
  }

  to {
    opacity: 1;
    transform: translateX(0);
  }
}

@keyframes repair-message-pop {
  from {
    opacity: 0;
    transform: translateY(-4px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes agent-presence-orbit {
  to {
    transform: rotate(360deg);
  }
}

@keyframes agent-presence-cursor-route {
  0% {
    left: 18vw;
    top: 32vh;
    transform: rotate(-12deg) scale(0.96);
  }

  24% {
    left: 58vw;
    top: 34vh;
    transform: rotate(2deg) scale(1);
  }

  48% {
    left: 46vw;
    top: 70vh;
    transform: rotate(10deg) scale(1.02);
  }

  72% {
    left: 78vw;
    top: 54vh;
    transform: rotate(-4deg) scale(0.98);
  }

  100% {
    left: 18vw;
    top: 32vh;
    transform: rotate(-12deg) scale(0.96);
  }
}

@keyframes agent-scan-down {
  from {
    transform: translateY(-90%);
  }

  to {
    transform: translateY(760%);
  }
}

@keyframes agent-node-inspect {
  0%,
  100% {
    filter: drop-shadow(0 0 4px rgba(59, 130, 246, 0.16));
    transform: translate(0, 0);
  }

  50% {
    filter: drop-shadow(0 0 18px rgba(236, 72, 153, 0.38));
    transform: translate(4px, -3px);
  }
}

@keyframes agent-click-ping {
  0% {
    opacity: 0.95;
    transform: scale(0.58);
  }

  70% {
    opacity: 0.2;
    transform: scale(1.45);
  }

  100% {
    opacity: 0;
    transform: scale(1.9);
  }
}

@keyframes agent-micro-modal-pop {
  0% {
    opacity: 0;
    transform: translateY(10px) scale(0.96);
  }

  16%,
  78% {
    opacity: 1;
    transform: translateY(0) scale(1);
  }

  100% {
    opacity: 0;
    transform: translateY(-10px) scale(0.98);
  }
}

@media (prefers-reduced-motion: reduce) {
  .topbar::before,
  .topbar::after,
  .summary-card::after,
  .editor-toolbar-panel::after,
  .agent-panel::after,
  .observer-panel::after,
  .code-workbench-panel::after,
  .lint-panel::after,
  .reverse-panel::after,
  .map-panel::after,
  .algorithm-panel::after,
  .lanes-panel::after,
  .gemini-section-divider::before,
  .gemini-section-divider::after,
  .habla-title span,
  .code-workbench-repair-spinner,
  .code-workbench-repair-messages span,
  .agent-presence-orb,
  .agent-presence-cursor,
  .agent-presence-cursor span,
  .agent-presence-micro-modal,
  .app-shell.is-agent-presence-active .architecture-node,
  .app-shell.is-agent-presence-active .code-workbench-editor::before,
  .code-workbench-editor.is-writing::after,
  .code-workbench-editor.is-sweeping::after,
  .code-workbench-scanner-target,
  .code-workbench-broom-tool,
  .code-workbench-broom-track span,
  .code-workbench-dustpan::after,
  .app-shell.is-agent-presence-active .algorithm-board::after {
    animation: none;
  }
}

