  font-family: "IBM Plex Mono", "Cascadia Code", monospace;
}

.agent-console-message p {
  margin: 0;
  color: #dbeafe;
  font-size: 13px;
  line-height: 1.45;
}

.agent-console-message code {
  display: block;
  min-width: 0;
  overflow: hidden;
  padding: 7px 8px;
  border-radius: 8px;
  color: #a7f3d0;
  background: rgba(2, 6, 23, 0.64);
  font-family: "IBM Plex Mono", "Cascadia Code", monospace;
  font-size: 11px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.agent-console-empty,
.subagent-plan-empty {
  display: grid;
  gap: 5px;
  padding: 14px;
  border: 1px dashed rgba(148, 163, 184, 0.24);
  border-radius: 14px;
  color: #cbd5e1;
  background: rgba(15, 23, 42, 0.42);
}

.agent-console-empty span,
.subagent-plan-empty span {
  color: #94a3b8;
  font-size: 12px;
}

.agent-raw-terminal {
  border-top: 1px solid rgba(148, 163, 184, 0.14);
  padding-top: 10px;
}

.agent-raw-terminal summary {
  color: #93c5fd;
  cursor: pointer;
  font-size: 12px;
  font-weight: 900;
}

.agent-terminal.is-raw {
  min-height: 180px;
  max-height: 280px;
  margin-top: 10px;
  border-radius: 12px;
}

.subagent-orchestrator {
  display: grid;
  gap: 12px;
  padding: 14px;
  border: 1px solid rgba(96, 165, 250, 0.22);
  border-radius: 16px;
  background:
    linear-gradient(135deg, rgba(15, 23, 42, 0.76), rgba(2, 6, 23, 0.7)),
    rgba(2, 6, 23, 0.66);
}

.subagent-orchestrator.is-assigned {
  border-color: rgba(34, 197, 94, 0.38);
  box-shadow: inset 0 0 0 1px rgba(34, 197, 94, 0.12), 0 0 30px rgba(34, 197, 94, 0.1);
}

.subagent-plan-card {
  display: grid;
  gap: 10px;
}

.subagent-plan-summary {
  display: grid;
  gap: 4px;
}

.subagent-plan-summary strong {
  color: #e0f2fe;
}

.subagent-plan-summary span,
.subagent-plan-card small {
  color: #94a3b8;
  font-size: 12px;
}

.subagent-roster {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
  gap: 8px;
}

.subagent-chip {
  display: grid;
  gap: 4px;
  min-height: 118px;
  padding: 10px;
  border: 1px solid color-mix(in srgb, var(--agent-color, #38bdf8) 42%, transparent);
  border-radius: 12px;
  background: linear-gradient(180deg, color-mix(in srgb, var(--agent-color, #38bdf8) 16%, transparent), rgba(15, 23, 42, 0.72));
}

.subagent-chip b {
  width: fit-content;
  padding: 3px 6px;
  border-radius: 8px;
  color: #020617;
  background: var(--agent-color, #38bdf8);
  font-size: 11px;
}

.subagent-chip strong {
  color: #f8fafc;
}

.subagent-chip span {
  color: #cbd5e1;
  font-size: 12px;
  line-height: 1.35;
}

.agent-visual-note {
  padding: 12px 14px;
  border: 1px solid rgba(45, 212, 191, 0.2);
  border-radius: 14px;
  background: rgba(13, 148, 136, 0.12);
  color: #ccfbf1;
  font-size: 13px;
}

.agent-debug-list {
  display: grid;
  gap: 8px;
  max-height: 220px;
  overflow: auto;
  padding: 12px 14px;
  border: 1px solid rgba(148, 163, 184, 0.12);
  border-radius: 14px;
  background: rgba(2, 6, 23, 0.5);
}

.agent-debug-list code {
  color: #bfdbfe;
  font-family: "IBM Plex Mono", "Cascadia Code", monospace;
  font-size: 12px;
  white-space: pre-wrap;
  word-break: break-word;
}

.agent-cycle-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(170px, 1fr));
  gap: 10px;
}

.agent-cycle-card {
  display: grid;
  gap: 6px;
  min-height: 120px;
  padding: 12px;
  border: 1px solid rgba(148, 163, 184, 0.14);
  border-radius: 14px;
  background: rgba(2, 6, 23, 0.48);
  transition: border-color 180ms ease, background-color 180ms ease, box-shadow 180ms ease, transform 180ms ease;
}

.agent-cycle-card strong {
  color: #f8fafc;
}

.agent-cycle-card span,
.agent-cycle-card small,
.agent-cycle-card p {
  margin: 0;
  color: #94a3b8;
}

.agent-cycle-card.is-validated {
  border-color: rgba(163, 230, 53, 0.8);
  background: rgba(101, 163, 13, 0.24);
  box-shadow: 0 0 0 1px rgba(163, 230, 53, 0.18), 0 12px 28px rgba(101, 163, 13, 0.18);
}

.agent-cycle-card.is-completed,
.agent-cycle-card.is-ok {
  border-color: rgba(163, 230, 53, 0.5);
  background: rgba(101, 163, 13, 0.12);
}

.agent-cycle-card.is-improving,
.agent-cycle-card.is-analyzing,
.agent-cycle-card.is-pending {
  border-color: rgba(239, 68, 68, 0.46);
  background: rgba(127, 29, 29, 0.16);
}

.agent-cycle-card.is-failed {
  border-color: rgba(248, 113, 113, 0.8);
  background: rgba(127, 29, 29, 0.28);
  box-shadow: 0 0 0 1px rgba(248, 113, 113, 0.18), 0 12px 28px rgba(127, 29, 29, 0.24);
}

.agent-cycle-card.is-current {
  border-color: rgba(248, 113, 113, 0.92);
  background: rgba(153, 27, 27, 0.34);
  box-shadow: 0 0 0 1px rgba(248, 113, 113, 0.2), 0 0 30px rgba(239, 68, 68, 0.24);
  animation: lace-cycle-live-pulse 1s ease-in-out infinite;
}

@keyframes lace-cycle-live-pulse {
  0%,
  100% {
    transform: translateY(0);
    box-shadow: 0 0 0 1px rgba(248, 113, 113, 0.18), 0 0 12px rgba(239, 68, 68, 0.14);
  }
  50% {
    transform: translateY(-1px);
    box-shadow: 0 0 0 1px rgba(248, 113, 113, 0.4), 0 0 34px rgba(239, 68, 68, 0.42);
  }
}

.agent-error {
  margin: 0;
  color: #fca5a5;
}

.agent-burst-stack {
  position: fixed;
  right: 22px;
  bottom: 22px;
  z-index: 95;
  display: grid;
  gap: 10px;
  width: min(380px, calc(100vw - 32px));
  pointer-events: none;
}

.agent-burst {
  display: grid;
  gap: 5px;
  padding: 12px 14px;
  border: 1px solid rgba(56, 189, 248, 0.34);
  border-left-width: 4px;
  border-radius: 10px;
  background: rgba(8, 15, 27, 0.96);
  color: #dbeafe;
  box-shadow: 0 18px 50px rgba(0, 0, 0, 0.38);
  animation: agent-burst-enter 180ms ease-out both, agent-burst-exit 220ms ease-in 4.78s forwards;
}

.agent-burst strong,
.agent-burst p {
  min-width: 0;
  margin: 0;
  overflow: hidden;
  text-overflow: ellipsis;
}

.agent-burst strong {
  color: #ffffff;
  font-size: 12px;
}

.agent-burst p {
  color: #bfdbfe;
  font-size: 13px;
  line-height: 1.35;
}

.agent-burst.is-initial {
  border-color: rgba(248, 113, 113, 0.5);
}

.agent-burst.is-middle {
  border-color: rgba(56, 189, 248, 0.58);
}

.agent-burst.is-final {
  border-color: rgba(190, 242, 100, 0.62);
}

.agent-burst.is-danger {
  border-color: rgba(239, 68, 68, 0.7);
}

@keyframes agent-burst-enter {
  from {
    opacity: 0;
    transform: translateY(12px) scale(0.98);
  }
  to {
    opacity: 1;
    transform: translateY(0) scale(1);
  }
}

@keyframes agent-burst-exit {
  to {
    opacity: 0;
    transform: translateY(8px) scale(0.98);
  }
}

.reviewer-overlay {
  position: fixed;
  inset: 0;
  z-index: 80;
  display: grid;
  place-items: end center;
  padding: 24px;
  pointer-events: none;
}

.reviewer-backdrop {
  position: absolute;
  inset: 0;
  background: rgba(2, 6, 23, 0.46);
  pointer-events: auto;
}

.reviewer-panel {
  position: relative;
  z-index: 1;
  width: min(1120px, calc(100vw - 32px));
  max-height: min(820px, calc(100vh - 42px));
  overflow: hidden;
  display: grid;
  grid-template-rows: auto auto auto auto minmax(180px, 1fr);
  border: 1px solid rgba(45, 212, 191, 0.28);
  border-radius: 18px;
  background: rgba(8, 15, 27, 0.96);
  box-shadow: 0 28px 90px rgba(0, 0, 0, 0.48);
  pointer-events: auto;
}

.reviewer-overlay.is-expanded {
  place-items: center;
}

.reviewer-overlay.is-expanded .reviewer-panel {
  width: min(1440px, calc(100vw - 24px));
  max-height: calc(100vh - 24px);
}

.reviewer-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
  padding: 16px 18px;
  border-bottom: 1px solid rgba(148, 163, 184, 0.14);
}

.reviewer-header h2 {
  margin-bottom: 6px;
  color: #f8fafc;
}

.reviewer-header p {
  margin: 0;
  color: #94a3b8;
  font-size: 13px;
}

.reviewer-actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 8px;
}

.reviewer-summary-grid {
  display: grid;
  grid-template-columns: repeat(6, minmax(120px, 1fr));
  gap: 10px;
  padding: 14px 16px;
  border-bottom: 1px solid rgba(148, 163, 184, 0.1);
}

.reviewer-summary-grid > div {
  min-width: 0;
  display: grid;
  gap: 4px;
  padding: 10px 12px;
  border: 1px solid rgba(148, 163, 184, 0.13);
  border-radius: 12px;
  background: rgba(2, 6, 23, 0.44);
}

.reviewer-summary-grid span,
.reviewer-summary-grid small {
  color: #94a3b8;
  font-size: 12px;
}

.reviewer-summary-grid strong {
  color: #f8fafc;
  font-size: 13px;
  overflow-wrap: anywhere;
}

.reviewer-evidence-grid {
  display: grid;
  grid-template-columns: 1fr 1fr minmax(190px, 0.7fr);
  gap: 12px;
  padding: 14px 16px;
  border-bottom: 1px solid rgba(148, 163, 184, 0.1);
