.reviewer-evidence-grid section {
  min-width: 0;
  padding: 12px;
  border: 1px solid rgba(148, 163, 184, 0.12);
  border-radius: 12px;
  background: rgba(2, 6, 23, 0.38);
}

.reviewer-evidence-grid h3 {
  margin: 0 0 8px;
  color: #bfdbfe;
  font-size: 13px;
  letter-spacing: 0;
}

.reviewer-evidence-grid ul {
  margin: 0;
  padding-left: 18px;
  color: #d1fae5;
  font-size: 12px;
}

.reviewer-evidence-grid p {
  margin: 0;
  color: #94a3b8;
  font-size: 12px;
  overflow-wrap: anywhere;
}

.reviewer-warning-strip {
  display: grid;
  gap: 8px;
  padding: 12px 16px;
  border-bottom: 1px solid rgba(251, 191, 36, 0.16);
  background: rgba(120, 53, 15, 0.18);
}

.reviewer-warning-strip p {
  margin: 0;
  color: #fde68a;
  font-size: 13px;
}

.reviewer-timeline {
  display: grid;
  align-content: start;
  gap: 10px;
  min-height: 0;
  overflow: auto;
  padding: 14px 16px 18px;
}

.reviewer-event {
  display: grid;
  gap: 6px;
  padding: 12px;
  border: 1px solid rgba(148, 163, 184, 0.14);
  border-radius: 12px;
  background: rgba(2, 6, 23, 0.48);
}

.reviewer-event > div {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
}

.reviewer-event strong {
  color: #f8fafc;
  font-size: 12px;
}

.reviewer-event span,
.reviewer-event small {
  color: #94a3b8;
  font-size: 11px;
}

.reviewer-event p {
  margin: 0;
  color: #cbd5e1;
  font-size: 13px;
  line-height: 1.45;
}

.reviewer-event.is-success {
  border-color: rgba(34, 197, 94, 0.36);
  background: rgba(20, 83, 45, 0.18);
}

.reviewer-event.is-warning {
  border-color: rgba(251, 191, 36, 0.42);
  background: rgba(120, 53, 15, 0.2);
}

.reviewer-event.is-error {
  border-color: rgba(248, 113, 113, 0.48);
  background: rgba(127, 29, 29, 0.22);
}

.reviewer-minibar {
  position: fixed;
  right: 18px;
  bottom: 18px;
  z-index: 82;
  width: min(520px, calc(100vw - 36px));
  display: grid;
  gap: 4px;
  padding: 12px 14px;
  border: 1px solid rgba(45, 212, 191, 0.32);
  border-radius: 14px;
  background: rgba(8, 15, 27, 0.96);
  box-shadow: 0 18px 60px rgba(0, 0, 0, 0.42);
  color: #cbd5e1;
  text-align: left;
  cursor: pointer;
}

.reviewer-minibar strong {
  color: #f8fafc;
}

.reviewer-minibar span {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: #94a3b8;
  font-size: 12px;
}

.workspace-grid {
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1fr) 420px;
  gap: 16px;
  margin-top: 16px;
}

.workspace-grid::before {
  content: "";
  position: absolute;
  top: 4px;
  bottom: 4px;
  left: calc(100% - 420px - 9px);
  width: 2px;
  pointer-events: none;
  border-radius: 999px;
  background: linear-gradient(
    180deg,
    transparent 0%,
    rgba(239, 68, 68, 0.9) 12%,
    rgba(236, 72, 153, 0.94) 36%,
    rgba(168, 85, 247, 0.94) 62%,
    rgba(59, 130, 246, 0.9) 88%,
    transparent 100%
  );
  box-shadow:
    0 0 10px rgba(236, 72, 153, 0.34),
    0 0 18px rgba(59, 130, 246, 0.26);
  opacity: var(--divider-glow-opacity);
}

.map-panel,
.inspector,
.algorithm-panel,
.lanes-panel {
  overflow: hidden;
}

.map-panel {
  background:
    linear-gradient(180deg, rgba(7, 10, 17, 0.98), rgba(5, 9, 18, 0.98)),
    rgba(15, 23, 42, 0.74);
}

.legend {
  display: flex;
  align-items: center;
  gap: 14px;
  color: #cbd5e1;
  font-size: 13px;
  white-space: nowrap;
}

.legend-line {
  display: inline-block;
  width: 28px;
  height: 2px;
  margin-right: 6px;
  vertical-align: middle;
}

.legend-line.socket {
  background: #38bdf8;
}

.legend-line.uses {
  background: #4ade80;
}

.legend-line.reference {
  background: #c084fc;
}

.architecture-stage {
  padding: 12px 16px 16px;
}

.architecture-hint {
  margin-bottom: 10px;
  color: #93c5fd;
  font-size: 13px;
}

.architecture-canvas {
  position: relative;
  overflow: hidden;
  width: 100%;
  height: 760px;
  border-radius: 18px;
  background:
    radial-gradient(circle at top center, rgba(168, 85, 247, 0.08), transparent 32rem),
    #050913;
  cursor: grab;
  user-select: none;
  touch-action: none;
}

.architecture-canvas:active {
  cursor: grabbing;
}

.architecture-svg {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  pointer-events: none;
  transform-origin: 50% 50%;
  transition: transform 1200ms cubic-bezier(0.2, 0.8, 0.2, 1);
}

.app-shell.is-agent-presence-active .architecture-svg {
  transform: translate(var(--agent-map-pan-x), var(--agent-map-pan-y)) scale(var(--agent-map-scale));
}

.architecture-svg g,
.architecture-svg rect,
.architecture-svg path,
.architecture-svg text {
  pointer-events: auto;
}

.architecture-layer-label {
  fill: #c4b5fd;
  font-size: 24px;
  font-weight: 700;
  letter-spacing: 0.12em;
}

.architecture-scene-label {
  fill: #f8fafc;
  font-size: 18px;
  font-weight: 700;
  letter-spacing: 0.08em;
}

.architecture-edge-label {
  fill: #a8b4ca;
  font-size: 14px;
}

.architecture-badge {
  fill: #e0f2fe;
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.08em;
}

.architecture-node-title {
  fill: #f8fafc;
  font-size: 16px;
  font-weight: 700;
}

.architecture-node.is-analyzing rect:first-child,
.architecture-node.is-improving rect:first-child,
.architecture-node.is-pending rect:first-child {
  animation: architecture-cycle-live-pulse 1s ease-in-out infinite;
}

.architecture-node.is-validated rect:first-child,
.architecture-node.is-completed rect:first-child {
  filter: drop-shadow(0 0 12px rgba(163, 230, 53, 0.28));
}

.architecture-node.is-failed rect:first-child {
  filter: drop-shadow(0 0 12px rgba(239, 68, 68, 0.3));
}

.app-shell.is-agent-presence-active .map-panel,
.app-shell.is-agent-presence-active .algorithm-panel,
.app-shell.is-agent-presence-active .code-workbench-panel {
  border-color: rgba(96, 165, 250, 0.34);
  box-shadow:
    0 24px 80px rgba(0, 0, 0, 0.34),
    0 0 36px rgba(59, 130, 246, 0.14);
}

.app-shell.is-agent-presence-active .architecture-canvas::after {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background:
    linear-gradient(115deg, transparent 0%, rgba(56, 189, 248, 0.07) 44%, rgba(236, 72, 153, 0.12) 50%, transparent 58%);
  animation: agent-scan-down 5.2s ease-in-out infinite;
}

.app-shell.is-agent-presence-active .architecture-node rect:first-child {
  animation: agent-node-inspect 2.6s ease-in-out infinite;
}

.app-shell.is-agent-presence-active .architecture-node:nth-of-type(2n) rect:first-child {
  animation-delay: -0.8s;
}

.app-shell.is-agent-presence-active .architecture-node:nth-of-type(3n) rect:first-child {
  animation-delay: -1.45s;
}

@keyframes architecture-cycle-live-pulse {
  0%,
  100% {
    filter: drop-shadow(0 0 4px rgba(239, 68, 68, 0.16));
  }
  50% {
    filter: drop-shadow(0 0 18px rgba(239, 68, 68, 0.42));
  }
}

.architecture-node-path {
  fill: #93a3bc;
  font-size: 12px;
}

.architecture-node-status {
  font-size: 13px;
  font-weight: 700;
}

.architecture-node-meta {
  fill: #7f8aa1;
  font-size: 12px;
}

