.algorithm-meta strong {
  color: #f8fafc;
}

.algorithm-meta span {
  color: #93c5fd;
  font-size: 13px;
}

.algorithm-toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 14px;
  color: #94a3b8;
  font-size: 13px;
}

.algorithm-reset {
  border: 1px solid rgba(96, 165, 250, 0.35);
  border-radius: 999px;
  padding: 8px 12px;
  background: rgba(30, 41, 59, 0.74);
  color: #dbeafe;
  cursor: pointer;
}

.algorithm-board {
  position: relative;
  overflow: hidden;
  height: 680px;
  border-radius: 16px;
  background: #ffffff;
  box-shadow: inset 0 0 0 1px rgba(15, 23, 42, 0.08);
  cursor: grab;
  touch-action: none;
  user-select: none;
}

.algorithm-board:active {
