}

.app-shell.is-agent-presence-active .algorithm-board::after {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  top: 0;
  z-index: 2;
  height: 92px;
  pointer-events: none;
  background:
    linear-gradient(180deg, transparent, rgba(59, 130, 246, 0.14), rgba(236, 72, 153, 0.1), transparent);
  mix-blend-mode: multiply;
  animation: agent-scan-down 4.6s ease-in-out infinite;
