}

.algorithm-flow {
  position: absolute;
  inset: 0 auto auto 0;
  display: block;
  width: auto;
  height: auto;
  pointer-events: none;
  transform-origin: 50% 50%;
  transition: transform 1200ms cubic-bezier(0.2, 0.8, 0.2, 1);
}

.app-shell.is-agent-presence-active .algorithm-flow {
  transform: translate(var(--agent-flow-pan-x), var(--agent-flow-pan-y)) scale(var(--agent-flow-scale));
}

.algorithm-flow g,
.algorithm-flow path,
.algorithm-flow rect,
.algorithm-flow polygon,
.algorithm-flow text {
  pointer-events: auto;
}

.algorithm-sandbox-panel {
  display: grid;
  gap: 10px;
  margin: 0 16px 16px;
  padding: 12px;
  border: 1px solid rgba(96, 165, 250, 0.28);
  border-radius: 8px;
  background: rgba(2, 6, 23, 0.58);
}

