.agent-chat-header,
.agent-chat-context {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  min-width: 0;
}

.agent-chat-header div {
  display: grid;
  gap: 2px;
  min-width: 0;
}

.agent-chat-header strong {
  color: #dcfce7;
  font-size: 12px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.agent-chat-pilot-label {
  min-width: 0;
