  font-weight: 900;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.agent-chat-virtual-cursor {
  position: absolute;
  z-index: 12;
  left: 42%;
  top: 52%;
  width: 24px;
  height: 28px;
  pointer-events: none;
  filter: drop-shadow(0 0 10px rgba(74, 222, 128, 0.72));
  opacity: 0;
  transform: translate(-50%, -50%);
  transition: left 420ms ease, top 420ms ease, opacity 180ms ease, transform 180ms ease;
}

.agent-chat-virtual-cursor::before {
  content: "";
  position: absolute;
  left: 4px;
  top: 1px;
  width: 15px;
  height: 23px;
  clip-path: polygon(0 0, 0 100%, 39% 72%, 66% 100%, 100% 84%, 72% 58%, 100% 58%);
  background: #dcfce7;
}

.agent-chat-virtual-cursor span {
  position: absolute;
  left: -7px;
  top: -7px;
  width: 34px;
  height: 34px;
  border: 1px solid rgba(74, 222, 128, 0.5);
  border-radius: 999px;
  animation: agent-chat-cursor-ping 1.15s ease-out infinite;
}

.code-workbench-agent-chat.is-agent-piloted .agent-chat-virtual-cursor {
  opacity: 1;
}

.code-workbench-agent-chat.is-phase-cursor .agent-chat-virtual-cursor {
  left: 54%;
  top: 72%;
}

.code-workbench-agent-chat.is-phase-focus .agent-chat-virtual-cursor,
.code-workbench-agent-chat.is-phase-type .agent-chat-virtual-cursor {
  left: 78%;
  top: 84%;
}

.code-workbench-agent-chat.is-phase-submit .agent-chat-virtual-cursor {
  left: calc(100% - 52px);
  top: calc(100% - 32px);
  transform: translate(-50%, -50%) scale(0.92);
}


.agent-chat-header small,
.agent-chat-context span {
