.code-workbench-broom-head {
  position: absolute;
  left: 18px;
  bottom: 12px;
  width: 54px;
  height: 14px;
  border-radius: 3px;
  background: linear-gradient(90deg, #fef3c7, #facc15, #d97706);
  box-shadow: 0 0 18px rgba(250, 204, 21, 0.24);
  transform: rotate(-9deg);
}

.code-workbench-broom-bristles {
  position: absolute;
  left: 13px;
  bottom: 0;
  width: 64px;
  height: 18px;
  border-radius: 0 0 12px 12px;
  background: repeating-linear-gradient(90deg, rgba(251, 191, 36, 0.95) 0 5px, rgba(180, 83, 9, 0.88) 5px 8px);
  transform: skewX(-10deg) rotate(-9deg);
}

.code-workbench-dustpan {
  position: absolute;
  right: 34px;
  bottom: 54px;
  width: 96px;
  height: 42px;
}

.code-workbench-dustpan::before {
  content: "";
  position: absolute;
  left: 8px;
  right: 4px;
  bottom: 0;
  height: 24px;
  border: 1px solid rgba(125, 211, 252, 0.42);
  border-top: 0;
  border-radius: 2px 2px 10px 10px;
  background: linear-gradient(180deg, rgba(14, 116, 144, 0.82), rgba(15, 23, 42, 0.96));
  box-shadow: inset 0 8px 16px rgba(125, 211, 252, 0.12), 0 0 22px rgba(14, 165, 233, 0.24);
}

.code-workbench-dustpan::after {
  content: "";
  position: absolute;
  left: 0;
  bottom: 23px;
  width: 92px;
  height: 4px;
  border-radius: 999px;
  background: #bae6fd;
  box-shadow: 0 0 12px rgba(125, 211, 252, 0.42);
  animation: code-dustpan-collect 1.2s ease-in-out infinite;
}

.code-workbench-dustpan span {
  position: absolute;
  right: 4px;
  bottom: 22px;
  width: 5px;
  height: 34px;
  border-radius: 999px;
  background: #bae6fd;
  transform: rotate(24deg);
  transform-origin: bottom;
}

.code-workbench-broom-banner {
  position: absolute;
  right: 16px;
  top: 16px;
  width: min(430px, calc(100% - 96px));
  display: grid;
  gap: 5px;
  padding: 10px 12px;
  border: 1px solid rgba(250, 204, 21, 0.42);
  border-radius: 4px;
  background: rgba(30, 41, 59, 0.95);
  color: #fef3c7;
  font-size: 12px;
  box-shadow: 0 14px 42px rgba(0, 0, 0, 0.4);
}

.code-workbench-broom-banner strong {
  color: #ffffff;
}

.code-workbench-broom-banner span,
.code-workbench-broom-banner small {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.code-workbench-broom-banner small {
  color: #bae6fd;
}

.code-workbench-scanner-overlay {
  position: absolute;
  inset: 0;
  z-index: 6;
  pointer-events: none;
}

.code-workbench-scanner-beam {
  position: absolute;
  left: 64px;
  right: 0;
  top: calc(14px + var(--scanner-y, 0px));
  height: 22px;
  background: linear-gradient(90deg, rgba(34, 197, 94, 0.04), rgba(34, 197, 94, 0.18), rgba(56, 189, 248, 0.16), transparent);
  border-top: 1px solid rgba(34, 197, 94, 0.34);
  border-bottom: 1px solid rgba(56, 189, 248, 0.24);
  box-shadow: 0 0 20px rgba(34, 197, 94, 0.18);
}

.code-workbench-scanner-lens {
  position: absolute;
  left: calc(64px + 16px + var(--scanner-x, 0px));
  top: calc(7px + var(--scanner-y, 0px));
  width: 48px;
  height: 48px;
  border: 2px solid rgba(187, 247, 208, 0.95);
  border-radius: 50%;
  background: radial-gradient(circle at 42% 38%, rgba(240, 253, 244, 0.22), rgba(34, 197, 94, 0.08) 48%, rgba(15, 23, 42, 0.12) 68%);
  box-shadow: 0 0 0 1px rgba(34, 197, 94, 0.18), 0 0 28px rgba(34, 197, 94, 0.48);
  transform: translate(-50%, -25%);
}

.code-workbench-scanner-lens::after {
  content: "";
  position: absolute;
  right: -16px;
  bottom: -11px;
  width: 22px;
  height: 5px;
  border-radius: 999px;
  background: rgba(187, 247, 208, 0.95);
  transform: rotate(45deg);
  box-shadow: 0 0 12px rgba(34, 197, 94, 0.52);
}

.code-workbench-scanner-lens span {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 18px;
  height: 18px;
  transform: translate(-50%, -50%);
}

.code-workbench-scanner-target {
  position: absolute;
  left: calc(64px + 16px + var(--scanner-x, 0px));
  top: calc(14px + var(--scanner-y, 0px));
  width: 18px;
  height: 18px;
  transform: translate(-50%, 0);
}

.code-workbench-scanner-lens span::before,
.code-workbench-scanner-lens span::after,
.code-workbench-scanner-target::before,
.code-workbench-scanner-target::after {
  content: "";
  position: absolute;
  background: rgba(103, 232, 249, 0.92);
  box-shadow: 0 0 10px rgba(103, 232, 249, 0.72);
}

.code-workbench-scanner-lens span::before,
.code-workbench-scanner-target::before {
  left: 8px;
  top: -4px;
  width: 2px;
  height: 26px;
}

.code-workbench-scanner-lens span::after,
.code-workbench-scanner-target::after {
  left: -4px;
  top: 8px;
  width: 26px;
  height: 2px;
}

.code-workbench-scanner-target {
  border: 1px solid rgba(103, 232, 249, 0.82);
  border-radius: 3px;
  animation: code-scanner-target-pulse 0.36s ease-in-out infinite alternate;
}

.code-workbench-scanning-toast {
  position: absolute;
  top: 94px;
  left: 50%;
  z-index: 42;
  display: grid;
  grid-template-columns: auto auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 8px;
  width: min(520px, calc(100% - 32px));
  padding: 9px 12px;
  border: 1px solid rgba(34, 197, 94, 0.46);
  border-radius: 6px;
  background: rgba(5, 46, 22, 0.96);
  color: #dcfce7;
  box-shadow: 0 18px 42px rgba(0, 0, 0, 0.42);
  transform: translateX(-50%);
  pointer-events: auto;
}

.code-workbench-scanning-toast span {
  width: 10px;
  height: 10px;
  border-radius: 999px;
  background: #22c55e;
  box-shadow: 0 0 0 0 rgba(34, 197, 94, 0.58);
  animation: scanner-toast-pulse 1s ease-in-out infinite;
}

.code-workbench-scanning-toast strong {
  color: #ffffff;
  font-size: 12px;
  white-space: nowrap;
}

.code-workbench-scanning-toast small {
  min-width: 0;
  overflow: hidden;
  color: #bbf7d0;
  font-size: 12px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.code-workbench-scanning-toast button {
  min-height: 26px;
  padding: 0 9px;
  border: 1px solid rgba(187, 247, 208, 0.34);
  border-radius: 4px;
  color: #dcfce7;
  background: rgba(20, 83, 45, 0.92);
  font: inherit;
  font-size: 12px;
  cursor: pointer;
}

.code-workbench-scanning-toast button:hover {
  color: #ffffff;
  border-color: rgba(220, 252, 231, 0.62);
}

.code-workbench-scanner-banner {
  position: absolute;
  right: 16px;
  top: 16px;
  width: min(420px, calc(100% - 96px));
  display: grid;
  gap: 5px;
  padding: 10px 12px;
  border: 1px solid rgba(34, 197, 94, 0.42);
  border-radius: 4px;
  background: rgba(5, 46, 22, 0.94);
  color: #dcfce7;
  font-size: 12px;
  box-shadow: 0 14px 42px rgba(0, 0, 0, 0.4);
}

.code-workbench-scanner-banner strong {
  color: #ffffff;
}

.code-workbench-scanner-banner span,
.code-workbench-scanner-banner small {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.code-workbench-scanner-banner i {
  display: block;
  height: 4px;
  overflow: hidden;
  border-radius: 999px;
  background: rgba(15, 23, 42, 0.68);
}

.code-workbench-scanner-banner b {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, #22c55e, #67e8f9);
  box-shadow: 0 0 12px rgba(103, 232, 249, 0.48);
}

.code-workbench-readonly-banner {
  position: absolute;
  right: 16px;
  bottom: 16px;
  max-width: min(520px, calc(100% - 96px));
  padding: 10px 12px;
  border: 1px solid rgba(234, 179, 8, 0.34);
  border-radius: 4px;
  background: rgba(24, 24, 24, 0.94);
  color: #fde68a;
  font-size: 12px;
  box-shadow: 0 12px 40px rgba(0, 0, 0, 0.36);
}

.code-workbench-writer-banner {
  position: absolute;
  right: 16px;
  top: 16px;
  max-width: min(560px, calc(100% - 96px));
  display: grid;
  gap: 4px;
  padding: 10px 12px;
  border: 1px solid rgba(56, 189, 248, 0.42);
  border-radius: 4px;
  background: rgba(8, 47, 73, 0.94);
  color: #d7f9ff;
  font-size: 12px;
  box-shadow: 0 14px 42px rgba(0, 0, 0, 0.4);
}

.code-workbench-writer-banner strong {
  color: #ffffff;
}

.code-workbench-writer-banner span {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}


@keyframes code-broom-sweep {
  0% {
    transform: translateX(0) rotate(-4deg);
  }
  42% {
    transform: translateX(calc(100vw - 250px)) rotate(8deg);
  }
  58% {
    transform: translateX(calc(100vw - 250px)) rotate(-5deg);
  }
  100% {
    transform: translateX(0) rotate(-4deg);
  }
}

@keyframes code-broom-dust {
  0%, 100% {
    opacity: 0.18;
    transform: translateY(0) scale(0.72);
  }
  45% {
    opacity: 0.78;
    transform: translateY(-8px) scale(1.08);
  }
}

@keyframes code-dustpan-collect {
  0%, 100% {
    transform: translateX(0);
    opacity: 0.74;
  }
  50% {
    transform: translateX(-8px);
    opacity: 1;
  }
}

@keyframes code-writer-scan {
  0% {
    transform: translateX(-100%);
  }
  100% {
    transform: translateX(100%);
  }
}

@keyframes code-scanner-target-pulse {
  from {
    opacity: 0.72;
    transform: translate(-50%, 0) scale(0.94);
  }
  to {
    opacity: 1;
    transform: translate(-50%, 0) scale(1.08);
  }
}

@keyframes integrity-finding-pulse {
  from {
    opacity: 0.58;
    transform: translateY(0) scaleY(0.94);
  }
  to {
    opacity: 1;
    transform: translateY(0) scaleY(1.06);
  }
}

@keyframes zombie-release-pulse {
  0%, 100% {
    filter: brightness(1);
  }
  50% {
    filter: brightness(1.22);
  }
}

@keyframes agent-chat-cursor-ping {
  0% {
    opacity: 0.92;
    transform: scale(0.55);
  }
  70% {
    opacity: 0.18;
    transform: scale(1.45);
  }
  100% {
    opacity: 0;
    transform: scale(1.85);
  }
}

@keyframes scanner-toast-pulse {
  0% {
    box-shadow: 0 0 0 0 rgba(34, 197, 94, 0.58);
  }
  70% {
    box-shadow: 0 0 0 9px rgba(34, 197, 94, 0);
  }
  100% {
    box-shadow: 0 0 0 0 rgba(34, 197, 94, 0);
  }
}

.code-workbench-editor-resizer {
  position: relative;
  display: grid;
  place-items: center;
  min-height: 12px;
  border-top: 1px solid #2d2d30;
  border-bottom: 1px solid #2d2d30;
  background: #202020;
  cursor: row-resize;
  touch-action: none;
}

.code-workbench-editor-resizer::before {
  content: "";
  position: absolute;
  inset: -8px 0;
}

.code-workbench-editor-resizer span {
  width: min(220px, 42%);
  height: 4px;
  border-radius: 999px;
  background: linear-gradient(90deg, rgba(96, 165, 250, 0.28), rgba(148, 163, 184, 0.9), rgba(96, 165, 250, 0.28));
  box-shadow: 0 0 16px rgba(96, 165, 250, 0.16);
  pointer-events: none;
}

.code-workbench-editor-resizer:hover,
.code-workbench-editor-resizer:focus-visible {
  background: #252526;
  outline: none;
}

.code-workbench-editor-resizer:hover span,
.code-workbench-editor-resizer:focus-visible span {
  background: linear-gradient(90deg, rgba(56, 189, 248, 0.4), rgba(191, 219, 254, 1), rgba(56, 189, 248, 0.4));
  box-shadow: 0 0 18px rgba(56, 189, 248, 0.32);
}

.code-workbench-actions {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
  min-height: 58px;
  overflow: visible;
  padding: 8px 12px;
  border-top: 1px solid #2d2d30;
  background: #252526;
}

.code-workbench-state {
  display: inline-flex;
  align-items: center;
  min-height: 32px;
  padding: 0 10px;
  border-radius: 4px;
  font-size: 12px;
  font-weight: 700;
}

.code-workbench-state.locked {
  background: rgba(202, 138, 4, 0.18);
  color: #fde68a;
}

.code-workbench-state.open {
  background: rgba(22, 163, 74, 0.18);
  color: #bbf7d0;
}

.code-workbench-truth-state {
  display: inline-flex;
  align-items: center;
  min-height: 32px;
  padding: 0 10px;
  border: 1px solid rgba(148, 163, 184, 0.24);
  border-radius: 4px;
  background: rgba(30, 30, 30, 0.72);
  color: #cbd5e1;
  font-size: 12px;
  font-weight: 800;
}

.code-workbench-truth-state.is-zombie {
  border-color: rgba(248, 113, 113, 0.58);
  background: rgba(127, 29, 29, 0.34);
  color: #fecaca;
}

.code-workbench-truth-state.is-live {
  border-color: rgba(34, 197, 94, 0.42);
  background: rgba(20, 83, 45, 0.3);
  color: #bbf7d0;
}

.code-workbench-truth-state.is-idle {
  border-color: rgba(56, 189, 248, 0.34);
  background: rgba(8, 47, 73, 0.28);
  color: #bae6fd;
}

.code-workbench-zombie-release {
  min-height: 34px;
  border-color: rgba(248, 113, 113, 0.82) !important;
  background: #991b1b !important;
  color: #ffffff !important;
  box-shadow: 0 0 0 1px rgba(248, 113, 113, 0.32), 0 0 18px rgba(248, 113, 113, 0.28);
}

.code-workbench-zombie-release:not(:disabled) {
  animation: zombie-release-pulse 1.4s ease-in-out infinite;
}

.code-workbench-error {
  color: #fecaca;
  font-size: 12px;
}

.code-workbench-repair-status {
  color: #bbf7d0;
  font-size: 12px;
}

.code-workbench-repair-bubble {
  position: absolute;
  top: 20px;
  right: 24px;
  z-index: 5;
  display: grid;
  gap: 10px;
  width: min(460px, calc(100% - 96px));
  padding: 14px;
  border: 1px solid rgba(248, 113, 113, 0.46);
  border-radius: 8px;
  background: #181818;
  color: #d4d4d4;
  box-shadow: 0 20px 70px rgba(0, 0, 0, 0.48);
}

.code-workbench-repair-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.code-workbench-repair-header strong {
  color: #ffffff;
}

.code-workbench-repair-header button {
  min-height: 28px;
  padding: 0 8px;
  border-radius: 4px;
  background: #2d2d30;
  color: #d4d4d4;
  cursor: pointer;
}

.code-workbench-repair-bubble code {
  display: block;
  padding: 8px;
  border-radius: 4px;
  background: rgba(127, 29, 29, 0.28);
  color: #fecaca;
  font-family: "IBM Plex Mono", "Cascadia Code", monospace;
  font-size: 12px;
  word-break: break-word;
}

.code-workbench-repair-bubble p,
.code-workbench-repair-bubble small {
  margin: 0;
  color: #cccccc;
}

.code-workbench-repair-bubble label {
  display: grid;
  gap: 6px;
  color: #9cdcfe;
  font-size: 12px;
}

.code-workbench-repair-bubble textarea {
  width: 100%;
  resize: vertical;
  min-height: 86px;
  border: 1px solid #3c3c3c;
  border-radius: 4px;
  background: #1e1e1e;
  color: #d4d4d4;
  padding: 10px;
  font-family: "IBM Plex Mono", "Cascadia Code", monospace;
  font-size: 12px;
  line-height: 1.45;
}

.code-workbench-repair-progress {
  display: grid;
  gap: 8px;
  padding: 10px;
  border: 1px solid rgba(56, 189, 248, 0.34);
  border-radius: 8px;
  background:
    radial-gradient(circle at 12% 22%, rgba(236, 72, 153, 0.16), transparent 34px),
    rgba(8, 47, 73, 0.28);
}

.code-workbench-repair-progress.is-complete {
  border-color: rgba(163, 230, 53, 0.36);
  background:
    radial-gradient(circle at 12% 22%, rgba(163, 230, 53, 0.14), transparent 34px),
    rgba(20, 83, 45, 0.2);
}

.code-workbench-repair-progress-row {
  display: grid;
  grid-template-columns: 34px minmax(0, 1fr) auto;
  gap: 10px;
  align-items: center;
}

.code-workbench-repair-spinner {
  width: 28px;
  height: 28px;
  border: 2px solid rgba(148, 163, 184, 0.26);
  border-top-color: #38bdf8;
  border-right-color: #ec4899;
  border-radius: 50%;
  box-shadow:
    0 0 18px rgba(56, 189, 248, 0.28),
    inset 0 0 12px rgba(236, 72, 153, 0.16);
  animation: repair-spinner 0.9s linear infinite;
}

.code-workbench-repair-progress-row div {
  display: grid;
  gap: 2px;
  min-width: 0;
}

.code-workbench-repair-progress-row small {
  color: #93c5fd;
  font-size: 11px;
  letter-spacing: 0.02em;
  text-transform: lowercase;
}

.code-workbench-repair-progress-row strong {
  min-width: 0;
  overflow: hidden;
  color: #f8fafc;
  font-family: "IBM Plex Mono", "Cascadia Code", monospace;
  font-size: 12px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.code-workbench-repair-progress-row b {
  color: #e0f2fe;
  font-family: "IBM Plex Mono", "Cascadia Code", monospace;
  font-size: 13px;
}

.code-workbench-repair-progress-track {
  height: 7px;
  overflow: hidden;
  border-radius: 999px;
  background: rgba(45, 45, 48, 0.92);
}

.code-workbench-repair-progress-track span {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, #ef4444, #ec4899, #a855f7, #3b82f6, #a3e635);
  box-shadow: 0 0 18px rgba(59, 130, 246, 0.38);
  transition: width 280ms ease;
}

.code-workbench-repair-progress em {
  color: #cbd5e1;
  font-size: 11px;
  font-style: normal;
}

.code-workbench-repair-messages {
  display: grid;
  gap: 5px;
}

.code-workbench-repair-messages span {
  min-width: 0;
  overflow: hidden;
  padding: 5px 7px;
  border-left: 2px solid rgba(56, 189, 248, 0.58);
  border-radius: 4px;
  background: rgba(15, 23, 42, 0.55);
  color: #cbd5e1;
  font-size: 11px;
  text-overflow: ellipsis;
  white-space: nowrap;
  animation: repair-message-pop 240ms ease both;
}

.code-workbench-repair-actions {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
}

.code-workbench-terminal {
  min-height: 0;
  overflow: hidden;
  border-top: 1px solid #2d2d30;
  background: #181818;
}

.code-workbench-terminal > div {
  display: flex;
  gap: 18px;
  min-height: 34px;
  padding: 0 12px;
  align-items: center;
  border-bottom: 1px solid #2d2d30;
  color: #858585;
  font-size: 12px;
}

.code-workbench-terminal > div button {
  background: transparent;
  color: #858585;
  cursor: pointer;
}

.code-workbench-terminal > div button.active {
  color: #ffffff;
}

.code-workbench-terminal pre {
  height: 135px;
  max-height: 135px;
  margin: 0;
  overflow: auto;
  padding: 12px;
  color: #d4d4d4;
  font-family: "IBM Plex Mono", "Cascadia Code", monospace;
  font-size: 12px;
  line-height: 1.45;
}

@media (max-width: 1280px) {
  .runtime-dashboard-zone {
    grid-template-columns: minmax(248px, min(34vw, var(--runtime-dashboard-width, 318px))) 8px minmax(0, 1fr);
  }

  .workspace-grid,
  .agent-grid,
  .observer-grid {
    grid-template-columns: 1fr;
  }

  .workspace-grid::before {
    display: none;
  }

  .code-workbench-shell {
    grid-template-columns: 48px minmax(260px, var(--workbench-sidebar-width, 320px)) 8px minmax(0, 1fr);
  }

  .reviewer-summary-grid,
  .reviewer-evidence-grid {
    grid-template-columns: 1fr 1fr;
  }

  .editor-toolbar-grid {
    grid-template-columns: 1fr;
  }

  .email-config-grid {
    grid-template-columns: 1fr;
  }

  .observer-timeline {
    grid-template-columns: 1fr 1fr;
  }
}

@media (max-width: 860px) {
  .runtime-dashboard-zone {
    display: grid;
    grid-template-columns: 1fr;
    gap: 14px;
  }

  .runtime-dashboard-sidebar {
    position: relative;
    top: auto;
    max-height: 720px;
  }

  .runtime-dashboard-resizer {
    display: none;
  }

  .app-shell {
    padding: 14px;
  }

  .topbar {
    flex-direction: column;
    align-items: flex-start;
