.cyberlace-panel {
  margin: 10px auto 12px;
  width: min(1420px, calc(100% - 32px));
  border: 1px solid rgba(120, 120, 120, 0.24);
  border-radius: 8px;
  padding: 12px;
  background: rgba(12, 16, 18, 0.82);
}

.cyberlace-panel.is-collapsed {
  padding: 10px 12px;
}

.cyberlace-panel.is-collapsed .panel-header.compact {
  margin-bottom: 0;
}

.cyberlace-panel.is-collapsed .panel-header p {
  margin-bottom: 0;
}

.cyberlace-panel.is-off {
  border-color: rgba(148, 163, 184, 0.28);
}

.cyberlace-panel.is-monitor {
  border-color: rgba(45, 212, 191, 0.36);
}

.cyberlace-panel.is-enforce {
  border-color: rgba(248, 113, 113, 0.48);
}

.cyberlace-grid {
  display: grid;
  grid-template-columns: minmax(260px, 0.7fr) minmax(320px, 1.3fr);
  gap: 12px;
}

.cyberlace-summary,
.cyberlace-stream {
  border: 1px solid rgba(148, 163, 184, 0.18);
  border-radius: 8px;
  padding: 12px;
  background: rgba(2, 6, 8, 0.42);
  min-width: 0;
}

.cyberlace-summary strong,
.cyberlace-stream strong {
  display: block;
  margin-bottom: 6px;
  color: #d8f5ef;
}

.cyberlace-summary p,
.cyberlace-event span,
.cyberlace-event small,
.cyberlace-error {
  overflow-wrap: anywhere;
}

.cyberlace-metrics {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 8px;
  margin-top: 10px;
}

.cyberlace-metrics span {
  border: 1px solid rgba(148, 163, 184, 0.16);
  border-radius: 6px;
  padding: 8px;
  background: rgba(15, 23, 42, 0.4);
}

.cyberlace-metrics small {
  display: block;
  color: #9aa6b2;
  font-size: 0.75rem;
}

.cyberlace-events {
  display: grid;
  gap: 8px;
  max-height: 220px;
  overflow: auto;
  padding-right: 4px;
}

.cyberlace-event {
  border-left: 3px solid rgba(45, 212, 191, 0.55);
  padding: 8px 10px;
  background: rgba(15, 23, 42, 0.34);
  border-radius: 6px;
}

.cyberlace-event small {
  display: block;
  color: #9aa6b2;
  margin-bottom: 4px;
}

.cyberlace-error {
  display: block;
  margin-top: 8px;
  color: #fecaca;
}

@media (max-width: 860px) {
  .cyberlace-grid {
    grid-template-columns: 1fr;
  }

  .cyberlace-panel {
    width: min(100% - 20px, 1420px);
  }
}


