/* Operational mouse: active only when App passes autonomousMode=true. */
.operational-mouse-layer {
  position: fixed;
  inset: 0;
  z-index: 132;
  pointer-events: none;
  color: #edf7f2;
  font-family: inherit;
  isolation: isolate;
}

.operational-mouse-cursor {
  position: fixed;
  left: 0;
  top: 0;
  display: flex;
  align-items: center;
  gap: 6px;
  pointer-events: none;
  transition: transform 560ms cubic-bezier(0.19, 1, 0.22, 1), opacity 180ms ease;
  opacity: 0.88;
  z-index: 138;
}

.operational-mouse-cursor.is-active {
  opacity: 1;
}

.operational-mouse-pointer {
  width: 0;
  height: 0;
  border-left: 13px solid #f8fff9;
  border-top: 9px solid transparent;
  border-bottom: 9px solid transparent;
  filter: drop-shadow(0 2px 4px rgba(0, 0, 0, 0.55));
  transform: rotate(18deg);
}

.operational-mouse-label {
  max-width: 150px;
  border: 1px solid rgba(136, 255, 190, 0.34);
  background: rgba(11, 20, 18, 0.9);
  border-radius: 6px;
  padding: 3px 7px;
  font-size: 11px;
  line-height: 1.1;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

