  color: rgba(235, 255, 244, 0.94);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0;
  text-transform: uppercase;
  writing-mode: vertical-rl;
  transform: rotate(180deg);
  box-shadow: -10px 14px 28px rgba(0, 0, 0, 0.24);
}

.operational-mouse-layer.is-clear:not(.has-modal):not(.is-auto-visible) .operational-tool-dock {
  transform: translateX(calc(100% - 46px));
