export default function CodeWorkbenchIntegrityAlert({
  findings,
  actionStatus,
  busy,
  selectedProject,
  onFocusFirst,
  onFrozenSniper,
  onAcceptBaseline,
}) {
  if (findings.length) {
    return (
      <div className="code-workbench-integrity-alert" role="status" aria-live="polite">
        <div>
          <strong>Observer detecto cambios externos no registrados</strong>
