import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { io } from "socket.io-client";

const UI_REFRESH_SUPPRESS_AUTH_KEY = "hablaUiRefreshSuppressAuthGate";
const UI_REFRESH_LAST_KEY = "hablaRuntimeUiRefreshLast";
const LACE_GATE_AUTO_PREFIX = "hablaLaceGateAutoQueuedAt:";
const UI_REFRESH_COOLDOWN_MS = 120000;
const LACE_GATE_AUTO_COOLDOWN_MS = 1800000;

const GATE_LABELS = {
  mouse: "Mouse",
  scanner: "Scanner",
  integrity: "Integrity",
  sandbox: "Sandbox",
  cyberlace: "CyberLACE",
  lace: "LACE",
  broom: "Escoba",
  typewriter: "Typewriter",
};

function nowLabel() {
  return new Date().toISOString();
}

function sessionGet(key) {
  try {
    return window.sessionStorage.getItem(key) || "";
  } catch {
    return "";
  }
}

function sessionSet(key, value) {
  try {
    window.sessionStorage.setItem(key, String(value));
  } catch {
    // Session storage can be unavailable; the UI refresh still falls back to a normal reload.
  }
}

function compact(value, fallback = "sin evidencia") {
  const text = String(value || "").trim();
  return text || fallback;
}

function gateFromEvent(event, source) {
  const op = String(event?.op || "").toLowerCase();
  const phase = String(event?.phase || "").toLowerCase();
  const action = String(event?.action || "").toLowerCase();
  const tool = String(event?.targetTool || "").toLowerCase().replace(/-/g, "_");
  const joined = `${op} ${phase} ${action} ${tool}`;
  if (source === "mouse" || joined.includes("operational_mouse") || joined.includes("ui:mouse")) return tool || "mouse";
  if (joined.includes("code_scanner") || joined.includes("scanner")) return "scanner";
  if (joined.includes("integrity") || joined.includes("findings")) return "integrity";
  if (joined.includes("sandbox")) return "sandbox";
  if (joined.includes("cyberlace") || joined.includes("quarantine")) return "cyberlace";
  if (joined.includes("lace")) return "lace";
  if (joined.includes("broom") || joined.includes("escoba")) return "broom";
  if (joined.includes("typewriter")) return "typewriter";
  return "mouse";
}

function statusFromEvent(event, source) {
  if (source === "mouse") return "queued";
  const status = String(event?.status || event?.state || "").toLowerCase();
  if (status) return status;
  const op = String(event?.op || "").toLowerCase();
  if (op.includes("complete") || op.includes("completed")) return "passed";
  if (op.includes("blocked") || op.includes("failed")) return "blocked";
  return "observing";
}

function normalizeEvent(event, source) {
  const gate = gateFromEvent(event, source);
  const status = statusFromEvent(event, source);
  return {
    id: `${source}-${event?.actionId || event?.timestamp || Date.now()}-${Math.random().toString(16).slice(2)}`,
    source,
    gate,
    status,
    projectSlug: compact(event?.projectSlug || event?.projectId, "sin proyecto"),
    message: compact(event?.message || event?.reason || event?.op || event?.action, "evento runtime"),
    evidence: compact(event?.expectedEvidence || event?.relativePath || event?.reportPath || event?.artifactPath || event?.focusPath, "sin evidencia"),
    timestamp: compact(event?.timestamp || event?.updatedAt || event?.createdAt || nowLabel(), "sin timestamp"),
  };
}

export default function ForensicTruthRail({ socketUrl = "", autonomousMode = false, selectedProject = "" }) {
  const apiBase = String(socketUrl || "").replace(/\/$/, "");
  const [events, setEvents] = useState([]);
  const [gates, setGates] = useState({});
  const [laceDependencyStatus, setLaceDependencyStatus] = useState(null);
  const [laceGateActionStatus, setLaceGateActionStatus] = useState("");
  const [autoRevealActive, setAutoRevealActive] = useState(false);
  const refreshScheduledRef = useRef(false);
  const revealTimerRef = useRef(null);

  const revealRailTemporarily = useCallback(() => {
    setAutoRevealActive(true);
    if (revealTimerRef.current) window.clearTimeout(revealTimerRef.current);
    revealTimerRef.current = window.setTimeout(() => {
      setAutoRevealActive(false);
      revealTimerRef.current = null;
    }, 6500);
  }, []);

  useEffect(() => () => {
    if (revealTimerRef.current) window.clearTimeout(revealTimerRef.current);
  }, []);

  const scheduleRuntimeUiRefresh = useCallback((event) => {
    if (!autonomousMode || refreshScheduledRef.current) return;
    const status = String(event?.status || "").toLowerCase();
    if (!['blocked', 'failed'].includes(status)) return;
    if (event?.source === 'mouse') return;
    const now = Date.now();
    const lastRefreshAt = Number(sessionGet(UI_REFRESH_LAST_KEY) || 0);
    if (Number.isFinite(lastRefreshAt) && now - lastRefreshAt < UI_REFRESH_COOLDOWN_MS) return;
    refreshScheduledRef.current = true;
    sessionSet(UI_REFRESH_LAST_KEY, String(now));
    sessionSet(UI_REFRESH_SUPPRESS_AUTH_KEY, String(now));
    sessionSet('hablaRuntimeUiRefreshReason', `${event.gate || 'runtime'}:${event.message || status}`.slice(0, 240));
    window.setTimeout(() => {
      window.location.reload();
    }, 1100);
  }, [autonomousMode]);

  const queueLaceGateAction = useCallback(async (reason = "LACE closure bloqueado; abrir gate visual para diagnostico.") => {
    const project = String(selectedProject || "").trim();
    if (!autonomousMode || !project) return null;
    revealRailTemporarily();
    setLaceGateActionStatus("encolando");
    try {
      const response = await fetch(`${apiBase}/api/ui-actions/enqueue`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          targetTool: "lace_gate",
          projectSlug: project,
          source: "forensic_truth_rail",
          reason,
          expectedEvidence: "runtime/task_queue.json + docs/lace_cycles",
          autoRun: true,
          expiresSeconds: 120,
        }),
      });
      const payload = await response.json().catch(() => ({}));
      setLaceGateActionStatus(payload?.ok === false || !response.ok ? "bloqueado" : "solicitado");
      return payload;
    } catch {
      setLaceGateActionStatus("fallo");
      return null;
    }
  }, [apiBase, autonomousMode, revealRailTemporarily, selectedProject]);

  useEffect(() => {
    if (!autonomousMode) return undefined;
    const socket = io(apiBase || undefined, { transports: ["polling"], upgrade: false });
    function push(source) {
      return (payload) => {
        if (!payload || typeof payload !== "object") return;
        const item = normalizeEvent(payload, source);
        setEvents((current) => [item, ...current].slice(0, 32));
        setGates((current) => ({
          ...current,
          [item.gate]: item,
        }));
        revealRailTemporarily();
        scheduleRuntimeUiRefresh(item);
      };
    }
    socket.on("agent:visual", push("visual"));
    socket.on("agent:observer", push("observer"));
    socket.on("ui:mouse-action", push("mouse"));
    return () => socket.disconnect();
  }, [apiBase, autonomousMode, revealRailTemporarily, scheduleRuntimeUiRefresh]);

  useEffect(() => {
    const project = String(selectedProject || "").trim();
    if (!autonomousMode || !project) {
      setLaceDependencyStatus(null);
      return undefined;
    }
    let cancelled = false;
    async function loadLaceStatus() {
      try {
        const response = await fetch(`${apiBase}/api/projects/${encodeURIComponent(project)}/lace-dependency-status`);
        const payload = await response.json();
        if (!cancelled) setLaceDependencyStatus(payload?.ok === false ? null : payload);
      } catch {
        if (!cancelled) setLaceDependencyStatus(null);
      }
    }
    void loadLaceStatus();
    const timer = window.setInterval(loadLaceStatus, 10000);
    return () => {
      cancelled = true;
      window.clearInterval(timer);
    };
  }, [apiBase, autonomousMode, selectedProject]);

  useEffect(() => {
    const project = String(selectedProject || "").trim();
    if (!autonomousMode || !project || !laceDependencyStatus?.lace?.closureBlocked) return;
    const lace = laceDependencyStatus.lace || {};
    const signature = [
      project,
      lace.requiredCycles || 0,
      lace.validCycleEvidenceCount || 0,
      lace.missingCycles || 0,
      ...(laceDependencyStatus.dependencyFindings || []).map((finding) => `${finding.taskId}:${(finding.missingDependencies || []).join("+")}`),
    ].join("|");
    const key = `${LACE_GATE_AUTO_PREFIX}${project}`;
    const previous = sessionGet(key);
    if (previous === signature) {
      setLaceGateActionStatus("ya diagnosticado");
      return;
    }
    const now = Date.now();
    const lastQueuedAt = Number(sessionGet(`${key}:at`) || 0);
    if (Number.isFinite(lastQueuedAt) && now - lastQueuedAt < LACE_GATE_AUTO_COOLDOWN_MS) return;
    sessionSet(key, signature);
    sessionSet(`${key}:at`, String(now));
    void queueLaceGateAction("Linea de Verdad detecto LACE closure bloqueado; abrir diagnostico visual no destructivo.");
  }, [autonomousMode, laceDependencyStatus, queueLaceGateAction, selectedProject]);

  const gateRows = useMemo(() => {
    const keys = ["mouse", "scanner", "integrity", "sandbox", "cyberlace", "lace", "broom", "typewriter"];
    return keys.map((key) => {
      if (key === "lace" && laceDependencyStatus?.lace) {
        return {
          gate: "lace",
          status: laceDependencyStatus.lace.closureStatus || "observing",
          message: `Ciclos ${laceDependencyStatus.lace.validCycleEvidenceCount || 0}/${laceDependencyStatus.lace.requiredCycles || 0}`,
          evidence: (laceDependencyStatus.ghostDependencies || []).length
            ? `deps fantasma: ${laceDependencyStatus.ghostDependencies.join(", ")}`
            : `faltan ${laceDependencyStatus.lace.missingCycles || 0} ciclo(s)`,
        };
      }
      return gates[key] || { gate: key, status: "sin evidencia", message: "pendiente", evidence: "sin evidencia" };
    });
  }, [gates, laceDependencyStatus]);

  const railAutoVisible = Boolean(
    autoRevealActive
    || ["encolando"].includes(String(laceGateActionStatus || "").toLowerCase())
  );
  const railClassName = [
    "forensic-truth-rail",
    railAutoVisible ? "is-auto-visible" : "is-idle",
  ].join(" ");

  if (!autonomousMode) return null;

  return (
    <aside className={railClassName} aria-label="Linea de verdad forense">
      <span className="forensic-truth-rail__tab" aria-hidden="true">Verdad</span>
      <header className="forensic-truth-rail__header">
        <strong>Linea de Verdad</strong>
        <span>evidencia viva</span>
      </header>
      <div className="forensic-gate-grid">
        {gateRows.map((gate) => (
          <article key={gate.gate} className={`forensic-gate-card is-${String(gate.status || "").replace(/[^a-z0-9_-]/gi, "-").toLowerCase()}`}>
            <strong>{GATE_LABELS[gate.gate] || gate.gate}</strong>
            <span>{gate.status}</span>
            <small>{gate.evidence}</small>
          </article>
        ))}
      </div>
      {laceDependencyStatus?.lace?.closureBlocked ? (
        <section className="forensic-lace-alert">
          <strong>LACE closure gate bloqueado</strong>
          <p>Faltan {laceDependencyStatus.lace.missingCycles || 0} ciclo(s); validos {laceDependencyStatus.lace.validCycleEvidenceCount || 0}/{laceDependencyStatus.lace.requiredCycles || 0}.</p>
          {laceDependencyStatus.dependencyFindings?.slice(0, 4).map((finding) => (
            <p key={finding.taskId}>
              {finding.taskId}: falta {finding.missingDependencies.join(", ")}
            </p>
          ))}
          <button type="button" data-truth-action="open-lace-gate" onClick={() => queueLaceGateAction("Humano solicito abrir LACE Gate desde Linea de Verdad.")}>
            Abrir LACE Gate
          </button>
          {laceGateActionStatus ? <small>mouse action: {laceGateActionStatus}</small> : null}
        </section>
      ) : null}
      <section className="forensic-event-stream">
        {events.length ? events.map((event) => (
          <article key={event.id} className="forensic-event-row">
            <header>
              <strong>{GATE_LABELS[event.gate] || event.gate}</strong>
              <span>{event.source} · {event.status}</span>
            </header>
            <p>{event.message}</p>
            <small>{event.projectSlug} · {event.evidence}</small>
          </article>
        )) : <p className="forensic-empty">Sin eventos nuevos. Esperando evidencia real del runtime.</p>}
      </section>
    </aside>
  );
}

import { useEffect, useMemo, useState } from "react";

const SCENARIO_LABELS = {
  "obfuscated-secret": "Secretos ofuscados",
  "external-login": "Login externo",
  "prompt-injection-readme": "Prompt injection README",
  "payment-data": "Banco + CVV + PIN",
  "multi-provider-token": "Tokens multi-proveedor",
};

const INTENSITY_LABELS = {
  baseline: "Baseline",
  hard: "Hard",
  extreme: "Extreme",
};

function compactId(value) {
  return String(value || "")
    .trim()
    .replace(/[^A-Za-z0-9_.-]+/g, "-")
    .replace(/^-+|-+$/g, "")
    .slice(0, 90);
}

function statusText(result) {
  if (!result) return "Sin corrida";
  if (result.passed === true) return "PASSED";
  if (result.passed === false) return "FAILED";
  return "RUNNING";
}

function resultClass(result) {
  if (!result) return "is-idle";
  if (result.passed === true) return "is-passed";
  if (result.passed === false) return "is-failed";
  return "is-running";
}

function shortValue(value, fallback = "-") {
  if (value === null || value === undefined || value === "") return fallback;
  return String(value);
}

function setHarnessTrainingAutomation(active, detail = {}) {
  window.dispatchEvent(new CustomEvent("habla:harness-training-automation", {
    detail: {
      active: Boolean(active),
      autoAcceptSafeAlternative: Boolean(active),
      ...detail,
    },
  }));
}

export default function HarnessEngineeringStudio({ socketUrl = "", onClose }) {
  const [scenario, setScenario] = useState("obfuscated-secret");
  const [caseId, setCaseId] = useState("");
  const [campaignId, setCampaignId] = useState("");
  const [cycles, setCycles] = useState(50);
  const [taskDelaySeconds, setTaskDelaySeconds] = useState(8);
  const continuous = false;
  const [autopilotRunId, setAutopilotRunId] = useState("");
  const [intensity, setIntensity] = useState("hard");
  const [objective, setObjective] = useState("Entrenamiento autonomo de seguridad operacional para agentes IA.");
  const [summary, setSummary] = useState({ scenarios: [], intensities: [], cases: [], reports: [], checkpoints: [], campaigns: [], memory: null });
  const [loadingSummary, setLoadingSummary] = useState(false);
  const [running, setRunning] = useState(false);
  const [autopilotRunning, setAutopilotRunning] = useState(false);
  const [result, setResult] = useState(null);
  const [autopilotResult, setAutopilotResult] = useState(null);
  const [status, setStatus] = useState("");
  const [artifact, setArtifact] = useState(null);
  const [artifactLoading, setArtifactLoading] = useState(false);
  const [learningStatus, setLearningStatus] = useState(null);
  const [learningActionStatus, setLearningActionStatus] = useState("");

  const scenarios = useMemo(() => {
    const values = Array.isArray(summary.scenarios) && summary.scenarios.length ? summary.scenarios : Object.keys(SCENARIO_LABELS);
    return values.filter(Boolean);
  }, [summary.scenarios]);

  const intensities = useMemo(() => {
    const values = Array.isArray(summary.intensities) && summary.intensities.length ? summary.intensities : Object.keys(INTENSITY_LABELS);
    return values.filter(Boolean);
  }, [summary.intensities]);

  async function loadSummary() {
    setLoadingSummary(true);
    try {
      const response = await fetch(`${socketUrl}/api/harness/training/summary`);
      const payload = await response.json();
      if (!response.ok || payload?.ok === false) {
        throw new Error(payload?.message || payload?.error || "training_summary_failed");
      }
      setSummary({
        scenarios: Array.isArray(payload.scenarios) ? payload.scenarios : [],
        intensities: Array.isArray(payload.intensities) ? payload.intensities : [],
        cases: Array.isArray(payload.cases) ? payload.cases : [],
        reports: Array.isArray(payload.reports) ? payload.reports : [],
        checkpoints: Array.isArray(payload.checkpoints) ? payload.checkpoints : [],
        campaigns: Array.isArray(payload.campaigns) ? payload.campaigns : [],
        memory: payload.memory || null,
        safetyLearning: payload.safetyLearning || null,
      });
      setLearningStatus(payload.safetyLearning || null);
    } catch (error) {
      setStatus(error?.message || "No se pudo cargar Harness Engineering Studio.");
    } finally {
      setLoadingSummary(false);
    }
  }

  useEffect(() => {
    loadSummary();
  }, []);

  async function runScenario(event) {
    event.preventDefault();
    const normalizedCaseId = compactId(caseId);
    setRunning(true);
    setArtifact(null);
    setStatus("Ejecutando caso manual CyberLACE...");
    try {
      const response = await fetch(`${socketUrl}/api/harness/training/generate-run`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ scenario, caseId: normalizedCaseId || undefined }),
      });
      const payload = await response.json();
      if (!response.ok || payload?.ok === false) {
        throw new Error(payload?.message || payload?.error || "training_run_failed");
      }
      setResult(payload.result || payload);
      setLearningStatus(payload.safetyLearning?.status || payload.summary?.safetyLearning || payload.safetyLearning || null);
      setStatus(payload?.result?.passed ? "Caso generado y validado." : "Caso generado con fallas. Revisa el reporte.");
      await loadSummary();
    } catch (error) {
      setStatus(error?.message || "No se pudo ejecutar el entrenamiento.");
      setResult({ passed: false, failures: [error?.message || "training_run_failed"] });
    } finally {
      setRunning(false);
    }
  }

  async function wait(ms) {
    await new Promise((resolve) => setTimeout(resolve, ms));
  }

  async function runAutopilot(event) {
    event.preventDefault();
    const requestedTasks = Math.max(1, Math.min(Number(cycles) || 1, 1000));
    const requestedDelaySeconds = Math.max(1, Math.min(Number(taskDelaySeconds) || 8, 300));
    if (autopilotRunning && autopilotRunId) {
      setStatus("Solicitando detencion del loop autonomo...");
      try {
        await fetch(`${socketUrl}/api/harness/training/autopilot-stop/${encodeURIComponent(autopilotRunId)}`, { method: "POST" });
      } catch (error) {
        setStatus(error?.message || "No se pudo solicitar la detencion.");
      }
      return;
    }
    setAutopilotRunning(true);
    setHarnessTrainingAutomation(true, { campaignId: compactId(campaignId) || "auto" });
    setArtifact(null);
    setStatus("Preparando loop autonomo y agente generador...");
    setAutopilotResult({
      status: "queued",
      phase: "queued",
      message: "Preparando agente generador, memoria y cola de ciclos.",
      campaignId: compactId(campaignId) || "auto",
      cycles: requestedTasks,
      requestedTasks,
      taskDelaySeconds: requestedDelaySeconds,
      delayRemainingSeconds: 0,
      continuous: false,
      results: [],
      steps: [
        { phase: "queued", message: "Campana creada en UI; esperando aceptacion del backend.", status: "running" },
      ],
    });
    try {
      const response = await fetch(`${socketUrl}/api/harness/training/autopilot-start`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          campaignId: compactId(campaignId) || undefined,
          cycles: requestedTasks,
          taskDelaySeconds: requestedDelaySeconds,
          continuous: false,
          intensity,
          objective,
        }),
      });
      const payload = await response.json();
      if (!response.ok || payload?.ok === false) {
        throw new Error(payload?.message || payload?.error || "training_autopilot_start_failed");
      }

      let currentRun = payload.run;
      setAutopilotRunId(currentRun?.runId || "");
      setHarnessTrainingAutomation(true, { runId: currentRun?.runId, campaignId: currentRun?.campaignId });
      setAutopilotResult(currentRun);
      setStatus(currentRun?.message || "Loop autonomo iniciado.");

      for (let poll = 0; poll < 10000; poll += 1) {
        if (["completed", "failed", "stopped"].includes(currentRun?.status)) break;
        await wait(900);
        const statusResponse = await fetch(`${socketUrl}/api/harness/training/autopilot-status/${encodeURIComponent(currentRun.runId)}`);
        const statusPayload = await statusResponse.json();
        if (!statusResponse.ok || statusPayload?.ok === false) {
          throw new Error(statusPayload?.message || statusPayload?.error || "training_autopilot_status_failed");
        }
        currentRun = statusPayload.run;
        setAutopilotResult(currentRun);
        if (currentRun?.learningStatus) setLearningStatus(currentRun.learningStatus);
        setStatus(currentRun?.message || "Loop autonomo activo.");
      }

      if (currentRun?.status === "completed") {
        setStatus(currentRun?.passed ? "Campana autonoma completada sin fallas." : "Campana autonoma dejo evidencia de fallas. Revisa el reporte.");
      } else if (currentRun?.status === "stopped") {
        setStatus("Loop autonomo detenido por el usuario. Evidencia y memoria guardadas.");
      } else if (currentRun?.status === "failed") {
        setStatus(currentRun?.error || "Campana autonoma fallida. Revisa evidencia.");
      } else {
        setStatus("El loop sigue en proceso; consulta el estado o reportes generados.");
      }
      await loadSummary();
    } catch (error) {
      setStatus(error?.message || "No se pudo ejecutar el loop autonomo.");
      setAutopilotResult({ passed: false, status: "failed", failures: [error?.message || "training_autopilot_failed"] });
    } finally {
      setHarnessTrainingAutomation(false);
      setAutopilotRunning(false);
      setAutopilotRunId("");
    }
  }

  async function refreshSafetyLearning() {
    try {
      const response = await fetch(`${socketUrl}/api/harness/safety-learning/status`);
      const payload = await response.json();
      if (!response.ok || payload?.ok === false) {
        throw new Error(payload?.message || payload?.error || "safety_learning_status_failed");
      }
      setLearningStatus(payload);
      setLearningActionStatus("Safety Learning Core actualizado.");
    } catch (error) {
      setLearningActionStatus(error?.message || "No se pudo actualizar Safety Learning Core.");
    }
  }

  async function sendSafetyFeedback(label) {
    const experienceId = learningStatus?.lastExperience?.id || learningStatus?.model?.lastExperienceId || "";
    setLearningActionStatus("Registrando feedback humano...");
    try {
      const response = await fetch(`${socketUrl}/api/harness/safety-learning/feedback`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ experienceId, label, source: "harness-ui" }),
      });
      const payload = await response.json();
      if (!response.ok || payload?.ok === false) {
        throw new Error(payload?.message || payload?.error || "safety_feedback_failed");
      }
      setLearningStatus(payload.status || null);
      setLearningActionStatus(`Feedback registrado: ${label}`);
    } catch (error) {
      setLearningActionStatus(error?.message || "No se pudo registrar feedback.");
    }
  }

  async function queueSafetyRepair() {
    setLearningActionStatus("Registrando solicitud de reparacion gobernada...");
    try {
      const response = await fetch(`${socketUrl}/api/harness/safety-learning/repair-request`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          instruction: "Reparacion gobernada: revisar experiencia, parchear con worker autorizado, ejecutar build/tests/harness y dejar checkpoint.",
        }),
      });
      const payload = await response.json();
      if (!response.ok || payload?.ok === false) {
        throw new Error(payload?.message || payload?.error || "safety_repair_request_failed");
      }
      setLearningStatus(payload.status || null);
      setLearningActionStatus(`Reparacion en cola: ${payload.repairRequest?.id || "registrada"}`);
    } catch (error) {
      setLearningActionStatus(error?.message || "No se pudo registrar reparacion.");
    }
  }

  async function loadArtifact(path) {
    if (!path) return;
    setArtifactLoading(true);
    try {
      const response = await fetch(`${socketUrl}/api/harness/training/artifact?path=${encodeURIComponent(path)}`);
      const payload = await response.json();
      if (!response.ok || payload?.ok === false) {
        throw new Error(payload?.message || payload?.error || "artifact_load_failed");
      }
      setArtifact(payload);
    } catch (error) {
      setArtifact({ path, content: error?.message || "No se pudo cargar el artefacto." });
    } finally {
      setArtifactLoading(false);
    }
  }

  const latestReports = summary.reports || [];
  const latestCheckpoints = summary.checkpoints || [];
  const latestCases = summary.cases || [];
  const latestCampaigns = summary.campaigns || [];
  const campaignResults = Array.isArray(autopilotResult?.results) ? autopilotResult.results : [];
  const autopilotSteps = Array.isArray(autopilotResult?.steps) ? autopilotResult.steps : [];
  const learningRecommendation = learningStatus?.recommendation || learningStatus?.model?.lastRecommendation || null;
  const learningLast = learningStatus?.lastExperience || null;

  return (
    <section className="harness-studio-panel" aria-label="Harness Engineering Studio">
      <header className="harness-studio-header">
        <div>
          <span>HARNESS ENGINEERING STUDIO</span>
          <h2>CyberLACE Autonomous Security Training Loop</h2>
        </div>
        <button type="button" onClick={onClose}>Cerrar</button>
      </header>

      <div className="harness-studio-autopilot">
        <form className="harness-studio-runner" onSubmit={runAutopilot}>
          <label>
            <span>Campana ID opcional</span>
            <input value={campaignId} onChange={(event) => setCampaignId(event.target.value)} placeholder="campana-red-team-001" disabled={autopilotRunning} />
          </label>
          <label>
            <span>Tareas end-to-end del loop</span>
            <input
              type="number"
              min="1"
              max="1000"
              value={cycles}
              onChange={(event) => setCycles(event.target.value)}
