class AppErrorBoundary extends React.Component {
  constructor(props) {
    super(props);
    this.state = { error: null };
  }

  static getDerivedStateFromError(error) {
    return { error };
  }

  render() {
    if (!this.state.error) {
      return this.props.children;
    }

    return (
      <main className="runtime-error-screen">
        <section className="runtime-error-card">
          <p className="eyebrow">Frontend Error</p>
          <h1>La interfaz encontro un error de runtime</h1>
          <p>Recarga la pagina. Si el error persiste, comparte este mensaje para corregirlo mas rapido.</p>
          <pre>{String(this.state.error?.stack || this.state.error?.message || this.state.error)}</pre>
        </section>
      </main>
    );
  }
}

createRoot(document.getElementById("root")).render(
  <React.StrictMode>
    <AppErrorBoundary>
      <App />
    </AppErrorBoundary>
  </React.StrictMode>
);

{
  "name": "ecosystem-microservice-js",
  "version": "1.0.0",
  "private": true,
  "type": "module",
  "scripts": {
    "start": "node src/server.js",
    "sync": "node src/server.js --sync-once"
  }
}

const ARCHITECTURE_API =
  process.env.ARCHITECTURE_API || "http://127.0.0.1:5000/api/architecture";

export async function publishEcosystemPulse(snapshot) {
  const response = await fetch(ARCHITECTURE_API, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      "X-Ecosystem-Source": "microservice-js",
    },
    body: JSON.stringify({
      metadata: {
        source: "microservice-js",
        projectName: "Ecosystem Pulse",
        note: "Microservicio lateral que publica estado de workers y conecta el ecosistema.",
      },
      microserviceSnapshot: snapshot,
    }),
  });

  if (!response.ok) {
    throw new Error(`Architecture bridge failed with ${response.status}`);
  }

  return response.json();
}

import { collectRegistryStats, workerRegistry } from "./workerRegistry.js";

export function buildServiceSnapshot() {
  const stats = collectRegistryStats();

  const nodes = workerRegistry.map((worker) => ({
    id: worker.id,
    name: worker.id,
    domain: worker.domain,
    transport: worker.transport,
    status: worker.status,
  }));

  return {
    generatedAt: new Date().toISOString(),
    summary: stats,
    nodes,
  };
}

export function buildHealthReport() {
  const snapshot = buildServiceSnapshot();
  const degradedWorkers = snapshot.nodes.filter((worker) => worker.status !== "warm");

  return {
    status: degradedWorkers.length ? "degraded" : "healthy",
    summary: snapshot.summary,
    degradedWorkers,
  };
}

import { createServer } from "node:http";
import { buildHealthReport, buildServiceSnapshot } from "./catalogService.js";
import { publishEcosystemPulse } from "./architectureBridge.js";

const PORT = Number(process.env.MICROSERVICE_PORT || 6201);

async function syncOnce() {
  const snapshot = buildServiceSnapshot();
  await publishEcosystemPulse(snapshot);
  return snapshot;
}

const server = createServer(async (request, response) => {
  if (request.url === "/health") {
    const report = buildHealthReport();
    response.writeHead(200, { "Content-Type": "application/json" });
    response.end(JSON.stringify(report, null, 2));
    return;
  }

  if (request.url === "/sync") {
    const snapshot = await syncOnce();
    response.writeHead(200, { "Content-Type": "application/json" });
    response.end(JSON.stringify(snapshot, null, 2));
    return;
  }

  response.writeHead(200, { "Content-Type": "application/json" });
  response.end(
    JSON.stringify(
      {
        service: "ecosystem-microservice-js",
        endpoints: ["/health", "/sync"],
      },
      null,
      2
    )
  );
});

if (process.argv.includes("--sync-once")) {
  syncOnce()
    .then((snapshot) => {
      console.log("ecosystem pulse published", snapshot.summary);
    })
    .catch((error) => {
      console.error("ecosystem pulse failed", error);
      process.exitCode = 1;
    });
} else {
  server.listen(PORT, () => {
    console.log(`microservice-js listening on http://127.0.0.1:${PORT}`);
  });
}

