    }

    const rotors = [];
    const rotorGeometry = new THREE.TorusGeometry(0.58, 0.045, 8, 28);
    const bladeGeometry = new THREE.BoxGeometry(1.35, 0.035, 0.16);
    for (const x of [-2.35, 2.35]) {
